def file_sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def checked_range(data: bytes, offset: int, size: int, label: str) -> None:
    if offset < 0 or size < 0 or offset + size > len(data):
        raise ValueError(
            f"{label} range 0x{offset:X}+0x{size:X} is outside ELF")


def read_elf_vma(
    data: bytes,
    address: int,
    size: int,
    label: str,
) -> bytes:
    """Read one file-backed ELF64 PT_LOAD virtual-address range."""
    elf_header = struct.Struct("<16sHHIQQQIHHHHHH")
    program_header = struct.Struct("<IIQQQQQQ")
    checked_range(data, 0, elf_header.size, "ELF header")
    header = elf_header.unpack_from(data)
    ident = header[0]
    if ident[:4] != b"\x7fELF" or ident[4] != 2 or ident[5] != 1:
        raise ValueError("target is not a little-endian ELF64 image")
    if header[2] != 183:
        raise ValueError(f"target ELF machine is {header[2]}, expected AArch64")

    program_offset = header[5]
    program_entry_size = header[9]
    program_count = header[10]
    if program_entry_size != program_header.size:
        raise ValueError(
            f"ELF program-header size is {program_entry_size}, "
            f"expected {program_header.size}")
    if program_count == 0:
        raise ValueError("ELF contains no program headers")
    checked_range(
        data, program_offset, program_entry_size * program_count,
        "ELF program-header table",
    )

    mappings: list[int] = []
    for index in range(program_count):
        fields = program_header.unpack_from(
            data, program_offset + index * program_entry_size)
        segment_type, segment_offset = fields[0], fields[2]
        virtual_address, file_size = fields[3], fields[5]
        if segment_type != 1:  # PT_LOAD
            continue
        if virtual_address <= address and address + size <= (
            virtual_address + file_size
        ):
            mappings.append(segment_offset + address - virtual_address)
    if len(mappings) != 1:
        raise ValueError(
            f"{label} VMA 0x{address:X}+0x{size:X} maps to "
            f"{len(mappings)} file-backed PT_LOAD segments")
    checked_range(data, mappings[0], size, label)
    return data[mappings[0]:mappings[0] + size]


def read_elf_section_metadata(
    data: bytes,
    wanted_name: bytes,
) -> tuple[int, int, int, int, int]:
    """Return (type, flags, address, size, alignment) for one ELF section."""
    elf_header = struct.Struct("<16sHHIQQQIHHHHHH")
    section_header = struct.Struct("<IIQQQQIIQQ")
    checked_range(data, 0, elf_header.size, "ELF header")
    header = elf_header.unpack_from(data)
    ident = header[0]
    if ident[:4] != b"\x7fELF" or ident[4] != 2 or ident[5] != 1:
        raise ValueError("target is not a little-endian ELF64 image")
    if header[2] != 183:
        raise ValueError(f"target ELF machine is {header[2]}, expected AArch64")

    section_offset = header[6]
    section_entry_size = header[11]
    section_count = header[12]
    section_names_index = header[13]
    if section_entry_size != section_header.size:
        raise ValueError(
            f"ELF section-header size is {section_entry_size}, "
            f"expected {section_header.size}")
    if section_count == 0 or section_names_index >= section_count:
        raise ValueError("ELF uses an unsupported extended section table")
    checked_range(
        data, section_offset, section_entry_size * section_count,
        "ELF section table",
    )
    sections = [
        section_header.unpack_from(
            data, section_offset + index * section_entry_size)
        for index in range(section_count)
    ]
    names_header = sections[section_names_index]
    names_offset, names_size = names_header[4], names_header[5]
    checked_range(data, names_offset, names_size, "ELF section-name table")
    names = data[names_offset:names_offset + names_size]

    matches = []
    for fields in sections:
        name_offset = fields[0]
        if name_offset >= len(names):
            raise ValueError(
                f"ELF section name offset 0x{name_offset:X} is out of range")
        name_end = names.find(b"\0", name_offset)
        if name_end < 0:
            raise ValueError("unterminated ELF section name")
        if names[name_offset:name_end] == wanted_name:
            matches.append(fields)
    if len(matches) != 1:
        raise ValueError(
            f"expected one {wanted_name.decode()} section, "
            f"found {len(matches)}")
    fields = matches[0]
    return fields[1], fields[2], fields[3], fields[5], fields[8]


def read_elf_relocations(
    data: bytes,
    wanted_section: bytes,
) -> dict[int, tuple[int, int, str, int, int]]:
    """Return RELA entries as offset -> (type, addend, symbol, value, size)."""
    section_label = wanted_section.decode("ascii")
    elf_header = struct.Struct("<16sHHIQQQIHHHHHH")
    section_header = struct.Struct("<IIQQQQIIQQ")
    rela_entry = struct.Struct("<QQq")
    symbol_entry = struct.Struct("<IBBHQQ")
    checked_range(data, 0, elf_header.size, "ELF header")
    header = elf_header.unpack_from(data)
    ident = header[0]
    if ident[:4] != b"\x7fELF" or ident[4] != 2 or ident[5] != 1:
        raise ValueError("target is not a little-endian ELF64 image")
    if header[2] != 183:
        raise ValueError(f"target ELF machine is {header[2]}, expected AArch64")

    section_offset = header[6]
    section_entry_size = header[11]
    section_count = header[12]
    section_names_index = header[13]
    if section_entry_size != section_header.size:
        raise ValueError(
            f"ELF section-header size is {section_entry_size}, "
            f"expected {section_header.size}")
    if section_count == 0 or section_names_index >= section_count:
        raise ValueError("ELF uses an unsupported extended section table")
    checked_range(
        data, section_offset, section_entry_size * section_count,
        "ELF section table",
    )
    sections = [
        section_header.unpack_from(
            data, section_offset + index * section_entry_size)
        for index in range(section_count)
    ]
    names_header = sections[section_names_index]
    names_offset, names_size = names_header[4], names_header[5]
    checked_range(data, names_offset, names_size, "ELF section-name table")
    section_names = data[names_offset:names_offset + names_size]

    def section_name(index: int) -> bytes:
        name_offset = sections[index][0]
        if name_offset >= len(section_names):
            raise ValueError(
                f"ELF section name offset 0x{name_offset:X} is out of range")
        name_end = section_names.find(b"\0", name_offset)
        if name_end < 0:
            raise ValueError("unterminated ELF section name")
        return section_names[name_offset:name_end]

    rela_indices = [
        index for index in range(section_count)
        if section_name(index) == wanted_section
    ]
    if len(rela_indices) != 1:
        raise ValueError(
            f"expected one {section_label} section, "
            f"found {len(rela_indices)}")
    rela = sections[rela_indices[0]]
    if rela[1] != 4 or rela[9] != rela_entry.size:
        raise ValueError(
            f"{section_label} is not an ELF64 SHT_RELA table with "
            "24-byte entries")
    rela_offset, rela_size, symbol_index = rela[4], rela[5], rela[6]
    if rela_size % rela_entry.size or symbol_index >= section_count:
        raise ValueError(
            f"invalid {section_label} size or symbol-table link")
    checked_range(data, rela_offset, rela_size, section_label)

    symbols = sections[symbol_index]
    if symbols[1] != 11 or symbols[9] != symbol_entry.size:
        raise ValueError(
            f"{section_label} does not link to an ELF64 .dynsym table")
    symbol_offset, symbol_size, strings_index = (
        symbols[4], symbols[5], symbols[6]
    )
    if symbol_size % symbol_entry.size or strings_index >= section_count:
        raise ValueError("invalid .dynsym size or string-table link")
    checked_range(data, symbol_offset, symbol_size, ".dynsym")
    strings = sections[strings_index]
    if strings[1] != 3:
        raise ValueError(".dynsym does not link to an ELF string table")
    strings_offset, strings_size = strings[4], strings[5]
    checked_range(data, strings_offset, strings_size, ".dynstr")
    string_data = data[strings_offset:strings_offset + strings_size]
    symbol_count = symbol_size // symbol_entry.size

    def dynamic_symbol(index: int) -> tuple[str, int, int]:
        if index >= symbol_count:
            raise ValueError(
                f"dynamic relocation symbol index {index} is out of range")
        entry = symbol_entry.unpack_from(
            data, symbol_offset + index * symbol_entry.size)
        name_offset = entry[0]
        if name_offset >= len(string_data):
            raise ValueError(
                f"dynamic symbol name offset 0x{name_offset:X} is out of range")
        name_end = string_data.find(b"\0", name_offset)
        if name_end < 0:
            raise ValueError("unterminated dynamic symbol name")
        return (
            string_data[name_offset:name_end].decode("utf-8"),
            entry[4],
            entry[5],
        )

    relocations: dict[int, tuple[int, int, str, int, int]] = {}
    for entry_offset in range(rela_offset, rela_offset + rela_size,
                              rela_entry.size):
        target, info, addend = rela_entry.unpack_from(data, entry_offset)
        if target in relocations:
            raise ValueError(
                f"duplicate {section_label} relocation at 0x{target:X}")
        relocation_type = info & 0xFFFFFFFF
        symbol_name, symbol_value, symbol_size = dynamic_symbol(info >> 32)
        relocations[target] = (
            relocation_type,
            addend,
            symbol_name,
            symbol_value,
            symbol_size,
        )
    return relocations


def read_elf_dynamic_relocations(
    data: bytes,
) -> dict[int, tuple[int, int, str]]:
    """Return .rela.dyn entries as offset -> (type, addend, symbol)."""
    return {
        target: (relocation_type, addend, symbol_name)
        for target, (
            relocation_type,
            addend,
            symbol_name,
            _symbol_value,
            _symbol_size,
        ) in read_elf_relocations(data, b".rela.dyn").items()
    }


def verify_literal_surfaces(binary: Path) -> tuple[int, int, int]:
    data = binary.read_bytes()
    seen_addresses: set[int] = set()
    byte_count = 0
    for address, encoding, text in EXPECTED_LITERAL_SURFACES:
        if address in seen_addresses:
            raise ValueError(f"duplicate literal VMA 0x{address:X}")
        seen_addresses.add(address)
        if encoding not in {"utf-8", "utf-16le"}:
            raise ValueError(
                f"literal VMA 0x{address:X} has unsupported {encoding}")
        expected = (text + "\0").encode(encoding)
        actual = read_elf_vma(
            data, address, len(expected), f"{encoding} literal 0x{address:X}")
        if actual != expected:
            raise ValueError(
                f"{encoding} literal changed at VMA 0x{address:X}: "
                f"expected {expected.hex()}, got {actual.hex()}")
        byte_count += len(expected)

    for slot, expected in EXPECTED_LITERAL_POINTER_SURFACES:
        raw = read_elf_vma(data, slot, 8, f"literal pointer 0x{slot:X}")
        actual = struct.unpack("<Q", raw)[0]
        if actual != expected:
            raise ValueError(
                f"literal pointer changed at VMA 0x{slot:X}: "
                f"expected 0x{expected:X}, got 0x{actual:X}")
    return (
        len(EXPECTED_LITERAL_SURFACES),
        byte_count,
        len(EXPECTED_LITERAL_POINTER_SURFACES),
    )


def verify_switch_table_surfaces(
    binary: Path,
    fdes: dict[int, FdeRecord],
    manifest: set[int],
) -> tuple[int, int, int]:
    data = binary.read_bytes()
    seen_switches: set[int] = set()
    seen_tables: set[int] = set()
    total_entries = 0
    destinations: set[int] = set()
    for owner, switch, table, entry_count, expected_digest in (
        EXPECTED_SWITCH_TABLE_SURFACES
    ):
        if owner not in manifest:
            raise ValueError(
                f"switch 0x{switch:X} owner 0x{owner:X} is outside MANIFEST")
        record = fdes.get(owner)
        if record is None:
            raise ValueError(
                f"switch 0x{switch:X} owner 0x{owner:X} has no FDE")
        if not owner <= switch < record.end:
            raise ValueError(
                f"switch 0x{switch:X} is outside owner FDE "
                f"0x{owner:X}...0x{record.end:X}")
        if switch in seen_switches:
            raise ValueError(f"duplicate switch instruction 0x{switch:X}")
        if table in seen_tables:
            raise ValueError(f"duplicate switch-table VMA 0x{table:X}")
        if entry_count <= 0:
            raise ValueError(
                f"switch 0x{switch:X} has invalid entry count {entry_count}")
        seen_switches.add(switch)
        seen_tables.add(table)

        raw = read_elf_vma(
            data, table, entry_count * 4, f"switch table 0x{table:X}")
        actual_digest = hashlib.sha256(raw).hexdigest()
        if actual_digest != expected_digest:
            raise ValueError(
                f"switch table 0x{table:X} changed: expected "
                f"{expected_digest}, got {actual_digest}")
        for index, displacement in enumerate(
            struct.unpack(f"<{entry_count}i", raw)
        ):
            destination = table + displacement
            if destination & 3 or not owner <= destination < record.end:
                raise ValueError(
                    f"switch 0x{switch:X} case slot {index} resolves to "
                    f"0x{destination:X}, outside aligned owner FDE "
                    f"0x{owner:X}...0x{record.end:X}")
            destinations.add(destination)
        total_entries += entry_count
    return len(seen_switches), total_entries, len(destinations)


def verify_callsite_surface(
    binary: Path,
    fdes: dict[int, FdeRecord],
    manifest: set[int],
) -> dict[str, int]:
    data = binary.read_bytes()
    switch_dispatches = {
        switch for _, switch, _, _, _ in EXPECTED_SWITCH_TABLE_SURFACES
    }
    rows: list[tuple[int, int, int, int]] = []
    kind_counts: dict[int, int] = {}
    functions_with_transfer: set[int] = set()

    for owner in sorted(manifest):
        record = fdes.get(owner)
        if record is None:
            raise ValueError(f"callsite owner 0x{owner:X} has no FDE")
        size = record.end - owner
        if size <= 0 or size & 3:
            raise ValueError(
                f"callsite owner FDE 0x{owner:X}...0x{record.end:X} "
                "is not a positive AArch64 instruction range")
        raw = read_elf_vma(data, owner, size, f"function 0x{owner:X}")
        for offset in range(0, size, 4):
            address = owner + offset
            word = struct.unpack_from("<I", raw, offset)[0]
            kind: int | None = None
            value = 0

            if word & 0xFC000000 == 0x94000000:  # BL imm26
                kind = 1
                immediate = word & 0x03FFFFFF
                if immediate & 0x02000000:
                    immediate -= 1 << 26
                value = address + (immediate << 2)
            elif word & 0xFC000000 == 0x14000000:  # B imm26
                immediate = word & 0x03FFFFFF
                if immediate & 0x02000000:
                    immediate -= 1 << 26
                destination = address + (immediate << 2)
                if not owner <= destination < record.end:
                    kind = 2
                    value = destination
            elif word & 0xFFFFFC1F == 0xD63F0000:  # BLR Xn
                kind = 3
                value = (word >> 5) & 31
            elif word & 0xFFFFFC1F == 0xD61F0000:  # BR Xn
                kind = 5 if address in switch_dispatches else 4
                value = (word >> 5) & 31

            if kind is None:
                continue
            rows.append((owner, address, kind, value))
            kind_counts[kind] = kind_counts.get(kind, 0) + 1
            if kind != 5:
                functions_with_transfer.add(owner)

    if kind_counts != EXPECTED_CALLSITE_KIND_COUNTS:
        raise ValueError(
            f"callsite kind counts changed: expected "
            f"{EXPECTED_CALLSITE_KIND_COUNTS}, got {kind_counts}")
    observed_switches = {address for _, address, kind, _ in rows if kind == 5}
    if observed_switches != switch_dispatches:
        missing = sorted(switch_dispatches - observed_switches)
        extra = sorted(observed_switches - switch_dispatches)
        raise ValueError(
            "switch BR callsite set changed: "
            f"missing={','.join(f'0x{x:X}' for x in missing) or '-'} "
            f"extra={','.join(f'0x{x:X}' for x in extra) or '-'}")

    encoded = b"".join(
        struct.pack("<QQBQ", owner, address, kind, value)
        for owner, address, kind, value in rows
    )
    digest = hashlib.sha256(encoded).hexdigest()
    if digest != EXPECTED_CALLSITE_SURFACE_SHA256:
        raise ValueError(
            "callsite surface changed: expected "
            f"{EXPECTED_CALLSITE_SURFACE_SHA256}, got {digest}")

    direct = [row for row in rows if row[2] in {1, 2}]
    internal = [row for row in direct if row[3] in manifest]
    internal_edges = {(row[0], row[3]) for row in internal}
    if internal_edges != EXPECTED_INTERNAL_CALL_EDGES:
        missing = sorted(EXPECTED_INTERNAL_CALL_EDGES - internal_edges)
        extra = sorted(internal_edges - EXPECTED_INTERNAL_CALL_EDGES)
        format_edges = lambda edges: ",".join(
            f"0x{source:X}->0x{target:X}" for source, target in edges
        ) or "-"
        raise ValueError(
            "MANIFEST-internal call edges changed: "
            f"missing={format_edges(missing)} extra={format_edges(extra)}")

    expected_internal_sites = {
        (owner, site, kind, target)
        for owner, site, kind, target, _, _ in EXPECTED_INTERNAL_DIRECT_SITES
    }
    if len(expected_internal_sites) != len(EXPECTED_INTERNAL_DIRECT_SITES):
        raise ValueError("internal direct expectation contains duplicate sites")
    actual_internal_sites = set(internal)
    if actual_internal_sites != expected_internal_sites:
        missing = sorted(expected_internal_sites - actual_internal_sites)
        extra = sorted(actual_internal_sites - expected_internal_sites)
        format_sites = lambda sites: ",".join(
            f"0x{owner:X}:0x{site:X}->0x{target:X}/k{kind}"
            for owner, site, kind, target in sites
        ) or "-"
        raise ValueError(
            "MANIFEST-internal direct site set changed: "
            f"missing={format_sites(missing)} extra={format_sites(extra)}")

    internal_role_counts: dict[str, int] = {}
    internal_result_counts: dict[str, int] = {}
    site_owners: dict[int, int] = {}
    for owner, site, _, _, role, result_use in EXPECTED_INTERNAL_DIRECT_SITES:
        internal_role_counts[role] = internal_role_counts.get(role, 0) + 1
        internal_result_counts[result_use] = (
            internal_result_counts.get(result_use, 0) + 1)
        site_owners[site] = owner
    if internal_role_counts != EXPECTED_INTERNAL_DIRECT_ROLE_COUNTS:
        raise ValueError(
            "internal direct semantic role counts changed: expected "
            f"{EXPECTED_INTERNAL_DIRECT_ROLE_COUNTS}, "
            f"got {internal_role_counts}")
    if internal_result_counts != EXPECTED_INTERNAL_DIRECT_RESULT_COUNTS:
        raise ValueError(
            "internal direct result-use counts changed: expected "
            f"{EXPECTED_INTERNAL_DIRECT_RESULT_COUNTS}, "
            f"got {internal_result_counts}")

    abi_evidence_roles: set[str] = set()
    for site, producer, expected_word, register, role in \
            EXPECTED_INTERNAL_ABI_PRODUCERS:
        owner = site_owners.get(site)
        if owner is None:
            raise ValueError(
                f"internal ABI producer references unknown site 0x{site:X}")
        if not owner <= producer < site:
            raise ValueError(
                f"internal ABI producer 0x{producer:X} is outside call owner "
                f"0x{owner:X} before site 0x{site:X}")
        producer_word = struct.unpack(
            "<I", read_elf_vma(
                data, producer, 4,
                f"internal ABI producer 0x{producer:X}",
            ),
        )[0]
        if producer_word != expected_word:
            raise ValueError(
                f"internal ABI producer 0x{producer:X} changed: expected "
                f"0x{expected_word:08X}, got 0x{producer_word:08X}")
        if producer_word & 31 != register:
            raise ValueError(
                f"internal ABI producer 0x{producer:X} writes X/W"
                f"{producer_word & 31}, expected X/W{register}")
        if role in abi_evidence_roles:
            raise ValueError(
                f"duplicate internal ABI producer role {role}")
        abi_evidence_roles.add(role)

    external = [row for row in direct if row[3] not in manifest]
    external_counts: dict[int, int] = {}
    for _, _, _, target in external:
        external_counts[target] = external_counts.get(target, 0) + 1
    expected_external_counts = {
        target: count
        for target, count, _ in EXPECTED_EXTERNAL_DIRECT_TARGETS
    }
    if len(expected_external_counts) != len(EXPECTED_EXTERNAL_DIRECT_TARGETS):
        raise ValueError("external direct target expectation has duplicates")
    if external_counts != expected_external_counts:
        missing = sorted(
            set(expected_external_counts) - set(external_counts))
        extra = sorted(set(external_counts) - set(expected_external_counts))
        changed = sorted(
            target for target in set(external_counts) &
            set(expected_external_counts)
            if external_counts[target] != expected_external_counts[target]
        )
        raise ValueError(
            "external direct target surface changed: "
            f"missing={','.join(f'0x{x:X}' for x in missing) or '-'} "
            f"extra={','.join(f'0x{x:X}' for x in extra) or '-'} "
            f"changed={','.join(f'0x{x:X}' for x in changed) or '-'}")

    role_counts: dict[str, tuple[int, int]] = {}
    for target, count, role in EXPECTED_EXTERNAL_DIRECT_TARGETS:
        target_count, site_count = role_counts.get(role, (0, 0))
        role_counts[role] = (target_count + 1, site_count + count)
    if role_counts != EXPECTED_EXTERNAL_DIRECT_ROLE_COUNTS:
        raise ValueError(
            "external direct semantic role counts changed: expected "
            f"{EXPECTED_EXTERNAL_DIRECT_ROLE_COUNTS}, got {role_counts}")

    return {
        "sites": len(rows),
        "direct_targets": len({row[3] for row in direct}),
        "internal_sites": len(internal),
        "internal_edges": len(internal_edges),
        "internal_roles": len(internal_role_counts),
        "internal_result_uses": len(internal_result_counts),
        "internal_abi_producers": len(abi_evidence_roles),
        "internal_hidden_sret": internal_result_counts["hidden-sret"],
        "internal_direct_tails": sum(1 for row in internal if row[2] == 2),
        "external_sites": len(external),
        "external_targets": len(external_counts),
        "external_roles": len(role_counts),
        "no_transfer_functions": len(manifest - functions_with_transfer),
    }


def verify_external_consumer_surface(
    binary: Path,
    fdes: dict[int, FdeRecord],
    manifest: set[int],
) -> dict[str, int]:
    """Verify every real direct caller into the MANIFEST from ELF .text."""
    data = binary.read_bytes()
    section_type, section_flags, text_start, text_size, text_alignment = \
        read_elf_section_metadata(data, b".text")
    if section_type != 1 or not section_flags & 0x4:
        raise ValueError("ELF .text is not executable SHT_PROGBITS")
    if text_alignment < 4 or text_size % 4:
        raise ValueError("ELF .text has invalid AArch64 alignment or size")
    text = read_elf_vma(data, text_start, text_size, "ELF .text")
    fde_starts = sorted(fdes)

    def direct_branch_target(address: int, word: int) -> tuple[int, int] | None:
        if word & 0x7C000000 != 0x14000000:
            return None
        immediate = word & 0x03FFFFFF
        if immediate & 0x02000000:
            immediate -= 1 << 26
        kind = 1 if word & 0x80000000 else 2
        return address + (immediate << 2), kind

    rows: list[tuple[int, int, int, int, int]] = []
    for offset in range(0, len(text), 4):
        word = struct.unpack_from("<I", text, offset)[0]
        decoded = direct_branch_target(text_start + offset, word)
        if decoded is None or decoded[0] not in manifest:
            continue
        site = text_start + offset
        owner_index = bisect.bisect_right(fde_starts, site) - 1
        if owner_index < 0:
            raise ValueError(
                f"external consumer site 0x{site:X} has no preceding FDE")
        owner = fde_starts[owner_index]
        if site >= fdes[owner].end:
            raise ValueError(
                f"external consumer site 0x{site:X} is outside every FDE")
        if owner in manifest:
            continue
        target, kind = decoded
        rows.append((target, site, owner, word, kind))
    rows.sort()

    target_counts: dict[int, int] = {}
    owner_counts: dict[int, int] = {}
    for target, _, owner, _, _ in rows:
        target_counts[target] = target_counts.get(target, 0) + 1
        owner_counts[owner] = owner_counts.get(owner, 0) + 1
    expected_target_counts = {
        target: count
        for target, count, _ in EXPECTED_EXTERNAL_CONSUMER_TARGETS
    }
    expected_owner_counts = {
        owner: count
        for owner, count, _ in EXPECTED_EXTERNAL_CONSUMER_OWNERS
    }
    if len(expected_target_counts) != len(EXPECTED_EXTERNAL_CONSUMER_TARGETS):
        raise ValueError("external consumer target expectation has duplicates")
    if len(expected_owner_counts) != len(EXPECTED_EXTERNAL_CONSUMER_OWNERS):
        raise ValueError("external consumer owner expectation has duplicates")
    if target_counts != expected_target_counts:
        raise ValueError(
            "external consumer target counts changed: expected "
            f"{expected_target_counts}, got {target_counts}")
    if owner_counts != expected_owner_counts:
        raise ValueError(
            "external consumer owner counts changed: expected "
            f"{expected_owner_counts}, got {owner_counts}")

    counts = {
        "sites": len(rows),
        "targets": len(target_counts),
        "owners": len(owner_counts),
        "owner_target_pairs": len({
            (owner, target) for target, _, owner, _, _ in rows
        }),
        "direct_calls": sum(1 for *_, kind in rows if kind == 1),
        "direct_tails": sum(1 for *_, kind in rows if kind == 2),
    }
    if counts != EXPECTED_EXTERNAL_CONSUMER_COUNTS:
        raise ValueError(
            "external consumer aggregate changed: expected "
            f"{EXPECTED_EXTERNAL_CONSUMER_COUNTS}, got {counts}")
    encoded = b"".join(
        struct.pack("<QQQIB", target, site, owner, word, kind)
        for target, site, owner, word, kind in rows
    )
    if len(encoded) != EXPECTED_EXTERNAL_CONSUMER_RAW_BYTES:
        raise ValueError(
            "external consumer canonical byte count changed: expected "
            f"{EXPECTED_EXTERNAL_CONSUMER_RAW_BYTES}, got {len(encoded)}")
    digest = hashlib.sha256(encoded).hexdigest()
    if digest != EXPECTED_EXTERNAL_CONSUMER_SHA256:
        raise ValueError(
            "external consumer canonical digest changed: expected "
            f"{EXPECTED_EXTERNAL_CONSUMER_SHA256}, got {digest}")

    row_sites = {
        (owner, site, target)
        for target, site, owner, _, _ in rows
    }
    expected_release_sites = {
        (owner, site, 0x598B3C)
        for owner, site, _ in EXPECTED_EXTERNAL_CONSUMER_RAW_RELEASE_SITES
    }
    if not expected_release_sites <= row_sites:
        missing = sorted(expected_release_sites - row_sites)
        raise ValueError(
            "external consumer raw-release sites changed: "
            + ",".join(
                f"0x{owner:X}:0x{site:X}->0x{target:X}"
                for owner, site, target in missing
            ))

    lifetime_roles: set[str] = set()
    for owner, expected_end, role in EXPECTED_EXTERNAL_CONSUMER_LIFETIME_FDES:
        record = fdes.get(owner)
        if record is None or record.end != expected_end:
            actual = "missing" if record is None else f"0x{record.end:X}"
            raise ValueError(
                f"external consumer lifetime FDE {role} 0x{owner:X} ends "
                f"at {actual}, expected 0x{expected_end:X}")
        if role in lifetime_roles:
            raise ValueError(
                f"duplicate external consumer lifetime role {role}")
        lifetime_roles.add(role)

    helper_roles: set[str] = set()
    for owner, site, expected_target, role in \
            EXPECTED_EXTERNAL_CONSUMER_HELPER_EDGES:
        record = fdes.get(owner)
        if record is None or not owner <= site < record.end:
            raise ValueError(
                f"external consumer helper edge 0x{site:X} escapes "
                f"owner 0x{owner:X}")
        word = struct.unpack(
            "<I", read_elf_vma(data, site, 4, f"helper edge 0x{site:X}"),
        )[0]
        decoded = direct_branch_target(site, word)
        if decoded != (expected_target, 1):
            raise ValueError(
                f"external consumer helper edge {role} changed at "
                f"0x{site:X}: got {decoded!r}")
        if role in helper_roles:
            raise ValueError(f"duplicate external consumer helper role {role}")
        helper_roles.add(role)

    adaptor_raw = read_elf_vma(
        data,
        0x1A21F38,
        8 * len(EXPECTED_EXTERNAL_CONSUMER_ADAPTOR_VTABLE),
        "ObjSource adaptor vtable",
    )
    adaptor_qwords = struct.unpack(
        f"<{len(EXPECTED_EXTERNAL_CONSUMER_ADAPTOR_VTABLE)}Q", adaptor_raw)
    if adaptor_qwords != EXPECTED_EXTERNAL_CONSUMER_ADAPTOR_VTABLE:
        raise ValueError(
            "ObjSource adaptor vtable changed: expected "
            f"{EXPECTED_EXTERNAL_CONSUMER_ADAPTOR_VTABLE}, "
            f"got {adaptor_qwords}")

    plt_relocations = read_elf_relocations(data, b".rela.plt")
    plt_alias_roles = 0
    for stub, got_slot, symbol, target, symbol_size, expected_words in \
            EXPECTED_EXTERNAL_CONSUMER_PLT_ALIASES:
        words = struct.unpack(
            "<4I", read_elf_vma(data, stub, 16, f"PLT alias 0x{stub:X}"))
        if words != expected_words:
            raise ValueError(
                f"external consumer PLT alias 0x{stub:X} changed")
        if any(direct_branch_target(stub + index * 4, word) is not None
               for index, word in enumerate(words)):
            raise ValueError(
                f"external consumer PLT alias 0x{stub:X} became direct")
        ldr_slot = decode_aarch64_adrp_page(stub, words[0]) + \
            (((words[1] >> 10) & 0xFFF) * 8)
        if ldr_slot != got_slot:
            raise ValueError(
                f"external consumer PLT alias 0x{stub:X} loads "
                f"0x{ldr_slot:X}, expected 0x{got_slot:X}")
        expected_relocation = (1026, 0, symbol, target, symbol_size)
        if plt_relocations.get(got_slot) != expected_relocation:
            raise ValueError(
                f"external consumer PLT relocation at 0x{got_slot:X} "
                f"changed: got {plt_relocations.get(got_slot)!r}")
        if text_start <= stub < text_start + text_size:
            raise ValueError(
                f"external consumer PLT alias 0x{stub:X} entered .text")
        plt_alias_roles += 1

    return {
        **counts,
        "target_roles": len({
            role for _, _, role in EXPECTED_EXTERNAL_CONSUMER_TARGETS
        }),
        "owner_roles": len({
            role for _, _, role in EXPECTED_EXTERNAL_CONSUMER_OWNERS
        }),
        "lifetime_fdes": len(lifetime_roles),
        "raw_release_sites": len(expected_release_sites),
        "helper_edges": len(helper_roles),
        "adaptor_qwords": len(adaptor_qwords),
        "plt_aliases": plt_alias_roles,
    }


def verify_inverse_pointer_reference_surface(
    binary: Path,
    fdes: dict[int, FdeRecord],
    manifest: set[int],
) -> dict[str, int]:
    """Verify every static code pointer/address materialization into MANIFEST."""
    data = binary.read_bytes()
    section_type, section_flags, text_start, text_size, text_alignment = \
        read_elf_section_metadata(data, b".text")
    if section_type != 1 or not section_flags & 0x4:
        raise ValueError("inverse pointer .text is not executable PROGBITS")
    if text_alignment < 4 or text_size % 4:
        raise ValueError("inverse pointer .text has invalid alignment or size")
    text = read_elf_vma(data, text_start, text_size, "inverse pointer .text")
    text_end = text_start + text_size
    manifest_pages = {target & ~0xFFF for target in manifest}
    fde_starts = sorted(fdes)

    def sign_extend(value: int, bits: int) -> int:
        sign = 1 << (bits - 1)
        return value - (1 << bits) if value & sign else value

    def owner_at(site: int) -> int:
        index = bisect.bisect_right(fde_starts, site) - 1
        if index < 0:
            raise ValueError(
                f"inverse pointer site 0x{site:X} has no preceding FDE")
        owner = fde_starts[index]
        if site >= fdes[owner].end:
            raise ValueError(
                f"inverse pointer site 0x{site:X} is outside every FDE")
        return owner

    expected_candidates = EXPECTED_INVERSE_POINTER_PAGE_CANDIDATES
    expected_sites = {row[0] for row in expected_candidates}
    if len(expected_sites) != len(expected_candidates):
        raise ValueError("inverse pointer ADRP candidates contain duplicates")
    observed_candidates: dict[int, tuple[int, int]] = {}
    for offset in range(0, len(text), 4):
        site = text_start + offset
        word = struct.unpack_from("<I", text, offset)[0]
        if word & 0x9F000000 != 0x90000000:
            continue
        page = decode_aarch64_adrp_page(site, word)
        if page in manifest_pages:
            observed_candidates[site] = (page, word)
    if set(observed_candidates) != expected_sites:
        missing = sorted(expected_sites - set(observed_candidates))
        extra = sorted(set(observed_candidates) - expected_sites)
        raise ValueError(
            "inverse pointer ADRP page candidates changed: "
            f"missing={','.join(f'0x{x:X}' for x in missing) or '-'} "
            f"extra={','.join(f'0x{x:X}' for x in extra) or '-'}")

    materialization_owners: set[int] = set()
    external_materialization_owners: set[int] = set()
    manifest_targets: set[int] = set()
    page_collisions = 0
    canonical = bytearray()
    for site, expected_owner, add_site, target, expected_adrp, \
            expected_add, _role, target_is_manifest in expected_candidates:
        page, actual_adrp = observed_candidates[site]
        actual_add = struct.unpack(
            "<I", read_elf_vma(
                data, add_site, 4,
                f"inverse pointer ADD 0x{add_site:X}",
            ),
        )[0]
        if (actual_adrp, actual_add) != (expected_adrp, expected_add):
            raise ValueError(
                f"inverse pointer materialization changed at 0x{site:X}")
        if owner_at(site) != expected_owner or owner_at(add_site) != \
                expected_owner:
            raise ValueError(
                f"inverse pointer materialization escaped owner "
                f"0x{expected_owner:X}")
        if actual_add & 0x7F000000 != 0x11000000:
            raise ValueError(
                f"inverse pointer ADD encoding changed at 0x{add_site:X}")
        adrp_register = actual_adrp & 31
        if ((actual_add >> 5) & 31) != adrp_register or \
                (actual_add & 31) != adrp_register:
            raise ValueError(
                f"inverse pointer register chain changed at 0x{site:X}")
        shift = 12 if actual_add & (1 << 22) else 0
        resolved = page + (((actual_add >> 10) & 0xFFF) << shift)
        if resolved != target:
            raise ValueError(
                f"inverse pointer target changed at 0x{site:X}: "
                f"expected 0x{target:X}, got 0x{resolved:X}")
        if (target in manifest) != target_is_manifest:
            raise ValueError(
                f"inverse pointer MANIFEST classification changed at "
                f"0x{site:X}")
        if target_is_manifest:
            manifest_targets.add(target)
            materialization_owners.add(expected_owner)
            if expected_owner not in manifest:
                external_materialization_owners.add(expected_owner)
        else:
            page_collisions += 1
        canonical.extend(struct.pack(
            "<BQQQQIIB", 1, target, expected_owner, site, add_site,
            actual_adrp, actual_add, int(target_is_manifest),
        ))

    # ADR, general-register literal loads, move-wide sequences, and logical
    # immediate MOV aliases are the remaining non-relocation ways this image
    # can embed a complete low-address function pointer in .text.  None may
    # resolve to a MANIFEST entry outside the ADRP/ADD set above.
    adr_matches: set[tuple[int, int]] = set()
    literal_matches: set[tuple[int, int, int]] = set()
    move_wide_matches: set[tuple[int, int]] = set()
    logical_matches: set[tuple[int, int]] = set()

    elf_header = struct.Struct("<16sHHIQQQIHHHHHH")
    program_header = struct.Struct("<IIQQQQQQ")
    header = elf_header.unpack_from(data)
    load_mappings: list[tuple[int, int, int]] = []
    for index in range(header[10]):
        fields = program_header.unpack_from(
            data, header[5] + index * header[9])
        if fields[0] == 1:  # PT_LOAD
            load_mappings.append((fields[3], fields[3] + fields[5], fields[2]))

    def loaded_value(address: int, width: int) -> int | None:
        matches = [
            offset + address - start
            for start, end, offset in load_mappings
            if start <= address and address + width <= end
        ]
        if len(matches) != 1:
            return None
        checked_range(data, matches[0], width, "inverse literal value")
        return int.from_bytes(data[matches[0]:matches[0] + width], "little")

    def logical_immediate(word: int, width: int) -> int | None:
        n = (word >> 22) & 1
        if width == 32 and n:
            return None
        immr = (word >> 16) & 0x3F
        imms = (word >> 10) & 0x3F
        length_source = (n << 6) | ((~imms) & 0x3F)
        length = length_source.bit_length() - 1
        if length < 1:
            return None
        levels = (1 << length) - 1
        element_bits = 1 << length
        if element_bits > width:
            return None
        s = imms & levels
        r = immr & levels
        if s == levels:
            return None
        element_mask = (1 << element_bits) - 1
        element = (1 << (s + 1)) - 1
        if r:
            element = (
                (element >> r) | (element << (element_bits - r))
            ) & element_mask
        value = 0
        for bit in range(0, width, element_bits):
            value |= element << bit
        return value & ((1 << width) - 1)

    for offset in range(0, len(text), 4):
        site = text_start + offset
        word = struct.unpack_from("<I", text, offset)[0]
        if word & 0x9F000000 == 0x10000000:
            immediate = (((word >> 5) & 0x7FFFF) << 2) | \
                ((word >> 29) & 3)
            target = site + sign_extend(immediate, 21)
            if target in manifest:
                adr_matches.add((site, target))
        if word & 0xFF000000 in (0x18000000, 0x58000000):
            immediate = sign_extend((word >> 5) & 0x7FFFF, 19) << 2
            literal = site + immediate
            width = 8 if word & (1 << 30) else 4
            target = loaded_value(literal, width)
            if target in manifest:
                literal_matches.add((site, literal, target))

        move_kind = word & 0x7F800000
        if move_kind in (0x12800000, 0x52800000):
            sf = (word >> 31) & 1
            width = 64 if sf else 32
            value_mask = (1 << width) - 1
            shift = ((word >> 21) & 3) * 16
            if shift < width:
                immediate = ((word >> 5) & 0xFFFF) << shift
                value = (~immediate) & value_mask \
                    if move_kind == 0x12800000 else immediate
                if value in manifest:
                    move_wide_matches.add((site, value))
                register = word & 31
                for distance in range(4, 68, 4):
                    if offset + distance + 4 > len(text):
                        break
                    following = struct.unpack_from(
                        "<I", text, offset + distance)[0]
                    if following & 0x7F800000 != 0x72800000 or \
                            ((following >> 31) & 1) != sf or \
                            (following & 31) != register:
                        continue
                    following_shift = ((following >> 21) & 3) * 16
                    if following_shift >= width:
                        continue
                    value = (
                        value & ~(0xFFFF << following_shift)
                    ) | (((following >> 5) & 0xFFFF) << following_shift)
                    value &= value_mask
                    if value in manifest:
                        move_wide_matches.add((site, value))

        if word & 0x7F800000 == 0x32000000 and \
                ((word >> 5) & 31) == 31:
            width = 64 if word & (1 << 31) else 32
            target = logical_immediate(word, width)
            if target in manifest:
                logical_matches.add((site, target))

    unexpected_forms = {
        "ADR": adr_matches,
        "LDR-literal": literal_matches,
        "MOV-wide": move_wide_matches,
        "logical-immediate": logical_matches,
    }
    for form, matches in unexpected_forms.items():
        if matches:
            raise ValueError(
                f"inverse pointer gained {form} MANIFEST references: "
                f"{sorted(matches)!r}")

    # In an ET_DYN image every runtime absolute code pointer requires a dynamic
    # relocation.  The complete .rela.dyn addend scan must therefore equal the
    # MANIFEST-valued qwords already pinned in the ten static surfaces: two
    # init-array entries plus 60 psbfile vtable slots.
    expected_relative_slots: dict[int, int] = {}
    for _name, start, qwords in EXPECTED_STATIC_QWORD_SURFACES:
        for index, target in enumerate(qwords):
            if target in manifest:
                expected_relative_slots[start + index * 8] = target
    dynamic_relocations = read_elf_relocations(data, b".rela.dyn")
    relative_rows = {
        slot: row for slot, row in dynamic_relocations.items()
        if row[1] in manifest
    }
    if {slot: row[1] for slot, row in relative_rows.items()} != \
            expected_relative_slots:
        raise ValueError(
            "inverse pointer relative relocation slots changed")
    if any(row[3] in manifest for row in dynamic_relocations.values()):
        raise ValueError(
            "inverse pointer gained a .rela.dyn MANIFEST symbol reference")

    init_start, init_size = read_elf_section_metadata(
        data, b".init_array")[2:4]
    relro_start, relro_size = read_elf_section_metadata(
        data, b".data.rel.ro")[2:4]
    init_array_slots = 0
    vtable_slots = 0
    for slot, target in sorted(expected_relative_slots.items()):
        relocation = relative_rows[slot]
        if relocation != (1027, target, "", 0, 0):
            raise ValueError(
                f"inverse pointer relocation changed at 0x{slot:X}: "
                f"got {relocation!r}")
        raw_target = struct.unpack(
            "<Q", read_elf_vma(
                data, slot, 8,
                f"inverse pointer slot 0x{slot:X}",
            ),
        )[0]
        if raw_target != target:
            raise ValueError(
                f"inverse pointer qword changed at 0x{slot:X}")
        if init_start <= slot < init_start + init_size:
            init_array_slots += 1
        elif relro_start <= slot < relro_start + relro_size:
            vtable_slots += 1
        else:
            raise ValueError(
                f"inverse pointer relative slot 0x{slot:X} escaped "
                ".init_array/.data.rel.ro")
        manifest_targets.add(target)
        canonical.extend(struct.pack("<BQQI", 2, slot, target, 1027))

    # Weak local STL definitions are the only dynamic-symbol-valued MANIFEST
    # references.  They are JUMP_SLOT aliases whose four-word PLT stubs were
    # independently proven non-direct by verify_external_consumer_surface.
    plt_relocations = read_elf_relocations(data, b".rela.plt")
    observed_alias_slots = {
        slot: row for slot, row in plt_relocations.items()
        if row[3] in manifest
    }
    if any(row[1] in manifest for row in plt_relocations.values()):
        raise ValueError(
            "inverse pointer gained a .rela.plt MANIFEST addend reference")
    expected_alias_slots = {
        slot: (1026, 0, symbol, target, symbol_size, stub)
        for stub, slot, symbol, target, symbol_size, _words
        in EXPECTED_EXTERNAL_CONSUMER_PLT_ALIASES
    }
    if {
        slot: (*row, next(
            stub for stub, expected_slot, *_
            in EXPECTED_EXTERNAL_CONSUMER_PLT_ALIASES
            if expected_slot == slot
        ))
        for slot, row in observed_alias_slots.items()
    } != expected_alias_slots:
        raise ValueError("inverse pointer PLT alias set changed")
    for slot in sorted(expected_alias_slots):
        relocation_type, _addend, _symbol, target, symbol_size, stub = \
            expected_alias_slots[slot]
        raw_initializer = struct.unpack(
            "<Q", read_elf_vma(
                data, slot, 8,
                f"inverse pointer PLT slot 0x{slot:X}",
            ),
        )[0]
        # The file image contains PLT0 in both lazy JUMP_SLOT cells.  IDA's
        # live process view may show the loader-resolved weak local definition,
        # but that runtime mutation is not an initialized ELF pointer.
        if raw_initializer != 0x3FEDC0:
            raise ValueError(
                f"inverse pointer PLT initializer 0x{slot:X} changed")
        manifest_targets.add(target)
        canonical.extend(struct.pack(
            "<BQQQII", 3, stub, slot, target,
            relocation_type, symbol_size,
        ))

    counts = {
        "page_candidates": len(observed_candidates),
        "manifest_materializations": sum(
            int(row[7]) for row in expected_candidates),
        "materialization_owners": len(materialization_owners),
        "external_materialization_owners": len(
            external_materialization_owners),
        "page_collisions": page_collisions,
        "adr": len(adr_matches),
        "ldr_literal": len(literal_matches),
        "mov_wide": len(move_wide_matches),
        "logical_immediate": len(logical_matches),
        "relative_slots": len(relative_rows),
        "init_array_slots": init_array_slots,
        "vtable_slots": vtable_slots,
        "plt_alias_slots": len(observed_alias_slots),
        "targets": len(manifest_targets),
    }
    if counts != EXPECTED_INVERSE_POINTER_COUNTS:
        raise ValueError(
            "inverse pointer aggregate changed: expected "
            f"{EXPECTED_INVERSE_POINTER_COUNTS}, got {counts}")
    if len(canonical) != EXPECTED_INVERSE_POINTER_RAW_BYTES:
        raise ValueError(
            "inverse pointer canonical byte count changed: expected "
            f"{EXPECTED_INVERSE_POINTER_RAW_BYTES}, got {len(canonical)}")
    digest = hashlib.sha256(canonical).hexdigest()
    if digest != EXPECTED_INVERSE_POINTER_SHA256:
        raise ValueError(
            "inverse pointer canonical digest changed: expected "
            f"{EXPECTED_INVERSE_POINTER_SHA256}, got {digest}")
    return counts


def verify_owner_filter_bridge_surface(
    binary: Path,
    fdes: dict[int, FdeRecord],
    manifest: set[int],
) -> dict[str, int]:
    """Verify the complete motionplayer -> psbfile OwnerFilter bridge."""
    data = binary.read_bytes()
    expected_fde_starts = {
        start for start, _end, _role in EXPECTED_OWNER_FILTER_BRIDGE_FDES
    }
    if len(expected_fde_starts) != len(EXPECTED_OWNER_FILTER_BRIDGE_FDES):
        raise ValueError("OwnerFilter bridge FDE expectation has duplicates")
    for start, end, _role in EXPECTED_OWNER_FILTER_BRIDGE_FDES:
        record = fdes.get(start)
        if record is None or record.end != end:
            actual = None if record is None else record.end
            raise ValueError(
                f"OwnerFilter bridge FDE 0x{start:X} changed: expected "
                f"end 0x{end:X}, got "
                f"{('-' if actual is None else f'0x{actual:X}')}"
            )

    # 0x6A87D0 and 0x6A87E8 are adjacent but independent FDEs.  This rejects
    # the old IDA merge that flattened the TU helper and std::function
    # copy-assignment into one apparent function.
    if fdes[0x6A87D0].end != 0x6A87E8 or \
            fdes[0x6A87E8].end != 0x6A88CC:
        raise ValueError("OwnerFilter replacement/copy-assignment FDE split changed")

    bss_type, bss_flags, bss_start, bss_size, bss_alignment = \
        read_elf_section_metadata(data, b".bss")
    filter_address = 0x1AB82E0
    filter_size = 0x20
    if bss_type != 8 or bss_flags & 0x3 != 0x3:
        raise ValueError("OwnerFilter object is not in writable allocated NOBITS")
    if bss_alignment < 8 or not (
        bss_start <= filter_address
        and filter_address + filter_size <= bss_start + bss_size
    ):
        raise ValueError("OwnerFilter 32-byte object escaped .bss")

    canonical = bytearray()

    def add_canonical(tag: int, role: str, *values: int) -> None:
        encoded_role = role.encode("utf-8")
        if len(encoded_role) > 0xFFFF:
            raise ValueError("OwnerFilter canonical role is too long")
        canonical.extend(struct.pack("<BH", tag, len(encoded_role)))
        canonical.extend(encoded_role)
        canonical.extend(struct.pack("<" + "Q" * len(values), *values))

    for start, end, role in EXPECTED_OWNER_FILTER_BRIDGE_FDES:
        add_canonical(1, role, start, end)

    section_type, section_flags, text_start, text_size, text_alignment = \
        read_elf_section_metadata(data, b".text")
    if section_type != 1 or not section_flags & 0x4:
        raise ValueError("OwnerFilter bridge .text is not executable PROGBITS")
    if text_alignment < 4 or text_size % 4:
        raise ValueError("OwnerFilter bridge .text has invalid alignment or size")
    text = read_elf_vma(data, text_start, text_size, "OwnerFilter .text")

    def instruction_word(site: int) -> int:
        if site & 3 or not text_start <= site < text_start + text_size:
            raise ValueError(
                f"OwnerFilter instruction 0x{site:X} escaped .text")
        return struct.unpack_from("<I", text, site - text_start)[0]

    def owner_contains(owner: int, site: int) -> bool:
        record = fdes.get(owner)
        return record is not None and owner <= site < record.end

    def decode_add_target(page: int, adrp_word: int, add_word: int) -> int:
        if adrp_word & 0x9F000000 != 0x90000000:
            raise ValueError("OwnerFilter materialization lost ADRP")
        if add_word & 0xFF000000 != 0x91000000:
            raise ValueError("OwnerFilter materialization lost 64-bit ADD")
        register = adrp_word & 31
        if ((add_word >> 5) & 31) != register or add_word & 31 != register:
            raise ValueError("OwnerFilter ADRP/ADD register chain changed")
        shift = 12 if add_word & (1 << 22) else 0
        return page + (((add_word >> 10) & 0xFFF) << shift)

    expected_materialization_sites: set[tuple[int, int, int]] = set()
    for owner, adrp_site, add_site, target, expected_adrp, expected_add, \
            role in EXPECTED_OWNER_FILTER_MATERIALIZATIONS:
        if not owner_contains(owner, adrp_site) or \
                not owner_contains(owner, add_site):
            raise ValueError(
                f"OwnerFilter materialization escaped owner 0x{owner:X}")
        actual_adrp = instruction_word(adrp_site)
        actual_add = instruction_word(add_site)
        if (actual_adrp, actual_add) != (expected_adrp, expected_add):
            raise ValueError(
                f"OwnerFilter materialization changed at 0x{adrp_site:X}")
        page = decode_aarch64_adrp_page(adrp_site, actual_adrp)
        resolved = decode_add_target(page, actual_adrp, actual_add)
        if resolved != target:
            raise ValueError(
                f"OwnerFilter materialization 0x{adrp_site:X} resolves to "
                f"0x{resolved:X}, expected 0x{target:X}")
        key = (adrp_site, add_site, target)
        if key in expected_materialization_sites:
            raise ValueError("OwnerFilter materialization expectation duplicates")
        expected_materialization_sites.add(key)
        add_canonical(
            2, role, owner, adrp_site, add_site, target,
            actual_adrp, actual_add,
        )

    def scan_materializations(
        starts_ends: tuple[tuple[int, int], ...],
        targets: frozenset[int],
    ) -> set[tuple[int, int, int]]:
        rows: set[tuple[int, int, int]] = set()
        target_pages = {target & ~0xFFF for target in targets}
        for start, end in starts_ends:
            if start & 3 or end & 3 or start > end:
                raise ValueError("OwnerFilter scan range is invalid")
            for adrp_site in range(start, end, 4):
                adrp_word = instruction_word(adrp_site)
                if adrp_word & 0x9F000000 != 0x90000000:
                    continue
                page = decode_aarch64_adrp_page(adrp_site, adrp_word)
                if page not in target_pages:
                    continue
                register = adrp_word & 31
                for add_site in range(adrp_site + 4,
                                      min(adrp_site + 20, end), 4):
                    add_word = instruction_word(add_site)
                    if add_word & 0xFF000000 != 0x91000000:
                        continue
                    if ((add_word >> 5) & 31) != register or \
                            add_word & 31 != register:
                        continue
                    resolved = decode_add_target(page, adrp_word, add_word)
                    if resolved in targets:
                        rows.add((adrp_site, add_site, resolved))
        return rows

    global_expected = {
        row for row in expected_materialization_sites
        if row[2] == filter_address
    }
    global_observed = scan_materializations(
        ((text_start, text_start + text_size),),
        frozenset({filter_address}),
    )
    if global_observed != global_expected:
        raise ValueError(
            "OwnerFilter global address materialization set changed: "
            f"expected {sorted(global_expected)!r}, "
            f"got {sorted(global_observed)!r}")

    callable_targets = frozenset({0x6863CC, 0x686450, 0x6864C0, 0x6864C8})
    callable_expected = {
        row for row in expected_materialization_sites
        if row[2] in callable_targets
    }
    callable_observed = scan_materializations(
        ((0x685D30, 0x685E60), (0x685E60, 0x686148)),
        callable_targets,
    )
    if callable_observed != callable_expected:
        raise ValueError(
            "OwnerFilter callable materialization set changed: "
            f"expected {sorted(callable_expected)!r}, "
            f"got {sorted(callable_observed)!r}")

    for owner, site, target, expected_word, kind, role in \
            EXPECTED_OWNER_FILTER_DIRECT_EDGES:
        if not owner_contains(owner, site):
            raise ValueError(
                f"OwnerFilter direct edge escaped owner 0x{owner:X}")
        word = instruction_word(site)
        if word != expected_word:
            raise ValueError(
                f"OwnerFilter direct edge word changed at 0x{site:X}")
        expected_opcode = 0x94000000 if kind == "BL" else 0x14000000
        if kind not in {"BL", "B"} or word & 0xFC000000 != expected_opcode:
            raise ValueError(
                f"OwnerFilter direct edge kind changed at 0x{site:X}")
        resolved = decode_aarch64_pc_relative(site, word, 26, 0)
        if resolved != target:
            raise ValueError(
                f"OwnerFilter direct edge 0x{site:X} resolves to "
                f"0x{resolved:X}, expected 0x{target:X}")
        add_canonical(3, role, owner, site, target, word, ord(kind[0]))

    manager_op_counts: dict[int, int] = {}
    for owner, call_site, expected_call, target_register, pointer_site, \
            expected_pointer, operation_site, expected_operation, operation, \
            role in EXPECTED_OWNER_FILTER_MANAGER_CALLS:
        if not all(owner_contains(owner, site) for site in (
            call_site, pointer_site, operation_site
        )):
            raise ValueError(
                f"OwnerFilter manager call escaped owner 0x{owner:X}")
        call_word = instruction_word(call_site)
        pointer_word = instruction_word(pointer_site)
        operation_word = instruction_word(operation_site)
        if (call_word, pointer_word, operation_word) != (
            expected_call, expected_pointer, expected_operation
        ):
            raise ValueError(
                f"OwnerFilter manager call changed at 0x{call_site:X}")
        if call_word & 0xFFFFFC1F != 0xD63F0000 or \
                (call_word >> 5) & 31 != target_register:
            raise ValueError(
                f"OwnerFilter manager BLR register changed at 0x{call_site:X}")
        if operation_word & 31 != 2:
            raise ValueError(
                f"OwnerFilter manager operation no longer writes W2 at "
                f"0x{operation_site:X}")
        manager_op_counts[operation] = manager_op_counts.get(operation, 0) + 1
        add_canonical(
            4, role, owner, call_site, call_word, target_register,
            pointer_site, pointer_word, operation_site, operation_word,
            operation,
        )

    owner, call_site, expected_call, target_register, pointer_site, \
        expected_pointer, first_gate, expected_first_gate, second_gate, \
        expected_second_gate = EXPECTED_OWNER_FILTER_INVOKER
    if not all(owner_contains(owner, site) for site in (
        call_site, pointer_site, first_gate, second_gate
    )):
        raise ValueError("OwnerFilter invoker escaped Adopt")
    actual_invoker_words = (
        instruction_word(call_site),
        instruction_word(pointer_site),
        instruction_word(first_gate),
        instruction_word(second_gate),
    )
    if actual_invoker_words != (
        expected_call, expected_pointer,
        expected_first_gate, expected_second_gate,
    ):
        raise ValueError("OwnerFilter Adopt invoker surface changed")
    if expected_call & 0xFFFFFC1F != 0xD63F0000 or \
            (expected_call >> 5) & 31 != target_register:
        raise ValueError("OwnerFilter Adopt invoker BLR register changed")
    add_canonical(
        5, "adopt-owner-filter-invoker", owner, call_site, expected_call,
        target_register, pointer_site, expected_pointer,
        first_gate, expected_first_gate, second_gate, expected_second_gate,
    )

    semantic_roles: set[str] = set()
    for owner, site, expected_word, role in \
            EXPECTED_OWNER_FILTER_SEMANTIC_WORDS:
        if role in semantic_roles:
            raise ValueError(f"duplicate OwnerFilter semantic role {role}")
        semantic_roles.add(role)
        if not owner_contains(owner, site):
            raise ValueError(
                f"OwnerFilter semantic word escaped owner 0x{owner:X}")
        word = instruction_word(site)
        if word != expected_word:
            raise ValueError(
                f"OwnerFilter semantic word changed at 0x{site:X}: "
                f"expected 0x{expected_word:08X}, got 0x{word:08X}")
        add_canonical(6, role, owner, site, word)

    expected_ranges = {
        (start, end) for start, end, _role in EXPECTED_OWNER_FILTER_BYTE_RANGES
    }
    if len(expected_ranges) != len(EXPECTED_OWNER_FILTER_BYTE_RANGES):
        raise ValueError("OwnerFilter byte-range expectation has duplicates")
    range_bytes = 0
    for start, end, role in EXPECTED_OWNER_FILTER_BYTE_RANGES:
        if start & 3 or end & 3 or start >= end:
            raise ValueError(f"OwnerFilter byte range {role} is invalid")
        for site in range(start, end, 4):
            if not any(
                fde_start <= site < fde_end
                for fde_start, fde_end, _ in EXPECTED_OWNER_FILTER_BRIDGE_FDES
            ):
                raise ValueError(
                    f"OwnerFilter byte range {role} escaped bridge FDEs at "
                    f"0x{site:X}")
        raw = read_elf_vma(
            data, start, end - start,
            f"OwnerFilter byte range {role}",
        )
        add_canonical(7, role, start, end, len(raw))
        canonical.extend(raw)
        range_bytes += len(raw)

    # Static construction must be eager: the complete initializer contains
    # three __cxa_atexit calls and no guard acquisition/release call.
    static_calls: list[tuple[int, int, int]] = []
    for site in range(0x42EE18, 0x42EF6C, 4):
        word = instruction_word(site)
        if word & 0xFC000000 == 0x94000000:
            static_calls.append((
                site, word,
                decode_aarch64_pc_relative(site, word, 26, 0),
            ))
    if len(static_calls) != 3 or \
            {target for _site, _word, target in static_calls} != {0x411D40}:
        raise ValueError(
            f"OwnerFilter static initializer call set changed: {static_calls!r}")
    for site, word, target in static_calls:
        add_canonical(8, "static-atexit", site, word, target)

    # Resolve the exact destructor GOT cell loaded at 0x42EF20/0x42EF24.
    dtor_adrp = instruction_word(0x42EF20)
    dtor_load = instruction_word(0x42EF24)
    if dtor_adrp != 0xB000B380 or dtor_load != 0xF9462800:
        raise ValueError("OwnerFilter destructor GOT load changed")
    if dtor_load & 0xFFC00000 != 0xF9400000:
        raise ValueError("OwnerFilter destructor load is no longer LDR X")
    dtor_page = decode_aarch64_adrp_page(0x42EF20, dtor_adrp)
    dtor_slot = dtor_page + (((dtor_load >> 10) & 0xFFF) << 3)
    expected_slot, relocation_type, addend, symbol, symbol_value, symbol_size = \
        EXPECTED_OWNER_FILTER_DTOR_GOT
    if dtor_slot != expected_slot:
        raise ValueError(
            f"OwnerFilter destructor GOT slot changed to 0x{dtor_slot:X}")
    relocation = read_elf_relocations(data, b".rela.dyn").get(dtor_slot)
    if relocation != (
        relocation_type, addend, symbol, symbol_value, symbol_size
    ):
        raise ValueError(
            f"OwnerFilter destructor relocation changed: {relocation!r}")
    add_canonical(
        9, "function-base-destructor-got",
        dtor_slot, relocation_type, addend, symbol_value, symbol_size,
        dtor_adrp, dtor_load,
    )

    counts = {
        "fdes": len(EXPECTED_OWNER_FILTER_BRIDGE_FDES),
        "manifest_fdes": len(expected_fde_starts & manifest),
        "external_fdes": len(expected_fde_starts - manifest),
        "global_materializations": len(global_expected),
        "callable_materializations": len(callable_expected),
        "direct_edges": len(EXPECTED_OWNER_FILTER_DIRECT_EDGES),
        "manager_calls": len(EXPECTED_OWNER_FILTER_MANAGER_CALLS),
        "manager_op2": manager_op_counts.get(2, 0),
        "manager_op3": manager_op_counts.get(3, 0),
        "invoker_calls": 1,
        "semantic_words": len(EXPECTED_OWNER_FILTER_SEMANTIC_WORDS),
        "byte_ranges": len(EXPECTED_OWNER_FILTER_BYTE_RANGES),
        "range_bytes": range_bytes,
        "static_atexit_calls": len(static_calls),
    }
    if counts != EXPECTED_OWNER_FILTER_COUNTS:
        raise ValueError(
            "OwnerFilter bridge aggregate changed: expected "
            f"{EXPECTED_OWNER_FILTER_COUNTS}, got {counts}")
    if len(canonical) != EXPECTED_OWNER_FILTER_RAW_BYTES:
        raise ValueError(
            "OwnerFilter bridge canonical byte count changed: expected "
            f"{EXPECTED_OWNER_FILTER_RAW_BYTES}, got {len(canonical)}")
    digest = hashlib.sha256(canonical).hexdigest()
    if digest != EXPECTED_OWNER_FILTER_SHA256:
        raise ValueError(
            "OwnerFilter bridge canonical digest changed: expected "
            f"{EXPECTED_OWNER_FILTER_SHA256}, got {digest}")
    return counts


def verify_emote_registration_surface(
    binary: Path,
    fdes: dict[int, FdeRecord],
    manifest: set[int],
) -> dict[str, int]:
    """Verify emoteplayer.dll's owning entry and Motion exclusion boundary."""
    data = binary.read_bytes()
    expected_fde_starts = {
        start for start, _end, _role in EXPECTED_EMOTE_REGISTRATION_FDES
    }
    if len(expected_fde_starts) != len(EXPECTED_EMOTE_REGISTRATION_FDES):
        raise ValueError("Emote registration FDE expectation has duplicates")
    for start, end, _role in EXPECTED_EMOTE_REGISTRATION_FDES:
        record = fdes.get(start)
        if record is None or record.end != end:
            actual = None if record is None else record.end
            raise ValueError(
                f"Emote registration FDE 0x{start:X} changed: expected "
                f"end 0x{end:X}, got "
                f"{('-' if actual is None else f'0x{actual:X}')}"
            )

    canonical = bytearray()

    def add_canonical(tag: int, role: str, *values: int) -> None:
        encoded_role = role.encode("utf-8")
        if len(encoded_role) > 0xFFFF:
            raise ValueError("Emote registration canonical role is too long")
        canonical.extend(struct.pack("<BH", tag, len(encoded_role)))
        canonical.extend(encoded_role)
        canonical.extend(struct.pack("<" + "Q" * len(values), *values))

    for start, end, role in EXPECTED_EMOTE_REGISTRATION_FDES:
        add_canonical(1, role, start, end)

    literal_addresses: set[int] = set()
    for address, value, role in EXPECTED_EMOTE_REGISTRATION_UTF16:
        if address in literal_addresses:
            raise ValueError("Emote registration UTF-16 expectation duplicates")
        literal_addresses.add(address)
        expected = (value + "\0").encode("utf-16le")
        actual = read_elf_vma(
            data, address, len(expected),
            f"Emote registration UTF-16 literal 0x{address:X}",
        )
        if actual != expected:
            raise ValueError(
                f"Emote registration UTF-16 literal changed at 0x{address:X}"
            )
        add_canonical(2, role, address, len(actual))
        canonical.extend(actual)

    forbidden_motion_callback_literals = 0
    for value in EXPECTED_MOTION_FORBIDDEN_CALLBACK_UTF16:
        encoded = (value + "\0").encode("utf-16le")
        hits = data.count(encoded)
        forbidden_motion_callback_literals += hits
        if hits:
            raise ValueError(
                f"Motion module unexpectedly contains UTF-16 callback "
                f"literal {value!r} ({hits} hit(s))")
        add_canonical(11, f"absent-{value}", len(encoded), hits)
        canonical.extend(encoded)

    section_type, section_flags, text_start, text_size, text_alignment = \
        read_elf_section_metadata(data, b".text")
    if section_type != 1 or not section_flags & 0x4:
        raise ValueError("Emote registration .text is not executable PROGBITS")
    if text_alignment < 4 or text_size % 4:
        raise ValueError("Emote registration .text has invalid alignment or size")
    text = read_elf_vma(data, text_start, text_size, "Emote registration .text")

    def instruction_word(site: int) -> int:
        if site & 3 or not text_start <= site < text_start + text_size:
            raise ValueError(
                f"Emote registration instruction 0x{site:X} escaped .text")
        return struct.unpack_from("<I", text, site - text_start)[0]

    def owner_contains(owner: int, site: int) -> bool:
        record = fdes.get(owner)
        return record is not None and owner <= site < record.end

    def decode_add_target(page: int, adrp_word: int, add_word: int) -> int:
        if adrp_word & 0x9F000000 != 0x90000000:
            raise ValueError("Emote registration materialization lost ADRP")
        if add_word & 0xFF000000 != 0x91000000:
            raise ValueError("Emote registration materialization lost ADD")
        register = adrp_word & 31
        if ((add_word >> 5) & 31) != register or add_word & 31 != register:
            raise ValueError(
                "Emote registration ADRP/ADD register chain changed")
        shift = 12 if add_word & (1 << 22) else 0
        return page + (((add_word >> 10) & 0xFFF) << shift)

    expected_materializations: set[tuple[int, int, int]] = set()
    for owner, adrp_site, add_site, target, expected_adrp, expected_add, \
            role in EXPECTED_EMOTE_REGISTRATION_MATERIALIZATIONS:
        if not owner_contains(owner, adrp_site) or \
                not owner_contains(owner, add_site):
            raise ValueError(
                f"Emote registration materialization escaped owner 0x{owner:X}")
        actual_adrp = instruction_word(adrp_site)
        actual_add = instruction_word(add_site)
        if (actual_adrp, actual_add) != (expected_adrp, expected_add):
            raise ValueError(
                f"Emote registration materialization changed at "
                f"0x{adrp_site:X}")
        page = decode_aarch64_adrp_page(adrp_site, actual_adrp)
        resolved = decode_add_target(page, actual_adrp, actual_add)
        if resolved != target:
            raise ValueError(
                f"Emote registration materialization 0x{adrp_site:X} "
                f"resolves to 0x{resolved:X}, expected 0x{target:X}")
        row = (adrp_site, add_site, target)
        if row in expected_materializations:
            raise ValueError(
                "Emote registration materialization expectation duplicates")
        expected_materializations.add(row)
        add_canonical(
            3, role, owner, adrp_site, add_site, target,
            actual_adrp, actual_add,
        )

    def scan_materializations(
        starts_ends: tuple[tuple[int, int], ...],
        targets: frozenset[int],
    ) -> set[tuple[int, int, int]]:
        rows: set[tuple[int, int, int]] = set()
        target_pages = {target & ~0xFFF for target in targets}
        for start, end in starts_ends:
            if start & 3 or end & 3 or start > end:
                raise ValueError("Emote registration scan range is invalid")
            for adrp_site in range(start, end, 4):
                adrp_word = instruction_word(adrp_site)
                if adrp_word & 0x9F000000 != 0x90000000:
                    continue
                page = decode_aarch64_adrp_page(adrp_site, adrp_word)
                if page not in target_pages:
                    continue
                register = adrp_word & 31
                for add_site in range(
                    adrp_site + 4, min(adrp_site + 20, end), 4
                ):
                    add_word = instruction_word(add_site)
                    if add_word & 0xFF000000 != 0x91000000:
                        continue
                    if ((add_word >> 5) & 31) != register or \
                            add_word & 31 != register:
                        continue
                    resolved = decode_add_target(page, adrp_word, add_word)
                    if resolved in targets:
                        rows.add((adrp_site, add_site, resolved))
        return rows

    materialization_targets = frozenset(
        target
        for _owner, _adrp, _add, target, _aw, _dw, _role
        in EXPECTED_EMOTE_REGISTRATION_MATERIALIZATIONS
    )
    observed_materializations = scan_materializations(
        ((text_start, text_start + text_size),), materialization_targets)
    if observed_materializations != expected_materializations:
        raise ValueError(
            "Emote registration function materialization set changed: "
            f"expected {sorted(expected_materializations)!r}, "
            f"got {sorted(observed_materializations)!r}")

    direct_sites: set[int] = set()
    for owner, site, target, expected_word, role in \
            EXPECTED_EMOTE_REGISTRATION_DIRECT_EDGES:
        if site in direct_sites:
            raise ValueError("Emote registration direct edge duplicates")
        direct_sites.add(site)
        if not owner_contains(owner, site):
            raise ValueError(
                f"Emote registration direct edge escaped owner 0x{owner:X}")
        word = instruction_word(site)
        if word != expected_word or word & 0xFC000000 != 0x94000000:
            raise ValueError(
                f"Emote registration direct BL changed at 0x{site:X}")
        resolved = decode_aarch64_pc_relative(site, word, 26, 0)
        if resolved != target:
            raise ValueError(
                f"Emote registration direct BL 0x{site:X} resolves to "
                f"0x{resolved:X}, expected 0x{target:X}")
        add_canonical(4, role, owner, site, target, word)

    expected_subclass_rows: set[tuple[int, int, int]] = set()
    expected_subclass_targets: set[int] = set()
    for site, target, expected_word, role in EXPECTED_MOTION_SUBCLASS_EDGES:
        if not owner_contains(0x6D9B08, site):
            raise ValueError("Motion subclass edge escaped namespace registrar")
        word = instruction_word(site)
        if word != expected_word or word & 0xFC000000 != 0x94000000:
            raise ValueError(f"Motion subclass BL changed at 0x{site:X}")
        resolved = decode_aarch64_pc_relative(site, word, 26, 0)
        if resolved != target:
            raise ValueError(
                f"Motion subclass BL 0x{site:X} resolves to 0x{resolved:X}, "
                f"expected 0x{target:X}")
        row = (site, target, word)
        if row in expected_subclass_rows or target in expected_subclass_targets:
            raise ValueError("Motion subclass edge expectation duplicates")
        expected_subclass_rows.add(row)
        expected_subclass_targets.add(target)
        add_canonical(5, role, 0x6D9B08, site, target, word)

    forbidden_targets = {0x682528, 0x685BC0, 0x67FAC8}
    interesting_targets = expected_subclass_targets | forbidden_targets
    observed_subclass_rows: set[tuple[int, int, int]] = set()
    forbidden_direct_hits = 0
    for site in range(0x6D9B08, 0x6DA28C, 4):
        word = instruction_word(site)
        if word & 0xFC000000 != 0x94000000:
            continue
        target = decode_aarch64_pc_relative(site, word, 26, 0)
        if target not in interesting_targets:
            continue
        if target in forbidden_targets:
            forbidden_direct_hits += 1
        else:
            observed_subclass_rows.add((site, target, word))
    if observed_subclass_rows != expected_subclass_rows:
        raise ValueError(
            "Motion subclass registration edge set changed: expected "
            f"{sorted(expected_subclass_rows)!r}, "
            f"got {sorted(observed_subclass_rows)!r}")

    expected_constant_rows: set[tuple[int, int]] = set()
    for site, expected_word, role in EXPECTED_MOTION_CONSTANT_EDGES:
        if not owner_contains(0x6D9B08, site):
            raise ValueError("Motion constant edge escaped namespace registrar")
        word = instruction_word(site)
        if word != expected_word or word & 0xFC000000 != 0x94000000:
            raise ValueError(f"Motion constant BL changed at 0x{site:X}")
        target = decode_aarch64_pc_relative(site, word, 26, 0)
        if target != 0x6DA28C:
            raise ValueError(
                f"Motion constant BL 0x{site:X} resolves to 0x{target:X}, "
                "expected 0x6DA28C")
        row = (site, word)
        if row in expected_constant_rows:
            raise ValueError("Motion constant edge expectation duplicates")
        expected_constant_rows.add(row)
        add_canonical(8, role, 0x6D9B08, site, target, word)

    observed_constant_rows: set[tuple[int, int]] = set()
    for site in range(0x6D9B08, 0x6DA28C, 4):
        word = instruction_word(site)
        if word & 0xFC000000 != 0x94000000:
            continue
        if decode_aarch64_pc_relative(site, word, 26, 0) == 0x6DA28C:
            observed_constant_rows.add((site, word))
    if observed_constant_rows != expected_constant_rows:
        raise ValueError(
            "Motion constant registration edge set changed: expected "
            f"{sorted(expected_constant_rows)!r}, "
            f"got {sorted(observed_constant_rows)!r}")

    expected_function_materializations: set[tuple[int, int, int]] = set()
    for adrp_site, add_site, target, expected_adrp, expected_add, role in \
            EXPECTED_MOTION_FUNCTION_MATERIALIZATIONS:
        if not owner_contains(0x6D9B08, adrp_site) or \
                not owner_contains(0x6D9B08, add_site):
            raise ValueError(
                "Motion function materialization escaped namespace registrar")
        adrp_word = instruction_word(adrp_site)
        add_word = instruction_word(add_site)
        if (adrp_word, add_word) != (expected_adrp, expected_add):
            raise ValueError(
                f"Motion function materialization changed at 0x{adrp_site:X}")
        page = decode_aarch64_adrp_page(adrp_site, adrp_word)
        resolved = decode_add_target(page, adrp_word, add_word)
        if resolved != target:
            raise ValueError(
                f"Motion function materialization 0x{adrp_site:X} resolves "
                f"to 0x{resolved:X}, expected 0x{target:X}")
        row = (adrp_site, add_site, target)
        if row in expected_function_materializations:
            raise ValueError(
                "Motion function materialization expectation duplicates")
        expected_function_materializations.add(row)
        add_canonical(
            9, role, 0x6D9B08, adrp_site, add_site, target,
            adrp_word, add_word,
        )

    motion_function_targets = frozenset(
        target for _adrp, _add, target, _aw, _dw, _role
        in EXPECTED_MOTION_FUNCTION_MATERIALIZATIONS
    )
    observed_function_materializations = scan_materializations(
        ((0x6D9B08, 0x6DA28C),), motion_function_targets)
    if observed_function_materializations != expected_function_materializations:
        raise ValueError(
            "Motion namespace function materialization set changed: expected "
            f"{sorted(expected_function_materializations)!r}, "
            f"got {sorted(observed_function_materializations)!r}")

    expected_function_edges: set[tuple[int, int]] = set()
    for site, target, expected_word, opcode, role in \
            EXPECTED_MOTION_FUNCTION_EDGES:
        if not owner_contains(0x6D9B08, site):
            raise ValueError(
                "Motion function member edge escaped namespace registrar")
        word = instruction_word(site)
        if word != expected_word or word & 0xFC000000 != opcode:
            raise ValueError(
                f"Motion function member edge changed at 0x{site:X}")
        resolved = decode_aarch64_pc_relative(site, word, 26, 0)
        if resolved != target:
            raise ValueError(
                f"Motion function member edge 0x{site:X} resolves to "
                f"0x{resolved:X}, expected 0x{target:X}")
        row = (site, word)
        if row in expected_function_edges:
            raise ValueError("Motion function member edge expectation duplicates")
        expected_function_edges.add(row)
        add_canonical(10, role, 0x6D9B08, site, target, word, opcode)

    observed_function_edges: set[tuple[int, int]] = set()
    for site in range(0x6DA180, 0x6DA28C, 4):
        word = instruction_word(site)
        if word & 0x7C000000 != 0x14000000:
            continue
        if decode_aarch64_pc_relative(site, word, 26, 0) == 0x6FCAAC:
            observed_function_edges.add((site, word))
    if observed_function_edges != expected_function_edges:
        raise ValueError(
            "Motion namespace function member edge set changed: expected "
            f"{sorted(expected_function_edges)!r}, "
            f"got {sorted(observed_function_edges)!r}")

    # A direct call is not the only possible way to smuggle EmotePlayer back
    # into the Motion registrar, so reject its exact class-name materialization
    # there as an independent negative boundary.
    forbidden_name_hits = len(scan_materializations(
        ((0x6D9B08, 0x6DA28C),), frozenset({0x14C1E9C})))
    forbidden_motion_hits = forbidden_direct_hits + forbidden_name_hits
    if forbidden_motion_hits:
        raise ValueError(
            "Motion namespace registrar unexpectedly references EmotePlayer")

    semantic_roles: set[str] = set()
    for owner, site, expected_word, role in \
            EXPECTED_EMOTE_REGISTRATION_SEMANTIC_WORDS:
        if role in semantic_roles:
            raise ValueError(f"duplicate Emote registration semantic role {role}")
        semantic_roles.add(role)
        if not owner_contains(owner, site):
            raise ValueError(
                f"Emote registration semantic word escaped owner 0x{owner:X}")
        word = instruction_word(site)
        if word != expected_word:
            raise ValueError(
                f"Emote registration semantic word changed at 0x{site:X}: "
                f"expected 0x{expected_word:08X}, got 0x{word:08X}")
        add_canonical(6, role, owner, site, word)

    range_starts: set[int] = set()
    range_bytes = 0
    for start, end, expected_digest, role in \
            EXPECTED_EMOTE_REGISTRATION_BYTE_RANGES:
        if start in range_starts or start & 3 or end & 3 or start >= end:
            raise ValueError(
                f"Emote registration byte range {role} is invalid or duplicate")
        range_starts.add(start)
        record = fdes.get(start)
        if record is None or record.end != end:
            raise ValueError(
                f"Emote registration byte range {role} is not one complete FDE")
        raw = read_elf_vma(
            data, start, end - start,
            f"Emote registration byte range {role}",
        )
        digest = hashlib.sha256(raw).hexdigest()
        if digest != expected_digest:
            raise ValueError(
                f"Emote registration byte range {role} digest changed: "
                f"expected {expected_digest}, got {digest}")
        add_canonical(7, role, start, end, len(raw))
        canonical.extend(raw)
        range_bytes += len(raw)

    counts = {
        "fdes": len(EXPECTED_EMOTE_REGISTRATION_FDES),
        "manifest_fdes": len(expected_fde_starts & manifest),
        "external_fdes": len(expected_fde_starts - manifest),
        "utf16_literals": len(EXPECTED_EMOTE_REGISTRATION_UTF16),
        "forbidden_motion_callback_literals": (
            forbidden_motion_callback_literals),
        "materializations": len(expected_materializations),
        "entry_materializations": sum(
            int(target == 0x682528)
            for _adrp, _add, target in expected_materializations),
        "setter_materializations": sum(
            int(target in {0x685D30, 0x685E60})
            for _adrp, _add, target in expected_materializations),
        "direct_edges": len(EXPECTED_EMOTE_REGISTRATION_DIRECT_EDGES),
        "motion_constants": len(expected_constant_rows),
        "motion_subclasses": len(expected_subclass_rows),
        "motion_function_materializations": len(
            expected_function_materializations),
        "motion_functions": len(expected_function_edges),
        "forbidden_motion_hits": forbidden_motion_hits,
        "semantic_words": len(EXPECTED_EMOTE_REGISTRATION_SEMANTIC_WORDS),
        "byte_ranges": len(EXPECTED_EMOTE_REGISTRATION_BYTE_RANGES),
        "range_bytes": range_bytes,
    }
    if counts != EXPECTED_EMOTE_REGISTRATION_COUNTS:
        raise ValueError(
            "Emote registration aggregate changed: expected "
            f"{EXPECTED_EMOTE_REGISTRATION_COUNTS}, got {counts}")
    if len(canonical) != EXPECTED_EMOTE_REGISTRATION_RAW_BYTES:
        raise ValueError(
            "Emote registration canonical byte count changed: expected "
            f"{EXPECTED_EMOTE_REGISTRATION_RAW_BYTES}, got {len(canonical)}")
    digest = hashlib.sha256(canonical).hexdigest()
    if digest != EXPECTED_EMOTE_REGISTRATION_SHA256:
        raise ValueError(
            "Emote registration canonical digest changed: expected "
            f"{EXPECTED_EMOTE_REGISTRATION_SHA256}, got {digest}")
    return counts


def verify_indirect_abi_surface(
    binary: Path,
    fdes: dict[int, FdeRecord],
    manifest: set[int],
) -> dict[str, int]:
    data = binary.read_bytes()
    switch_dispatches = {
        switch for _, switch, _, _, _ in EXPECTED_SWITCH_TABLE_SURFACES
    }
    observed_sites: set[tuple[int, int]] = set()

    for owner in sorted(manifest):
        record = fdes.get(owner)
        if record is None:
            raise ValueError(f"indirect ABI owner 0x{owner:X} has no FDE")
        raw = read_elf_vma(
            data, owner, record.end - owner,
            f"indirect ABI owner 0x{owner:X}",
        )
        for offset in range(0, len(raw), 4):
            address = owner + offset
            word = struct.unpack_from("<I", raw, offset)[0]
            is_blr = word & 0xFFFFFC1F == 0xD63F0000
            is_non_switch_br = (
                word & 0xFFFFFC1F == 0xD61F0000
                and address not in switch_dispatches
            )
            if is_blr or is_non_switch_br:
                observed_sites.add((owner, address))

    expected_sites = {
        (owner, site)
        for owner, site, _, _, _ in EXPECTED_INDIRECT_ABI_SITES
    }
    if len(expected_sites) != len(EXPECTED_INDIRECT_ABI_SITES):
        raise ValueError("indirect ABI expectation contains duplicate sites")
    if observed_sites != expected_sites:
        missing = sorted(expected_sites - observed_sites)
        extra = sorted(observed_sites - expected_sites)
        format_sites = lambda sites: ",".join(
            f"0x{owner:X}:0x{site:X}" for owner, site in sites
        ) or "-"
        raise ValueError(
            "indirect ABI site set changed: "
            f"missing={format_sites(missing)} extra={format_sites(extra)}")

    role_counts: dict[str, int] = {}
    fixed_loads = 0
    member_pointer_loads = 0
    for owner, site, producer, expected_word, role in \
            EXPECTED_INDIRECT_ABI_SITES:
        record = fdes[owner]
        if owner not in manifest or not owner <= producer < site < record.end:
            raise ValueError(
                f"indirect ABI row 0x{site:X} has invalid owner/producer bounds")
        producer_word = struct.unpack(
            "<I", read_elf_vma(
                data, producer, 4,
                f"indirect ABI producer 0x{producer:X}",
            ),
        )[0]
        if producer_word != expected_word:
            raise ValueError(
                f"indirect ABI producer 0x{producer:X} changed: expected "
                f"0x{expected_word:08X}, got 0x{producer_word:08X}")

        transfer_word = struct.unpack(
            "<I", read_elf_vma(
                data, site, 4, f"indirect ABI transfer 0x{site:X}",
            ),
        )[0]
        if not (
            transfer_word & 0xFFFFFC1F == 0xD63F0000
            or transfer_word & 0xFFFFFC1F == 0xD61F0000
        ):
            raise ValueError(
                f"indirect ABI site 0x{site:X} is no longer BLR/BR")
        transfer_register = (transfer_word >> 5) & 31
        producer_register = producer_word & 31
        if transfer_register != producer_register:
            raise ValueError(
                f"indirect ABI site 0x{site:X} calls X{transfer_register}, "
                f"but producer 0x{producer:X} loads X{producer_register}")

        if producer_word & 0xFFC00000 == 0xF9400000:
            fixed_loads += 1
        elif producer_word in {0xF8686928, 0xF8746914}:
            member_pointer_loads += 1
        else:
            raise ValueError(
                f"indirect ABI producer 0x{producer:X} has unknown load shape "
                f"0x{producer_word:08X}")
        role_counts[role] = role_counts.get(role, 0) + 1

    if role_counts != EXPECTED_INDIRECT_ABI_ROLE_COUNTS:
        raise ValueError(
            "indirect ABI semantic role counts changed: expected "
            f"{EXPECTED_INDIRECT_ABI_ROLE_COUNTS}, got {role_counts}")
    return {
        "sites": len(expected_sites),
        "fixed_loads": fixed_loads,
        "member_pointer_loads": member_pointer_loads,
        "roles": len(role_counts),
    }


def verify_typed_member_instruction_surface(
    binary: Path,
    fdes: dict[int, FdeRecord],
    manifest: set[int],
) -> dict[str, int]:
    sites = EXPECTED_TYPED_MEMBER_INSTRUCTION_SITES
    if len(sites) != len(set(sites)):
        raise ValueError("typed-member instruction surface has duplicate sites")
    if tuple(sorted(sites)) != sites:
        raise ValueError("typed-member instruction sites are not sorted")

    data = binary.read_bytes()
    owners = sorted(manifest)
    owner_index = 0
    encoded = bytearray()
    observed_owners: set[int] = set()
    for site in sites:
        if site & 3:
            raise ValueError(
                f"typed-member site 0x{site:X} is not AArch64 aligned")
        while (
            owner_index < len(owners)
            and fdes[owners[owner_index]].end <= site
        ):
            owner_index += 1
        if owner_index == len(owners):
            raise ValueError(
                f"typed-member site 0x{site:X} is after all MANIFEST FDEs")
        owner = owners[owner_index]
        record = fdes[owner]
        if not owner <= site <= record.end - 4:
            raise ValueError(
                f"typed-member site 0x{site:X} is outside MANIFEST owner "
                f"0x{owner:X}...0x{record.end:X}")
        word = struct.unpack(
            "<I",
            read_elf_vma(
                data, site, 4, f"typed-member instruction 0x{site:X}",
            ),
        )[0]
        encoded += struct.pack("<QQI", owner, site, word)
        observed_owners.add(owner)

    digest = hashlib.sha256(encoded).hexdigest()
    if digest != EXPECTED_TYPED_MEMBER_INSTRUCTION_SHA256:
        raise ValueError(
            "typed-member instruction surface changed: expected "
            f"{EXPECTED_TYPED_MEMBER_INSTRUCTION_SHA256}, got {digest}")
    if len(observed_owners) != EXPECTED_TYPED_MEMBER_OWNER_COUNT:
        raise ValueError(
            "typed-member owner count changed: expected "
            f"{EXPECTED_TYPED_MEMBER_OWNER_COUNT}, got "
            f"{len(observed_owners)}")
    return {"sites": len(sites), "owners": len(observed_owners)}


def sign_extend(value: int, bits: int) -> int:
    sign = 1 << (bits - 1)
    return (value ^ sign) - sign


def decode_aarch64_pc_relative(
    address: int,
    word: int,
    bits: int,
    shift: int,
) -> int:
    immediate = (word >> shift) & ((1 << bits) - 1)
    return address + (sign_extend(immediate, bits) << 2)


def landing_pad_successors(
    address: int,
    word: int,
    owner: int,
    end: int,
    switch_destinations: dict[int, tuple[int, ...]],
) -> tuple[int, ...]:
    """Decode explicit AArch64 control flow, deliberately excluding EH arcs."""
    fallthrough = address + 4

    if word & 0xFC000000 == 0x94000000:  # BL imm26
        target = decode_aarch64_pc_relative(address, word, 26, 0)
        if target in EXPECTED_LANDING_PAD_NORETURN_TARGETS:
            return ()
        return (fallthrough,) if fallthrough < end else ()

    if word & 0xFC000000 == 0x14000000:  # B imm26
        target = decode_aarch64_pc_relative(address, word, 26, 0)
        return (target,) if owner <= target < end else ()

    if word & 0xFF000010 == 0x54000000:  # B.cond imm19
        target = decode_aarch64_pc_relative(address, word, 19, 5)
        return tuple(
            value for value in (target, fallthrough)
            if owner <= value < end
        )

    if word & 0x7E000000 == 0x34000000:  # CBZ/CBNZ imm19
        target = decode_aarch64_pc_relative(address, word, 19, 5)
        return tuple(
            value for value in (target, fallthrough)
            if owner <= value < end
        )

    if word & 0x7E000000 == 0x36000000:  # TBZ/TBNZ imm14
        target = decode_aarch64_pc_relative(address, word, 14, 5)
        return tuple(
            value for value in (target, fallthrough)
            if owner <= value < end
        )

    if word & 0xFFFFFC1F == 0xD61F0000:  # BR Xn
        return switch_destinations.get(address, ())

    is_ret = word & 0xFFFFFC1F == 0xD65F0000
    is_brk_or_hlt = word & 0xFFE0001F in {0xD4200000, 0xD4400000}
    is_eret = word & 0xFFFFFFFF == 0xD69F03E0
    if is_ret or is_brk_or_hlt or is_eret:
        return ()
    return (fallthrough,) if fallthrough < end else ()


def walk_landing_pad_cfg(
    root: int,
    owner: int,
    end: int,
    instruction_word,
    switch_destinations: dict[int, tuple[int, ...]],
) -> dict[int, tuple[int, tuple[int, ...]]]:
    graph: dict[int, tuple[int, tuple[int, ...]]] = {}
    pending = [root]
    while pending:
        address = pending.pop()
        if address in graph:
            continue
        if address & 3 or not owner <= address < end:
            raise ValueError(
                f"landing CFG from 0x{root:X} escapes owner 0x{owner:X} "
                f"at 0x{address:X}")
        word = instruction_word(address)
        successors = landing_pad_successors(
            address, word, owner, end, switch_destinations)
        for successor in successors:
            if successor & 3 or not owner <= successor < end:
                raise ValueError(
                    f"landing CFG successor 0x{successor:X} from "
                    f"0x{address:X} escapes 0x{owner:X}...0x{end:X}")
        graph[address] = (word, successors)
        pending.extend(successors)
    return graph


def decode_landing_transfer(
    address: int,
    word: int,
) -> tuple[str, int] | None:
    if word & 0xFC000000 == 0x94000000:  # BL imm26
        return (
            "BL",
            decode_aarch64_pc_relative(address, word, 26, 0),
        )
    if word & 0xFFFFFC1F == 0xD63F0000:  # BLR Xn
        return ("BLR", (word >> 5) & 31)
    if word & 0xFFFFFC1F == 0xD61F0000:  # BR Xn
        return ("BR", (word >> 5) & 31)
    return None


def verify_landing_pad_contract_surface(
    binary: Path,
    fdes: dict[int, FdeRecord],
) -> dict[str, int]:
    data, except_section = read_gcc_except_table(binary)

    switch_destinations: dict[int, tuple[int, ...]] = {}
    for owner, site, table, entry_count, _ in EXPECTED_SWITCH_TABLE_SURFACES:
        if site in switch_destinations:
            raise ValueError(
                f"duplicate switch site in landing CFG at 0x{site:X}")
        raw = read_elf_vma(
            data, table, entry_count * 4,
            f"landing CFG switch table 0x{table:X}",
        )
        destinations = tuple(sorted({
            table + displacement
            for displacement in struct.unpack(f"<{entry_count}i", raw)
        }))
        record = fdes.get(owner)
        if record is None or any(
            not owner <= destination < record.end
            for destination in destinations
        ):
            raise ValueError(
                f"landing CFG switch 0x{site:X} escapes owner 0x{owner:X}")
        switch_destinations[site] = destinations

    encoded = bytearray()
    unique_instructions: set[tuple[int, int]] = set()
    unique_transfers: set[tuple[int, int, str, int]] = set()
    catch_rethrow_landings: set[tuple[int, int]] = set()
    class_counts = {
        "cleanup_resume": 0,
        "terminate": 0,
        "catch_rethrow": 0,
    }
    contract_lengths: list[int] = []
    landing_count = 0

    for owner in sorted(EXPECTED_ALL_LSDA_CALL_SITES):
        record = fdes.get(owner)
        if record is None or record.lsda is None:
            raise ValueError(
                f"landing-pad owner 0x{owner:X} has no LSDA FDE")
        size = record.end - owner
        if size <= 0 or size & 3:
            raise ValueError(
                f"landing-pad owner 0x{owner:X} has invalid FDE size")
        function_raw = read_elf_vma(
            data, owner, size, f"landing-pad owner 0x{owner:X}")
        word_cache: dict[int, int] = {}

        def instruction_word(address: int) -> int:
            if address not in word_cache:
                offset = address - owner
                if offset < 0 or offset + 4 > len(function_raw):
                    raise ValueError(
                        f"instruction 0x{address:X} is outside landing owner "
                        f"0x{owner:X}")
                word_cache[address] = struct.unpack_from(
                    "<I", function_raw, offset)[0]
            return word_cache[address]

        parsed = parse_lsda(data, except_section, record.lsda)
        landing_actions: dict[int, int] = {}
        for _, _, relative_landing, action in parsed.call_sites:
            if relative_landing == 0:
                continue
            landing = owner + relative_landing
            previous = landing_actions.setdefault(landing, action)
            if previous != action:
                raise ValueError(
                    f"landing 0x{landing:X} mixes actions "
                    f"{previous} and {action}")

        normal_graph = walk_landing_pad_cfg(
            owner, owner, record.end, instruction_word,
            switch_destinations,
        )
        normal_addresses = set(normal_graph)

        for landing, action in sorted(landing_actions.items()):
            if action not in {0, 1}:
                raise ValueError(
                    f"landing 0x{landing:X} has unsupported action {action}")
            graph = walk_landing_pad_cfg(
                landing, owner, record.end, instruction_word,
                switch_destinations,
            )
            overlap = set(graph) & normal_addresses
            if overlap:
                first = min(overlap)
                raise ValueError(
                    f"landing 0x{landing:X} overlaps explicit normal CFG "
                    f"at 0x{first:X}")

            direct_targets: set[int] = set()
            for address, (word, _) in graph.items():
                transfer = decode_landing_transfer(address, word)
                if transfer is None:
                    continue
                kind, value = transfer
                unique_transfers.add((owner, address, kind, value))
                if kind == "BL":
                    direct_targets.add(value)

            if action == 0:
                forbidden = {0x408BD0, 0x4139B0, 0x520FAC}
                if 0x41A950 not in direct_targets or direct_targets & forbidden:
                    raise ValueError(
                        f"cleanup landing 0x{landing:X} does not form a "
                        "pure cleanup/resume contract")
                landing_class = "cleanup_resume"
            elif 0x520FAC in direct_targets:
                if direct_targets != {0x520FAC} or len(graph) != 1:
                    raise ValueError(
                        f"terminate landing 0x{landing:X} gained extra work")
                landing_class = "terminate"
            elif {0x408BD0, 0x4139B0} <= direct_targets:
                if 0x41A950 in direct_targets or 0x520FAC in direct_targets:
                    raise ValueError(
                        f"catch/rethrow landing 0x{landing:X} has an "
                        "unexpected terminal helper")
                landing_class = "catch_rethrow"
                catch_rethrow_landings.add((owner, landing))
            else:
                raise ValueError(
                    f"action-1 landing 0x{landing:X} is neither terminate "
                    "nor catch/rethrow")
            class_counts[landing_class] += 1

            addresses = tuple(sorted(graph))
            contract_lengths.append(len(addresses))
            landing_count += 1
            encoded += struct.pack(
                "<QQBI", owner, landing, action, len(addresses))
            for address in addresses:
                word, successors = graph[address]
                encoded += struct.pack(
                    "<QIB", address, word, len(successors))
                for successor in successors:
                    encoded += struct.pack("<Q", successor)
                unique_instructions.add((owner, address))

    if catch_rethrow_landings != EXPECTED_CATCH_RETHROW_LANDINGS:
        raise ValueError(
            "catch/rethrow landing set changed: expected "
            f"{sorted(EXPECTED_CATCH_RETHROW_LANDINGS)!r}, got "
            f"{sorted(catch_rethrow_landings)!r}")

    actual_direct_counts: dict[int, int] = {}
    actual_blr_sites: set[tuple[int, int, int]] = set()
    unexpected_br_sites = []
    for owner, site, kind, value in unique_transfers:
        if kind == "BL":
            actual_direct_counts[value] = actual_direct_counts.get(value, 0) + 1
        elif kind == "BLR":
            actual_blr_sites.add((owner, site, value))
        else:
            unexpected_br_sites.append((owner, site, value))
    if unexpected_br_sites:
        raise ValueError(
            "landing-pad contract gained BR sites: "
            + ",".join(
                f"0x{owner:X}:0x{site:X}/X{register}"
                for owner, site, register in sorted(unexpected_br_sites)
            ))

    expected_direct_counts = {
        target: count
        for target, count, _ in EXPECTED_LANDING_PAD_DIRECT_TARGETS
    }
    if len(expected_direct_counts) != len(EXPECTED_LANDING_PAD_DIRECT_TARGETS):
        raise ValueError("landing-pad direct target expectation has duplicates")
    if actual_direct_counts != expected_direct_counts:
        raise ValueError(
            "landing-pad direct target counts changed: expected "
            f"{expected_direct_counts}, got {actual_direct_counts}")

    expected_blr_sites = {
        (owner, site, register)
        for owner, site, register, _ in EXPECTED_LANDING_PAD_BLR_SITES
    }
    if len(expected_blr_sites) != len(EXPECTED_LANDING_PAD_BLR_SITES):
        raise ValueError("landing-pad BLR expectation has duplicate sites")
    if actual_blr_sites != expected_blr_sites:
        raise ValueError(
            "landing-pad BLR sites changed: expected "
            f"{sorted(expected_blr_sites)!r}, got "
            f"{sorted(actual_blr_sites)!r}")

    counts = {
        "owners": len(EXPECTED_ALL_LSDA_CALL_SITES),
        "landings": landing_count,
        **class_counts,
        "unique_instructions": len(unique_instructions),
        "contract_instructions": sum(contract_lengths),
        "min_contract_instructions": min(contract_lengths),
        "max_contract_instructions": max(contract_lengths),
        "unique_transfers": len(unique_transfers),
        "direct_transfers": sum(actual_direct_counts.values()),
        "indirect_transfers": len(actual_blr_sites),
    }
    if counts != EXPECTED_LANDING_PAD_CONTRACT_COUNTS:
        raise ValueError(
            "landing-pad aggregate contract changed: expected "
            f"{EXPECTED_LANDING_PAD_CONTRACT_COUNTS}, got {counts}")

    digest = hashlib.sha256(encoded).hexdigest()
    if digest != EXPECTED_LANDING_PAD_CONTRACT_SHA256:
        raise ValueError(
            "landing-pad contract surface changed: expected "
            f"{EXPECTED_LANDING_PAD_CONTRACT_SHA256}, got {digest}")
    return {
        **counts,
        "direct_targets": len(actual_direct_counts),
        "blr_roles": len({
            role for _, _, _, role in EXPECTED_LANDING_PAD_BLR_SITES
        }),
    }


def normal_cfg_successors(
    address: int,
    word: int,
    owner: int,
    end: int,
    switch_destinations: dict[int, tuple[int, ...]],
    noreturn_targets: frozenset[int],
) -> tuple[int, ...]:
    """Decode entry-rooted normal flow without importing any LSDA arc."""
    fallthrough = address + 4

    if word & 0xFC000000 == 0x94000000:  # BL imm26
        target = decode_aarch64_pc_relative(address, word, 26, 0)
        if target in noreturn_targets:
            return ()
        return (fallthrough,) if fallthrough < end else ()

    if word & 0xFC000000 == 0x14000000:  # B imm26
        target = decode_aarch64_pc_relative(address, word, 26, 0)
        return (target,) if owner <= target < end else ()

    if word & 0xFF000010 == 0x54000000:  # B.cond imm19
        target = decode_aarch64_pc_relative(address, word, 19, 5)
        return tuple(
            value for value in (target, fallthrough)
            if owner <= value < end
        )

    if word & 0x7E000000 == 0x34000000:  # CBZ/CBNZ imm19
        target = decode_aarch64_pc_relative(address, word, 19, 5)
        return tuple(
            value for value in (target, fallthrough)
            if owner <= value < end
        )

    if word & 0x7E000000 == 0x36000000:  # TBZ/TBNZ imm14
        target = decode_aarch64_pc_relative(address, word, 14, 5)
        return tuple(
            value for value in (target, fallthrough)
            if owner <= value < end
        )

    if word & 0xFFFFFC1F == 0xD61F0000:  # BR Xn
        return switch_destinations.get(address, ())

    is_ret = word & 0xFFFFFC1F == 0xD65F0000
    is_brk_or_hlt = word & 0xFFE0001F in {0xD4200000, 0xD4400000}
    is_eret = word == 0xD69F03E0
    if is_ret or is_brk_or_hlt or is_eret:
        return ()
    return (fallthrough,) if fallthrough < end else ()


def walk_normal_cfg(
    root: int,
    owner: int,
    end: int,
    instruction_word,
    switch_destinations: dict[int, tuple[int, ...]],
    noreturn_targets: frozenset[int],
) -> dict[int, tuple[int, tuple[int, ...]]]:
    graph: dict[int, tuple[int, tuple[int, ...]]] = {}
    pending = [root]
    while pending:
        address = pending.pop()
        if address in graph:
            continue
        if address & 3 or not owner <= address < end:
            raise ValueError(
                f"normal CFG from 0x{root:X} escapes owner 0x{owner:X} "
                f"at 0x{address:X}")
        word = instruction_word(address)
        successors = normal_cfg_successors(
            address, word, owner, end, switch_destinations,
            noreturn_targets,
        )
        for successor in successors:
            if successor & 3 or not owner <= successor < end:
                raise ValueError(
                    f"normal CFG successor 0x{successor:X} from "
                    f"0x{address:X} escapes 0x{owner:X}...0x{end:X}")
        graph[address] = (word, successors)
        pending.extend(successors)
    return graph


def read_indirect_argument_manifest():
    """Decode and structurally validate all indirect argument-source rows."""
    try:
        compressed = base64.b64decode(
            EXPECTED_INDIRECT_ARGUMENT_ZLIB_BASE64,
            validate=True,
        )
        raw = zlib.decompress(compressed)
    except (binascii.Error, ValueError, zlib.error) as exc:
        raise ValueError(
            f"indirect-argument manifest cannot be decoded: {exc}") \
            from exc

    if len(raw) != EXPECTED_INDIRECT_ARGUMENT_RAW_BYTES:
        raise ValueError(
            "indirect-argument manifest size changed: expected "
            f"{EXPECTED_INDIRECT_ARGUMENT_RAW_BYTES}, got {len(raw)}")
    digest = hashlib.sha256(raw).hexdigest()
    if digest != EXPECTED_INDIRECT_ARGUMENT_SHA256:
        raise ValueError(
            "indirect-argument manifest digest changed: expected "
            f"{EXPECTED_INDIRECT_ARGUMENT_SHA256}, got {digest}")

    transfer_header = struct.Struct("<IIIBBBBB")
    argument_header = struct.Struct("<BBBBB")
    source_record = struct.Struct("<BBBII")
    rows = {}
    offset = 0
    previous_key = None
    while offset < len(raw):
        if offset + transfer_header.size > len(raw):
            raise ValueError(
                "indirect-argument manifest has a truncated transfer header")
        (
            owner,
            site,
            transfer_word,
            transfer_id,
            flow_id,
            target_register,
            role_id,
            argument_count,
        ) = transfer_header.unpack_from(raw, offset)
        offset += transfer_header.size

        transfer_kind = INDIRECT_ARGUMENT_TRANSFER_IDS.get(transfer_id)
        flow_class = INDIRECT_ARGUMENT_FLOW_IDS.get(flow_id)
        role = INDIRECT_ARGUMENT_ROLE_IDS.get(role_id)
        if transfer_kind is None or flow_class is None or role is None:
            raise ValueError(
                f"indirect-argument transfer IDs are invalid at 0x{site:X}")
        if owner & 3 or site & 3 or site < owner or target_register >= 31:
            raise ValueError(
                f"indirect-argument transfer header is invalid at 0x{site:X}")
        if argument_count not in EXPECTED_INDIRECT_ARGUMENT_ARITIES:
            raise ValueError(
                f"indirect-argument arity is invalid at 0x{site:X}")
        if transfer_kind == "BLR":
            valid_transfer = (
                transfer_word & 0xFFFFFC1F == 0xD63F0000)
        else:
            valid_transfer = (
                transfer_word & 0xFFFFFC1F == 0xD61F0000)
        if not valid_transfer or (transfer_word >> 5) & 31 != target_register:
            raise ValueError(
                f"indirect-argument transfer word is invalid at 0x{site:X}")

        key = (owner, site)
        if previous_key is not None and key <= previous_key:
            raise ValueError(
                "indirect-argument transfer rows are non-canonical at "
                f"0x{owner:X}:0x{site:X}")
        previous_key = key

        arguments = []
        for expected_index in range(argument_count):
            if offset + argument_header.size > len(raw):
                raise ValueError(
                    "indirect-argument manifest has a truncated argument "
                    f"header at 0x{site:X}")
            (
                argument_index,
                bank_id,
                type_id,
                argument_size,
                source_count,
            ) = argument_header.unpack_from(raw, offset)
            offset += argument_header.size
            bank = INDIRECT_ARGUMENT_BANK_IDS.get(bank_id)
            type_class = INDIRECT_ARGUMENT_TYPE_IDS.get(type_id)
            if (
                argument_index != expected_index
                or bank != f"X{argument_index}"
                or type_class is None
                or not source_count
                or (type_class, argument_size)
                not in EXPECTED_INDIRECT_ARGUMENT_TYPE_SIZE_COUNTS
            ):
                raise ValueError(
                    "indirect-argument argument header is invalid at "
                    f"0x{site:X}:arg{argument_index}")

            sources = []
            for _ in range(source_count):
                if offset + source_record.size > len(raw):
                    raise ValueError(
                        "indirect-argument manifest has a truncated source "
                        f"at 0x{site:X}:arg{argument_index}")
                source = source_record.unpack_from(raw, offset)
                offset += source_record.size
                (
                    source_role_id,
                    source_kind_id,
                    operand_index,
                    source_address,
                    source_word,
                ) = source
                source_role = INDIRECT_ARGUMENT_SOURCE_ROLE_IDS.get(
                    source_role_id)
                source_kind = INDIRECT_ARGUMENT_SOURCE_KIND_IDS.get(
                    source_kind_id)
                if source_role is None or source_kind is None:
                    raise ValueError(
                        "indirect-argument source ID is invalid at "
                        f"0x{site:X}:arg{argument_index}")
                if source_address & 3:
                    raise ValueError(
                        "indirect-argument source is unaligned at "
                        f"0x{site:X}:0x{source_address:X}")
                if source_role in {"entry-parameter", "entry-residue"}:
                    valid_source = (
                        source_kind == "ENTRY"
                        and operand_index == 0
                        and source_address == owner
                        and source_word == 0
                    )
                elif source_role == "instruction":
                    valid_source = (
                        source_kind not in {"ENTRY", "BL", "BLR"}
                        and owner <= source_address < site
                        and source_word != 0
                        and (
                            (source_kind == "LDP"
                             and operand_index in {0, 1})
                            or (source_kind != "LDP" and operand_index == 0)
                        )
                    )
                else:
                    valid_source = (
                        source_kind in {"BL", "BLR"}
                        and operand_index == 0
                        and owner <= source_address < site
                        and source_word != 0
                    )
                if not valid_source:
                    raise ValueError(
                        "indirect-argument source role/kind mismatch at "
                        f"0x{site:X}:0x{source_address:X}")
                sources.append(source)

            canonical_sources = sorted(
                sources,
                key=lambda item: (item[3], item[0], item[2], item[1]),
            )
            if sources != canonical_sources or len(set(sources)) != len(sources):
                raise ValueError(
                    "indirect-argument sources are non-canonical at "
                    f"0x{site:X}:arg{argument_index}")
            arguments.append((
                argument_index,
                bank_id,
                type_id,
                argument_size,
                tuple(sources),
            ))

        if key in rows:
            raise ValueError(
                f"duplicate indirect-argument transfer at 0x{site:X}")
        rows[key] = (
            transfer_word,
            transfer_id,
            flow_id,
            target_register,
            role_id,
            tuple(arguments),
        )

    expected_sites = EXPECTED_INDIRECT_ARGUMENT_COUNTS["sites"]
    if len(rows) != expected_sites:
        raise ValueError(
            "indirect-argument transfer count changed: expected "
            f"{expected_sites}, got {len(rows)}")
    return rows


def indirect_argument_instruction_destination(
    source_kind: str,
    operand_index: int,
    word: int,
) -> int:
    """Decode the physical destination of every explicit indirect argument."""
    if source_kind == "LDP":
        if operand_index == 0:
            return word & 31
        if operand_index == 1:
            return (word >> 10) & 31
    elif operand_index == 0 and source_kind in {
        "ADD", "CSEL", "LDR", "MOV",
    }:
        return word & 31
    raise ValueError(
        f"unsupported indirect-argument {source_kind} operand "
        f"{operand_index}")


def verify_indirect_argument_surface(
    binary: Path,
    fdes: dict[int, FdeRecord],
    manifest: set[int],
) -> dict[str, int]:
    """Prove every X0...X7 input reaching every non-switch BLR/BR."""
    expected_rows = read_indirect_argument_manifest()
    data, except_section = read_gcc_except_table(binary)

    abi_rows = {
        (owner, site): (producer, producer_word, role)
        for owner, site, producer, producer_word, role
        in EXPECTED_INDIRECT_ABI_SITES
    }
    if len(abi_rows) != len(EXPECTED_INDIRECT_ABI_SITES):
        raise ValueError("indirect-argument ABI expectation has duplicate sites")
    if set(expected_rows) != set(abi_rows):
        missing = sorted(set(abi_rows) - set(expected_rows))
        extra = sorted(set(expected_rows) - set(abi_rows))
        raise ValueError(
            "indirect-argument site set differs from indirect ABI surface: "
            f"missing={missing}, extra={extra}")

    landing_sites = {
        (owner, site)
        for owner, site, _, _ in EXPECTED_LANDING_PAD_BLR_SITES
    }
    switch_destinations: dict[int, tuple[int, ...]] = {}
    for owner, site, table, entry_count, _ in EXPECTED_SWITCH_TABLE_SURFACES:
        raw = read_elf_vma(
            data, table, entry_count * 4,
            f"indirect-argument switch table 0x{table:X}",
        )
        destinations = tuple(sorted({
            table + displacement
            for displacement in struct.unpack(f"<{entry_count}i", raw)
        }))
        record = fdes.get(owner)
        if record is None or any(
            not owner <= destination < record.end
            for destination in destinations
        ):
            raise ValueError(
                f"indirect-argument switch 0x{site:X} escapes owner "
                f"0x{owner:X}")
        switch_destinations[site] = destinations

    # A reverse slice cannot skip a writer already proved for a different
    # argument/site and silently inherit an older physical-register value.
    explicit_writer_sources: dict[
        tuple[int, str, int], set[tuple[int, ...]]
    ] = {}
    for (owner, _), (_, _, _, _, _, arguments) in expected_rows.items():
        for _, bank_id, _, _, sources in arguments:
            bank = INDIRECT_ARGUMENT_BANK_IDS[bank_id]
            for source in sources:
                source_role = INDIRECT_ARGUMENT_SOURCE_ROLE_IDS[source[0]]
                if source_role == "instruction":
                    explicit_writer_sources.setdefault(
                        (owner, bank, source[3]), set()
                    ).add(source)

    noreturn_targets = frozenset(
        target for target, _, _ in EXPECTED_NORMAL_NORETURN_TARGETS)
    rows_by_owner: dict[int, list[tuple[int, tuple]]] = {}
    for (owner, site), row in expected_rows.items():
        rows_by_owner.setdefault(owner, []).append((site, row))

    seen_sites = set()
    site_owners = set()
    target_registers = set()
    arity_counts: dict[int, int] = {}
    cardinalities: dict[int, int] = {}
    transfer_counts: dict[str, int] = {}
    flow_counts: dict[str, int] = {}
    bank_counts: dict[str, int] = {}
    argument_index_counts: dict[int, int] = {}
    type_size_counts: dict[tuple[str, int], int] = {}
    site_role_counts: dict[str, int] = {}
    role_operand_counts: dict[str, int] = {}
    source_role_counts = {
        role: 0 for role in INDIRECT_ARGUMENT_SOURCE_ROLE_IDS.values()
    }
    source_kind_counts: dict[str, int] = {}
    source_class_counts = {
        "memory_sources": 0,
        "transfer_sources": 0,
        "address_sources": 0,
        "select_sources": 0,
    }
    volatile_call_clobbers = 0

    for owner in sorted(rows_by_owner):
        if owner not in manifest:
            raise ValueError(
                f"indirect-argument owner 0x{owner:X} is outside MANIFEST")
        record = fdes.get(owner)
        if record is None:
            raise ValueError(
                f"indirect-argument owner 0x{owner:X} has no FDE")
        function_raw = read_elf_vma(
            data, owner, record.end - owner,
            f"indirect-argument owner 0x{owner:X}",
        )

        def instruction_word(address: int) -> int:
            offset = address - owner
            if offset < 0 or offset + 4 > len(function_raw):
                raise ValueError(
                    f"indirect-argument instruction 0x{address:X} is "
                    f"outside owner 0x{owner:X}")
            return struct.unpack_from("<I", function_raw, offset)[0]

        normal_graph = walk_normal_cfg(
            owner, owner, record.end, instruction_word,
            switch_destinations, noreturn_targets,
        )
        owner_landing_sites = {
            site for candidate_owner, site in landing_sites
            if candidate_owner == owner
        }
        landing_graphs = []
        if owner_landing_sites:
            if record.lsda is None:
                raise ValueError(
                    f"indirect-argument landing owner 0x{owner:X} has no LSDA")
            parsed = parse_lsda(data, except_section, record.lsda)
            landing_roots = sorted({
                owner + relative_landing
                for _, _, relative_landing, _ in parsed.call_sites
                if relative_landing
            })
            for root in landing_roots:
                graph = walk_landing_pad_cfg(
                    root, owner, record.end, instruction_word,
                    switch_destinations,
                )
                landing_graphs.append((root, graph))

        for site, row in sorted(rows_by_owner[owner]):
            (
                transfer_word,
                transfer_id,
                flow_id,
                target_register,
                role_id,
                arguments,
            ) = row
            transfer_kind = INDIRECT_ARGUMENT_TRANSFER_IDS[transfer_id]
            flow_class = INDIRECT_ARGUMENT_FLOW_IDS[flow_id]
            role = INDIRECT_ARGUMENT_ROLE_IDS[role_id]
            expected_flow = (
                "landing" if (owner, site) in landing_sites else "normal")
            if flow_class != expected_flow:
                raise ValueError(
                    f"indirect-argument flow class changed at 0x{site:X}: "
                    f"expected {expected_flow}, got {flow_class}")

            if flow_class == "normal":
                graph = normal_graph
                if site not in graph:
                    raise ValueError(
                        f"indirect-argument normal site 0x{site:X} is "
                        "not entry-reachable")
            else:
                if site in normal_graph:
                    raise ValueError(
                        f"indirect-argument landing site 0x{site:X} became "
                        "entry-reachable")
                matching_graphs = [
                    graph for _, graph in landing_graphs if site in graph
                ]
                if not matching_graphs:
                    raise ValueError(
                        f"indirect-argument landing site 0x{site:X} is "
                        "not reachable from any LSDA root")
                graph = {}
                for candidate in matching_graphs:
                    for address, instruction in candidate.items():
                        previous = graph.setdefault(address, instruction)
                        if previous != instruction:
                            raise ValueError(
                                "indirect-argument landing graphs disagree at "
                                f"0x{address:X}")

            actual_transfer_word = instruction_word(site)
            if (
                graph[site][0] != transfer_word
                or actual_transfer_word != transfer_word
            ):
                raise ValueError(
                    f"indirect-argument transfer changed at 0x{site:X}")
            abi_producer, abi_word, abi_role = abi_rows[(owner, site)]
            if role != abi_role:
                raise ValueError(
                    f"indirect-argument semantic role changed at 0x{site:X}")
            if instruction_word(abi_producer) != abi_word:
                raise ValueError(
                    f"indirect-argument target producer changed at "
                    f"0x{abi_producer:X}")

            predecessors: dict[int, list[int]] = {
                address: [] for address in graph
            }
            for source_address, (_, successors) in graph.items():
                for successor in successors:
                    predecessors.setdefault(successor, []).append(
                        source_address)

            seen_sites.add((owner, site))
            site_owners.add(owner)
            target_registers.add(target_register)
            transfer_counts[transfer_kind] = (
                transfer_counts.get(transfer_kind, 0) + 1)
            flow_counts[flow_class] = flow_counts.get(flow_class, 0) + 1
            site_role_counts[role] = site_role_counts.get(role, 0) + 1
            arity_counts[len(arguments)] = (
                arity_counts.get(len(arguments), 0) + 1)

            for (
                argument_index,
                bank_id,
                type_id,
                argument_size,
                sources,
            ) in arguments:
                bank = INDIRECT_ARGUMENT_BANK_IDS[bank_id]
                type_class = INDIRECT_ARGUMENT_TYPE_IDS[type_id]
                bank_counts[bank] = bank_counts.get(bank, 0) + 1
                argument_index_counts[argument_index] = (
                    argument_index_counts.get(argument_index, 0) + 1)
                type_size_key = (type_class, argument_size)
                type_size_counts[type_size_key] = (
                    type_size_counts.get(type_size_key, 0) + 1)
                cardinalities[len(sources)] = (
                    cardinalities.get(len(sources), 0) + 1)
                role_operand_counts[role] = (
                    role_operand_counts.get(role, 0) + 1)

                expected_instruction_sites: dict[
                    int, set[tuple[int, ...]]
                ] = {}
                expected_call_sites: dict[
                    int, set[tuple[int, ...]]
                ] = {}
                expected_entry = set()
                register = int(bank[1:])
                for source in sources:
                    (
                        source_role_id,
                        source_kind_id,
                        operand_index,
                        source_address,
                        source_word,
                    ) = source
                    source_role = INDIRECT_ARGUMENT_SOURCE_ROLE_IDS[
                        source_role_id]
                    source_kind = INDIRECT_ARGUMENT_SOURCE_KIND_IDS[
                        source_kind_id]
                    source_role_counts[source_role] += 1
                    source_kind_counts[source_kind] = (
                        source_kind_counts.get(source_kind, 0) + 1)

                    if source_role in {"entry-parameter", "entry-residue"}:
                        if flow_class != "normal":
                            raise ValueError(
                                "indirect-argument landing path gained an "
                                f"entry source at 0x{site:X}:{bank}")
                        expected_entry.add(source)
                        continue
                    if source_address not in graph:
                        raise ValueError(
                            "indirect-argument source is outside its explicit "
                            f"{flow_class} graph at 0x{source_address:X}")
                    actual_source_word = instruction_word(source_address)
                    if actual_source_word != source_word:
                        raise ValueError(
                            "indirect-argument source word changed at "
                            f"0x{source_address:X}: expected "
                            f"0x{source_word:08X}, got "
                            f"0x{actual_source_word:08X}")

                    if source_role in {"call-return", "call-clobber"}:
                        is_bl = source_word & 0xFC000000 == 0x94000000
                        is_blr = (
                            source_word & 0xFFFFFC1F == 0xD63F0000)
                        if not is_bl and not is_blr:
                            raise ValueError(
                                "indirect-argument call boundary changed at "
                                f"0x{source_address:X}")
                        if source_role == "call-return" and bank != "X0":
                            raise ValueError(
                                "indirect-argument call return feeds "
                                f"{bank} at 0x{site:X}")
                        expected_call_sites.setdefault(
                            source_address, set()).add(source)
                        continue

                    destination = indirect_argument_instruction_destination(
                        source_kind, operand_index, source_word)
                    if destination != register:
                        raise ValueError(
                            f"indirect-argument source writes X{destination}, "
                            f"expected {bank}, at 0x{source_address:X}")
                    expected_instruction_sites.setdefault(
                        source_address, set()).add(source)
                    if source_kind in {"LDP", "LDR"}:
                        source_class_counts["memory_sources"] += 1
                    elif source_kind == "MOV":
                        source_class_counts["transfer_sources"] += 1
                    elif source_kind == "ADD":
                        source_class_counts["address_sources"] += 1
                    elif source_kind == "CSEL":
                        source_class_counts["select_sources"] += 1

                # All recorded banks are AAPCS64 volatile.  Stop at the first
                # explicit writer on every predecessor path, or at a declared
                # call/entry boundary; importing stale register residue is an
                # error rather than a hidden source.
                hits = set()
                pending = list(predecessors.get(site, ()))
                visited = set()
                if not pending:
                    if not expected_entry:
                        raise ValueError(
                            "indirect-argument reaches an undeclared graph "
                            f"root at 0x{site:X}:{bank}")
                    hits.update(expected_entry)
                while pending:
                    address = pending.pop()
                    if address in visited:
                        continue
                    visited.add(address)

                    instruction_items = expected_instruction_sites.get(address)
                    if instruction_items:
                        hits.update(instruction_items)
                        continue

                    word = instruction_word(address)
                    is_prior_bl = word & 0xFC000000 == 0x94000000
                    is_prior_blr = word & 0xFFFFFC1F == 0xD63F0000
                    if is_prior_bl or is_prior_blr:
                        call_items = expected_call_sites.get(address)
                        if call_items:
                            hits.update(call_items)
                            continue
                        volatile_call_clobbers += 1
                        raise ValueError(
                            "indirect-argument backwards slice crosses an "
                            f"undeclared volatile {bank} call boundary at "
                            f"0x{owner:X}:0x{site:X}:0x{address:X}")

                    if (owner, bank, address) in explicit_writer_sources:
                        raise ValueError(
                            "indirect-argument path crosses an undeclared "
                            f"explicit {bank} writer at "
                            f"0x{owner:X}:0x{site:X}:0x{address:X}")

                    incoming = predecessors.get(address, ())
                    if incoming:
                        pending.extend(incoming)
                    else:
                        if not expected_entry:
                            raise ValueError(
                                "indirect-argument path reaches an undeclared "
                                f"{flow_class} root at "
                                f"0x{owner:X}:0x{site:X}:{bank}")
                        hits.update(expected_entry)

                if hits != set(sources):
                    missing = set(sources) - hits
                    extra = hits - set(sources)
                    raise ValueError(
                        "indirect-argument reaching sources changed at "
                        f"0x{owner:X}:0x{site:X}:{bank}: "
                        f"missing={missing}, extra={extra}")

    expectations = (
        ("arities", arity_counts, EXPECTED_INDIRECT_ARGUMENT_ARITIES),
        (
            "source cardinalities", cardinalities,
            EXPECTED_INDIRECT_ARGUMENT_CARDINALITIES,
        ),
        (
            "transfer kinds", transfer_counts,
            EXPECTED_INDIRECT_ARGUMENT_TRANSFER_COUNTS,
        ),
        ("flow classes", flow_counts, EXPECTED_INDIRECT_ARGUMENT_FLOW_COUNTS),
        ("banks", bank_counts, EXPECTED_INDIRECT_ARGUMENT_BANK_COUNTS),
        (
            "argument indices", argument_index_counts,
            EXPECTED_INDIRECT_ARGUMENT_INDEX_COUNTS,
        ),
        (
            "type/size pairs", type_size_counts,
            EXPECTED_INDIRECT_ARGUMENT_TYPE_SIZE_COUNTS,
        ),
        ("site roles", site_role_counts, EXPECTED_INDIRECT_ABI_ROLE_COUNTS),
        (
            "role operands", role_operand_counts,
            EXPECTED_INDIRECT_ARGUMENT_ROLE_OPERAND_COUNTS,
        ),
        (
            "source roles", source_role_counts,
            EXPECTED_INDIRECT_ARGUMENT_SOURCE_ROLE_COUNTS,
        ),
        (
            "source kinds", source_kind_counts,
            EXPECTED_INDIRECT_ARGUMENT_SOURCE_KIND_COUNTS,
        ),
    )
    for label, actual, expected in expectations:
        if actual != expected:
            raise ValueError(
                f"indirect-argument {label} changed: expected "
                f"{expected}, got {actual}")

    relation_count = sum(
        source_count * argument_count
        for source_count, argument_count in cardinalities.items()
    )
    operand_count = sum(bank_counts.values())
    counts = {
        "owners": len(site_owners),
        "sites": len(seen_sites),
        "relations": relation_count,
        "single_source": cardinalities.get(1, 0),
        "multi_source": operand_count - cardinalities.get(1, 0),
        "max_sources": max(cardinalities, default=0),
        "normal": flow_counts.get("normal", 0),
        "landing": flow_counts.get("landing", 0),
        "indirect_calls": transfer_counts.get("BLR", 0),
        "indirect_tails": transfer_counts.get("BR", 0),
        "operands": operand_count,
        "max_arity": max(arity_counts, default=0),
        "instruction": source_role_counts["instruction"],
        "entry": source_role_counts["entry-parameter"],
        "call_return": source_role_counts["call-return"],
        "call_clobber": source_role_counts["call-clobber"],
        "entry_residue": source_role_counts["entry-residue"],
        "volatile_call_clobbers": volatile_call_clobbers,
        **source_class_counts,
    }
    if counts != EXPECTED_INDIRECT_ARGUMENT_COUNTS:
        raise ValueError(
            "indirect-argument counts changed: expected "
            f"{EXPECTED_INDIRECT_ARGUMENT_COUNTS}, got {counts}")

    type_counts = {
        type_class: sum(
            count for (candidate, _), count in type_size_counts.items()
            if candidate == type_class
        )
        for type_class in INDIRECT_ARGUMENT_TYPE_IDS.values()
    }
    return {
        **counts,
        **{bank.lower(): count for bank, count in bank_counts.items()},
        **type_counts,
        "target_registers": len(target_registers),
        "semantic_roles": len(site_role_counts),
        "producer_classes": len(source_kind_counts),
    }


