def typed_member_read_producer_destination(
    producer_kind: str,
    producer_operand: int,
    word: int,
) -> tuple[int, str]:
    """Decode the destination lane of every direct member producer."""
    if producer_kind == "ADD":
        if (
            producer_operand != 0
            or word & 0x7F000000 not in {0x11000000, 0x0B000000}
        ):
            raise ValueError(
                f"typed-member read has invalid ADD word 0x{word:08X}")
        return word & 31, "X" if word & 0x80000000 else "W"

    opcode = word & 0xFFC00000
    if producer_kind == "LDP":
        if opcode != 0xA9400000 or producer_operand not in {0, 1}:
            raise ValueError(
                f"typed-member read has invalid LDP word 0x{word:08X}")
        register = (
            word & 31
            if producer_operand == 0
            else (word >> 10) & 31
        )
        return register, "X"

    if producer_operand != 0:
        raise ValueError(
            f"typed-member read {producer_kind} has invalid operand "
            f"{producer_operand}")
    if producer_kind == "LDR":
        valid = opcode in {0xB9400000, 0xF9400000} or (
            opcode == 0xF8400000 and word & 0xC00 != 0
        )
        width = "W" if opcode == 0xB9400000 else "X"
    elif producer_kind == "LDRB":
        valid = opcode == 0x39400000 or (
            opcode == 0x38400000 and word & 0xC00 != 0
        )
        width = "W"
    elif producer_kind == "LDRH":
        valid = opcode == 0x79400000
        width = "W"
    elif producer_kind == "LDUR":
        valid = opcode == 0xB8400000 and word & 0xC00 == 0
        width = "W"
    elif producer_kind == "LDURH":
        valid = opcode == 0x78400000 and word & 0xC00 == 0
        width = "W"
    else:
        valid = False
        width = "X"
    if not valid:
        raise ValueError(
            f"typed-member read has invalid {producer_kind} word "
            f"0x{word:08X}")
    return word & 31, width


def typed_member_read_anchor_source_destination(
    source_kind: str,
    change_mask: int,
    word: int,
) -> int:
    """Decode the destination bank of every residual-anchor source."""
    if source_kind == "LDP":
        if word & 0xFFC00000 != 0xA9400000:
            raise ValueError(
                f"typed-member read anchor has invalid LDP 0x{word:08X}")
        if change_mask == 1:
            return word & 31
        if change_mask == 2:
            return (word >> 10) & 31
    elif change_mask == 1:
        if source_kind == "ADD":
            valid = word & 0x7F000000 in {0x11000000, 0x0B000000}
        elif source_kind == "LDR":
            valid = word & 0xFFC00000 in {0xB9400000, 0xF9400000}
        elif source_kind == "MOV":
            valid = (
                word & 0x7F8003E0 == 0x320003E0
                or word & 0x7FE0FFE0 == 0x2A0003E0
            )
        elif source_kind == "SUBS":
            valid = word & 0x7F000000 in {0x71000000, 0x6B000000}
        else:
            valid = False
        if valid:
            return word & 31
    raise ValueError(
        f"typed-member read anchor has invalid {source_kind}/"
        f"change-mask {change_mask} word 0x{word:08X}")


def read_typed_member_read_producer_manifest(
) -> tuple[TypedMemberReadProducer, ...]:
    """Decode the canonical direct-producer/first-consumer manifest."""
    try:
        compressed = base64.b64decode(
            EXPECTED_TYPED_MEMBER_READ_PRODUCER_ZLIB_BASE64,
            validate=True,
        )
        raw = zlib.decompress(compressed)
    except (binascii.Error, ValueError, zlib.error) as exc:
        raise ValueError(
            f"typed-member read producer manifest cannot be decoded: {exc}"
        ) from exc
    if len(raw) != EXPECTED_TYPED_MEMBER_READ_PRODUCER_RAW_BYTES:
        raise ValueError(
            "typed-member read producer manifest size changed: expected "
            f"{EXPECTED_TYPED_MEMBER_READ_PRODUCER_RAW_BYTES}, got "
            f"{len(raw)}")
    digest = hashlib.sha256(raw).hexdigest()
    if digest != EXPECTED_TYPED_MEMBER_READ_PRODUCER_SHA256:
        raise ValueError(
            "typed-member read producer manifest digest changed: expected "
            f"{EXPECTED_TYPED_MEMBER_READ_PRODUCER_SHA256}, got {digest}")

    header = struct.Struct("<III8BhB")
    event_record = struct.Struct("<BBBBII")
    rows = []
    offset = 0
    previous_key = None
    while offset < len(raw):
        if offset + header.size > len(raw):
            raise ValueError(
                "typed-member read producer manifest has a truncated header")
        (
            owner,
            site,
            producer_word,
            mode_id,
            producer_kind_id,
            producer_operand,
            bank,
            width_id,
            base_type_id,
            member_type_id,
            op_id,
            field_offset,
            event_count,
        ) = header.unpack_from(raw, offset)
        offset += header.size
        mode = TYPED_MEMBER_READ_MODE_IDS.get(mode_id)
        producer_kind = TYPED_MEMBER_READ_PRODUCER_KIND_IDS.get(
            producer_kind_id)
        width = TYPED_MEMBER_READ_WIDTH_IDS.get(width_id)
        base_type = TYPED_MEMBER_READ_BASE_TYPE_IDS.get(base_type_id)
        member_type = TYPED_MEMBER_READ_MEMBER_TYPE_IDS.get(member_type_id)
        op = TYPED_MEMBER_READ_OP_IDS.get(op_id)
        if (
            mode is None
            or producer_kind is None
            or width is None
            or base_type is None
            or member_type is None
            or op is None
            or not event_count
            or owner & 3
            or site & 3
            or site < owner
            or bank >= 31
        ):
            raise ValueError(
                f"typed-member read producer header is invalid at "
                f"0x{site:X}")
        actual_bank, actual_width = typed_member_read_producer_destination(
            producer_kind, producer_operand, producer_word)
        if actual_bank != bank or actual_width != width:
            raise ValueError(
                f"typed-member read producer destination changed at "
                f"0x{site:X}")

        events = []
        for _ in range(event_count):
            if offset + event_record.size > len(raw):
                raise ValueError(
                    "typed-member read producer manifest has a truncated "
                    f"event at 0x{site:X}")
            event = event_record.unpack_from(raw, offset)
            offset += event_record.size
            (
                role_id,
                mnemonic_id,
                use_mask,
                change_mask,
                event_address,
                event_word,
            ) = event
            role = TYPED_MEMBER_READ_EVENT_ROLE_IDS.get(role_id)
            mnemonic = TYPED_MEMBER_READ_EVENT_MNEMONIC_IDS.get(mnemonic_id)
            if (
                role is None
                or mnemonic is None
                or event_address & 3
                or event_address < owner
                or not event_word
            ):
                raise ValueError(
                    f"typed-member read event is invalid at "
                    f"0x{site:X}:0x{event_address:X}")
            if role == "use":
                valid_masks = use_mask != 0 and change_mask == 0
            elif role == "transform":
                valid_masks = use_mask != 0 and change_mask != 0
            elif role == "call-use":
                valid_masks = (
                    use_mask == 0x80
                    and change_mask == 0
                    and mnemonic in {"B", "BL", "BLR"}
                )
            elif role == "call-boundary":
                valid_masks = (
                    use_mask == 0
                    and change_mask == 0
                    and mnemonic in {"BL", "BLR"}
                )
            else:
                valid_masks = (
                    use_mask == 0
                    and change_mask == 0
                    and mnemonic == "RET"
                )
            if not valid_masks:
                raise ValueError(
                    f"typed-member read event masks are invalid at "
                    f"0x{event_address:X}")
            events.append(event)
        canonical_events = tuple(sorted(
            events,
            key=lambda item: (
                item[4], item[0], item[2], item[3], item[1],
            ),
        ))
        if (
            tuple(events) != canonical_events
            or len(set(events)) != len(events)
            or len({event[4] for event in events}) != len(events)
        ):
            raise ValueError(
                f"typed-member read events are non-canonical at 0x{site:X}")

        key = (
            owner,
            site,
            mode_id,
            base_type_id,
            member_type_id,
            field_offset,
            op_id,
            producer_operand,
            bank,
            producer_kind_id,
            width_id,
        )
        if previous_key is not None and key <= previous_key:
            raise ValueError(
                f"typed-member read producer rows are non-canonical at "
                f"0x{site:X}")
        previous_key = key
        rows.append(TypedMemberReadProducer(
            owner,
            site,
            producer_word,
            mode,
            producer_kind,
            producer_operand,
            bank,
            width,
            base_type,
            member_type,
            op,
            field_offset,
            tuple(events),
        ))
    if len(rows) != EXPECTED_TYPED_MEMBER_READ_COUNTS["producer_lanes"]:
        raise ValueError(
            "typed-member read producer lane count changed: expected "
            f"{EXPECTED_TYPED_MEMBER_READ_COUNTS['producer_lanes']}, got "
            f"{len(rows)}")
    return tuple(rows)


def read_typed_member_read_anchor_manifest(
) -> tuple[TypedMemberReadAnchor, ...]:
    """Decode the canonical residual-anchor/backwards-source manifest."""
    try:
        compressed = base64.b64decode(
            EXPECTED_TYPED_MEMBER_READ_ANCHOR_ZLIB_BASE64,
            validate=True,
        )
        raw = zlib.decompress(compressed)
    except (binascii.Error, ValueError, zlib.error) as exc:
        raise ValueError(
            f"typed-member read anchor manifest cannot be decoded: {exc}"
        ) from exc
    if len(raw) != EXPECTED_TYPED_MEMBER_READ_ANCHOR_RAW_BYTES:
        raise ValueError(
            "typed-member read anchor manifest size changed: expected "
            f"{EXPECTED_TYPED_MEMBER_READ_ANCHOR_RAW_BYTES}, got {len(raw)}")
    digest = hashlib.sha256(raw).hexdigest()
    if digest != EXPECTED_TYPED_MEMBER_READ_ANCHOR_SHA256:
        raise ValueError(
            "typed-member read anchor manifest digest changed: expected "
            f"{EXPECTED_TYPED_MEMBER_READ_ANCHOR_SHA256}, got {digest}")

    header = struct.Struct("<IIIII8BhB")
    source_record = struct.Struct("<BBBII")
    rows = []
    offset = 0
    previous_key = None
    while offset < len(raw):
        if offset + header.size > len(raw):
            raise ValueError(
                "typed-member read anchor manifest has a truncated header")
        (
            owner,
            site,
            site_word,
            consumer,
            consumer_word,
            mode_id,
            anchor_class_id,
            consumer_operand,
            bank,
            width_id,
            base_type_id,
            member_type_id,
            op_id,
            field_offset,
            source_count,
        ) = header.unpack_from(raw, offset)
        offset += header.size
        mode = TYPED_MEMBER_READ_MODE_IDS.get(mode_id)
        anchor_class = TYPED_MEMBER_READ_ANCHOR_CLASS_IDS.get(
            anchor_class_id)
        width = TYPED_MEMBER_READ_WIDTH_IDS.get(width_id)
        base_type = TYPED_MEMBER_READ_BASE_TYPE_IDS.get(base_type_id)
        member_type = TYPED_MEMBER_READ_MEMBER_TYPE_IDS.get(member_type_id)
        op = TYPED_MEMBER_READ_OP_IDS.get(op_id)
        if (
            mode is None
            or anchor_class is None
            or width is None
            or base_type is None
            or member_type is None
            or op is None
            or not source_count
            or owner & 3
            or site & 3
            or consumer & 3
            or min(site, consumer) < owner
            or bank > 31
            or consumer_operand > 1
        ):
            raise ValueError(
                f"typed-member read anchor header is invalid at 0x{site:X}")

        sources = []
        for _ in range(source_count):
            if offset + source_record.size > len(raw):
                raise ValueError(
                    "typed-member read anchor manifest has a truncated "
                    f"source at 0x{site:X}")
            source = source_record.unpack_from(raw, offset)
            offset += source_record.size
            role_id, source_kind_id, change_mask, source_address, source_word = (
                source
            )
            role = TYPED_MEMBER_READ_SOURCE_ROLE_IDS.get(role_id)
            source_kind = TYPED_MEMBER_READ_SOURCE_KIND_IDS.get(source_kind_id)
            if (
                role is None
                or source_kind is None
                or source_address & 3
                or source_address < owner
            ):
                raise ValueError(
                    f"typed-member read anchor source is invalid at "
                    f"0x{site:X}:0x{source_address:X}")
            if role == "zero-register":
                valid_source = (
                    source_kind == "ZERO"
                    and bank == 31
                    and change_mask == 0
                    and source_address == consumer
                    and source_word == consumer_word
                )
            elif role == "instruction":
                valid_source = (
                    source_kind != "ZERO"
                    and bank < 31
                    and source_word != 0
                    and typed_member_read_anchor_source_destination(
                        source_kind, change_mask, source_word
                    ) == bank
                )
            else:
                valid_source = False
            if not valid_source:
                raise ValueError(
                    f"typed-member read anchor source role/kind is invalid at "
                    f"0x{site:X}:0x{source_address:X}")
            sources.append(source)
        canonical_sources = tuple(sorted(
            sources,
            key=lambda item: (item[3], item[0], item[2], item[1]),
        ))
        if tuple(sources) != canonical_sources or len(set(sources)) != len(
            sources
        ):
            raise ValueError(
                f"typed-member read anchor sources are non-canonical at "
                f"0x{site:X}")

        key = (
            owner,
            site,
            mode_id,
            base_type_id,
            member_type_id,
            field_offset,
            op_id,
            anchor_class_id,
            consumer,
            consumer_operand,
            bank,
            width_id,
        )
        if previous_key is not None and key <= previous_key:
            raise ValueError(
                f"typed-member read anchor rows are non-canonical at "
                f"0x{site:X}")
        previous_key = key
        rows.append(TypedMemberReadAnchor(
            owner,
            site,
            site_word,
            consumer,
            consumer_word,
            mode,
            anchor_class,
            consumer_operand,
            bank,
            width,
            base_type,
            member_type,
            op,
            field_offset,
            tuple(sources),
        ))
    if len(rows) != EXPECTED_TYPED_MEMBER_READ_COUNTS["anchor_lanes"]:
        raise ValueError(
            "typed-member read anchor lane count changed: expected "
            f"{EXPECTED_TYPED_MEMBER_READ_COUNTS['anchor_lanes']}, got "
            f"{len(rows)}")
    return tuple(rows)


def typed_member_synthetic_word_matches_mnemonic(
    mnemonic: str,
    word: int,
) -> bool:
    """Recognize the six emitted anchor instruction families."""
    if mnemonic == "STR":
        return (
            word & 0xFFC00000
            in {0xB9000000, 0xF9000000, 0x3D800000}
            or word & 0xFFC00C00 == 0xF8000400
        )
    if mnemonic == "STP":
        return word & 0xFFC00000 == 0xA9000000
    if mnemonic == "STRB":
        return word & 0xFFC00000 == 0x39000000
    if mnemonic == "LDR":
        return word & 0xFFC00000 == 0xF9400000
    if mnemonic == "BLR":
        return word & 0xFFFFFC1F == 0xD63F0000
    if mnemonic == "BR":
        return word & 0xFFFFFC1F == 0xD61F0000
    return False


def read_typed_member_synthetic_manifest(
) -> tuple[TypedMemberSyntheticRow, ...]:
    """Decode synthetic ctree rows and their nearest machine anchors."""
    try:
        compressed = base64.b64decode(
            EXPECTED_TYPED_MEMBER_SYNTHETIC_ZLIB_BASE64,
            validate=True,
        )
        raw = zlib.decompress(compressed)
    except (binascii.Error, ValueError, zlib.error) as exc:
        raise ValueError(
            f"typed-member synthetic manifest cannot be decoded: {exc}"
        ) from exc
    if len(raw) != EXPECTED_TYPED_MEMBER_SYNTHETIC_RAW_BYTES:
        raise ValueError(
            "typed-member synthetic manifest size changed: expected "
            f"{EXPECTED_TYPED_MEMBER_SYNTHETIC_RAW_BYTES}, got {len(raw)}")
    digest = hashlib.sha256(raw).hexdigest()
    if digest != EXPECTED_TYPED_MEMBER_SYNTHETIC_SHA256:
        raise ValueError(
            "typed-member synthetic manifest digest changed: expected "
            f"{EXPECTED_TYPED_MEMBER_SYNTHETIC_SHA256}, got {digest}")

    header = struct.Struct("<IBBhHHHB")
    occurrence_record = struct.Struct("<BBBII")
    rows = []
    offset = 0
    previous_key = None
    while offset < len(raw):
        if offset + header.size > len(raw):
            raise ValueError(
                "typed-member synthetic manifest has a truncated header")
        (
            owner,
            mode_id,
            op_id,
            field_offset,
            base_type_size,
            member_type_size,
            expression_size,
            occurrence_count,
        ) = header.unpack_from(raw, offset)
        offset += header.size
        mode = TYPED_MEMBER_SYNTHETIC_MODE_IDS.get(mode_id)
        op = TYPED_MEMBER_SYNTHETIC_OP_IDS.get(op_id)
        if (
            mode is None
            or op is None
            or owner & 3
            or not base_type_size
            or not member_type_size
            or not expression_size
            or not occurrence_count
        ):
            raise ValueError(
                f"typed-member synthetic header is invalid at 0x{owner:X}")

        strings = []
        for size, label in (
            (base_type_size, "base type"),
            (member_type_size, "member type"),
            (expression_size, "expression"),
        ):
            if offset + size > len(raw):
                raise ValueError(
                    "typed-member synthetic manifest has a truncated "
                    f"{label} at 0x{owner:X}")
            encoded = raw[offset:offset + size]
            offset += size
            try:
                decoded = encoded.decode("utf-8")
            except UnicodeDecodeError as exc:
                raise ValueError(
                    f"typed-member synthetic {label} is not UTF-8 at "
                    f"0x{owner:X}"
                ) from exc
            if not decoded or "\0" in decoded:
                raise ValueError(
                    f"typed-member synthetic {label} is invalid at "
                    f"0x{owner:X}")
            strings.append(decoded)
        base_type, member_type, expression = strings

        occurrences = []
        for _ in range(occurrence_count):
            if offset + occurrence_record.size > len(raw):
                raise ValueError(
                    "typed-member synthetic manifest has a truncated "
                    f"occurrence at 0x{owner:X}")
            (
                parent_op_id,
                realization_class_id,
                mnemonic_id,
                address,
                word,
            ) = occurrence_record.unpack_from(raw, offset)
            offset += occurrence_record.size
            parent_op = TYPED_MEMBER_SYNTHETIC_PARENT_OP_IDS.get(
                parent_op_id)
            realization_class = (
                TYPED_MEMBER_SYNTHETIC_REALIZATION_CLASS_IDS.get(
                    realization_class_id)
            )
            mnemonic = TYPED_MEMBER_SYNTHETIC_MNEMONIC_IDS.get(mnemonic_id)
            if (
                parent_op is None
                or realization_class is None
                or mnemonic is None
                or address & 3
                or address < owner
                or not word
                or not typed_member_synthetic_word_matches_mnemonic(
                    mnemonic, word)
            ):
                raise ValueError(
                    "typed-member synthetic occurrence is invalid at "
                    f"0x{owner:X}:0x{address:X}")
            occurrences.append((
                parent_op,
                realization_class,
                mnemonic,
                address,
                word,
            ))
        canonical_occurrences = tuple(sorted(
            occurrences,
            key=lambda item: (item[3], item[0], item[1], item[2], item[4]),
        ))
        if (
            tuple(occurrences) != canonical_occurrences
            or len(set(occurrences)) != len(occurrences)
            or len({item[3] for item in occurrences}) != len(occurrences)
        ):
            raise ValueError(
                "typed-member synthetic occurrences are non-canonical at "
                f"0x{owner:X}")

        key = (
            owner,
            mode_id,
            expression,
            base_type,
            member_type,
            field_offset,
            op_id,
        )
        if previous_key is not None and key <= previous_key:
            raise ValueError(
                "typed-member synthetic rows are non-canonical at "
                f"0x{owner:X}:{expression}")
        previous_key = key
        rows.append(TypedMemberSyntheticRow(
            owner,
            mode,
            op,
            field_offset,
            base_type,
            member_type,
            expression,
            tuple(occurrences),
        ))
    if len(rows) != EXPECTED_TYPED_MEMBER_SYNTHETIC_COUNTS["semantic_rows"]:
        raise ValueError(
            "typed-member synthetic row count changed: expected "
            f"{EXPECTED_TYPED_MEMBER_SYNTHETIC_COUNTS['semantic_rows']}, "
            f"got {len(rows)}")
    return tuple(rows)


def decode_typed_member_store_operands(
    store_kind: str,
    word: int,
) -> tuple[tuple[int, str, int], ...]:
    """Decode the selected value operands of the four emitted store forms."""
    opcode = word & 0xFFC00000
    if store_kind == "STRB" and opcode == 0x39000000:
        registers = ((0, word & 31, 1),)
    elif store_kind == "STRH" and opcode == 0x79000000:
        registers = ((0, word & 31, 2),)
    elif store_kind == "STR" and opcode in {0xB9000000, 0xF9000000}:
        registers = ((0, word & 31, 4 if opcode == 0xB9000000 else 8),)
    elif store_kind == "STP" and opcode == 0xA9000000:
        registers = (
            (0, word & 31, 8),
            (1, (word >> 10) & 31, 8),
        )
    else:
        raise ValueError(
            f"typed-member write has invalid {store_kind} word "
            f"0x{word:08X}")
    return tuple(
        (operand, "ZR" if register == 31 else f"X{register}", size)
        for operand, register, size in registers
    )


def typed_member_write_instruction_destination(
    source_kind: str,
    operand_index: int,
    word: int,
) -> int:
    """Decode and validate every explicit value-producer class in the surface."""
    if operand_index != 0:
        raise ValueError(
            f"typed-member write {source_kind} uses unsupported operand "
            f"{operand_index}")

    opcode = word & 0x7F000000
    valid = False
    if source_kind == "ADD":
        valid = opcode in {0x11000000, 0x0B000000}
    elif source_kind == "SUB":
        valid = opcode in {0x51000000, 0x4B000000}
    elif source_kind == "SUBS":
        valid = opcode in {0x71000000, 0x6B000000}
    elif source_kind == "LDR":
        valid = word & 0xFFC00000 in {0xB9400000, 0xF9400000}
    elif source_kind == "LDRH":
        valid = word & 0xFFC00000 == 0x79400000
    elif source_kind == "MOV":
        valid = (
            word & 0x7F8003E0 == 0x320003E0
            or word & 0x7FE0FFE0 == 0x2A0003E0
        )
    if not valid:
        raise ValueError(
            f"typed-member write source kind {source_kind} does not match "
            f"word 0x{word:08X}")
    return word & 31


def read_typed_member_write_manifest() -> tuple[TypedMemberWriteEvent, ...]:
    """Decode the canonical member-write/value-producer manifest."""
    try:
        compressed = base64.b64decode(
            EXPECTED_TYPED_MEMBER_WRITE_ZLIB_BASE64,
            validate=True,
        )
        raw = zlib.decompress(compressed)
    except (binascii.Error, ValueError, zlib.error) as exc:
        raise ValueError(
            f"typed-member write manifest cannot be decoded: {exc}") \
            from exc

    if len(raw) != EXPECTED_TYPED_MEMBER_WRITE_RAW_BYTES:
        raise ValueError(
            "typed-member write manifest size changed: expected "
            f"{EXPECTED_TYPED_MEMBER_WRITE_RAW_BYTES}, got {len(raw)}")
    digest = hashlib.sha256(raw).hexdigest()
    if digest != EXPECTED_TYPED_MEMBER_WRITE_SHA256:
        raise ValueError(
            "typed-member write manifest digest changed: expected "
            f"{EXPECTED_TYPED_MEMBER_WRITE_SHA256}, got {digest}")

    event_header = struct.Struct("<III8BHB")
    source_record = struct.Struct("<BBBII")
    events = []
    offset = 0
    previous_key = None
    while offset < len(raw):
        if offset + event_header.size > len(raw):
            raise ValueError(
                "typed-member write manifest has a truncated event header")
        (
            owner,
            site,
            store_word,
            store_kind_id,
            value_operand_index,
            bank_id,
            mode_id,
            type_id,
            store_size,
            base_type_id,
            field_type_id,
            field_offset,
            source_count,
        ) = event_header.unpack_from(raw, offset)
        offset += event_header.size

        store_kind = TYPED_MEMBER_WRITE_STORE_KIND_IDS.get(store_kind_id)
        mode = TYPED_MEMBER_WRITE_MODE_IDS.get(mode_id)
        type_class = TYPED_MEMBER_WRITE_TYPE_IDS.get(type_id)
        base_type = TYPED_MEMBER_WRITE_BASE_TYPE_IDS.get(base_type_id)
        field_type = TYPED_MEMBER_WRITE_FIELD_TYPE_IDS.get(field_type_id)
        bank = "ZR" if bank_id == 0 else f"X{bank_id - 1}"
        if (
            store_kind is None
            or mode is None
            or type_class is None
            or base_type is None
            or field_type is None
            or bank_id > 31
            or not source_count
        ):
            raise ValueError(
                f"typed-member write event IDs are invalid at 0x{site:X}")
        if owner & 3 or site & 3 or not owner <= site:
            raise ValueError(
                f"typed-member write event address is invalid at 0x{site:X}")
        if TYPED_MEMBER_WRITE_FIELD_TYPE_CONTRACTS[field_type] != (
            type_class,
            store_size,
        ):
            raise ValueError(
                f"typed-member write field contract changed at 0x{site:X}")

        operands = decode_typed_member_store_operands(store_kind, store_word)
        matching_operands = tuple(
            item for item in operands if item[0] == value_operand_index)
        if matching_operands != ((value_operand_index, bank, store_size),):
            raise ValueError(
                f"typed-member write selected operand is invalid at "
                f"0x{site:X}")

        sources = []
        for _ in range(source_count):
            if offset + source_record.size > len(raw):
                raise ValueError(
                    "typed-member write manifest has a truncated source at "
                    f"0x{site:X}")
            source = source_record.unpack_from(raw, offset)
            offset += source_record.size
            (
                source_role_id,
                source_kind_id,
                operand_index,
                source_address,
                source_word,
            ) = source
            source_role = TYPED_MEMBER_WRITE_SOURCE_ROLE_IDS.get(
                source_role_id)
            source_kind = TYPED_MEMBER_WRITE_SOURCE_KIND_IDS.get(
                source_kind_id)
            if source_role is None or source_kind is None:
                raise ValueError(
                    f"typed-member write source IDs are invalid at 0x{site:X}")
            if source_role in {"entry-parameter", "entry-residue"}:
                valid_source = (
                    source_kind == "ENTRY"
                    and operand_index == 0
                    and source_address == owner
                    and source_word == 0
                    and bank != "ZR"
                )
            elif source_role == "zero-register":
                valid_source = (
                    source_kind == "ZERO"
                    and operand_index == value_operand_index
                    and source_address == site
                    and source_word == store_word
                    and bank == "ZR"
                    and source_count == 1
                )
            elif source_role == "instruction":
                valid_source = (
                    source_kind
                    not in {"ENTRY", "ZERO", "BL", "BLR"}
                    and operand_index == 0
                    and owner <= source_address < site
                    and source_address & 3 == 0
                    and source_word != 0
                )
            else:
                valid_source = (
                    source_kind in {"BL", "BLR"}
                    and operand_index == 0
                    and owner <= source_address < site
                    and source_address & 3 == 0
                    and source_word != 0
                    and bank != "ZR"
                )
            if not valid_source:
                raise ValueError(
                    "typed-member write source role/kind mismatch at "
                    f"0x{site:X}:0x{source_address:X}")
            sources.append(source)

        canonical_sources = sorted(
            sources,
            key=lambda item: (item[3], item[0], item[2], item[1]),
        )
        if sources != canonical_sources or len(set(sources)) != len(sources):
            raise ValueError(
                f"typed-member write sources are non-canonical at 0x{site:X}")

        key = (
            owner,
            site,
            base_type_id,
            field_offset,
            field_type_id,
            value_operand_index,
        )
        if previous_key is not None and key <= previous_key:
            raise ValueError(
                f"typed-member write events are non-canonical at 0x{site:X}")
        previous_key = key
        events.append(TypedMemberWriteEvent(
            owner=owner,
            site=site,
            store_word=store_word,
            store_kind=store_kind,
            value_operand_index=value_operand_index,
            bank=bank,
            mode=mode,
            type_class=type_class,
            store_size=store_size,
            base_type=base_type,
            field_type=field_type,
            field_offset=field_offset,
            sources=tuple(sources),
        ))

    expected_events = EXPECTED_TYPED_MEMBER_WRITE_COUNTS["events"]
    if len(events) != expected_events:
        raise ValueError(
            "typed-member write event count changed: expected "
            f"{expected_events}, got {len(events)}")
    return tuple(events)


def verify_typed_member_write_surface(
    binary: Path,
    fdes: dict[int, FdeRecord],
    manifest: set[int],
) -> dict[str, int]:
    """Prove every instruction-backed member W/RW value producer."""
    events = read_typed_member_write_manifest()
    data = binary.read_bytes()

    switch_destinations: dict[int, tuple[int, ...]] = {}
    for owner, site, table, entry_count, _ in EXPECTED_SWITCH_TABLE_SURFACES:
        raw = read_elf_vma(
            data, table, entry_count * 4,
            f"typed-member write switch table 0x{table:X}",
        )
        destinations = tuple(sorted({
            table + displacement
            for displacement in struct.unpack(f"<{entry_count}i", raw)
        }))
        record = fdes.get(owner)
        if record is None or any(
            not owner <= destination < record.end
            for destination in destinations
        ):
            raise ValueError(
                f"typed-member write switch 0x{site:X} escapes owner "
                f"0x{owner:X}")
        switch_destinations[site] = destinations

    noreturn_targets = frozenset(
        target for target, _, _ in EXPECTED_NORMAL_NORETURN_TARGETS)
    typed_member_sites = frozenset(EXPECTED_TYPED_MEMBER_INSTRUCTION_SITES)
    rows_by_owner: dict[int, list[TypedMemberWriteEvent]] = {}
    explicit_writer_sources: dict[
        tuple[int, str, int], set[tuple[int, ...]]
    ] = {}
    for event in events:
        if event.owner not in manifest:
            raise ValueError(
                f"typed-member write owner 0x{event.owner:X} is outside "
                "MANIFEST")
        if event.site not in typed_member_sites:
            raise ValueError(
                f"typed-member write site 0x{event.site:X} is outside the "
                "instruction-backed member surface")
        rows_by_owner.setdefault(event.owner, []).append(event)
        for source in event.sources:
            source_role = TYPED_MEMBER_WRITE_SOURCE_ROLE_IDS[source[0]]
            if source_role == "instruction":
                explicit_writer_sources.setdefault(
                    (event.owner, event.bank, source[3]), set()
                ).add(source)

    store_counts: dict[str, int] = {}
    store_site_kinds: dict[tuple[int, int], str] = {}
    mode_counts: dict[str, int] = {}
    operand_counts: dict[int, int] = {}
    bank_counts: dict[str, int] = {}
    type_size_counts: dict[tuple[str, int], int] = {}
    base_type_counts: dict[str, int] = {}
    field_type_counts: dict[str, int] = {}
    cardinalities: dict[int, int] = {}
    source_role_counts = {
        role: 0 for role in TYPED_MEMBER_WRITE_SOURCE_ROLE_IDS.values()
    }
    source_kind_counts: dict[str, int] = {}
    source_class_counts = {
        "memory_sources": 0,
        "transfer_sources": 0,
        "address_sources": 0,
        "arithmetic_sources": 0,
    }
    observed_sites = set()
    observed_owners = set()
    entry_sources = set()
    normal_events = 0
    landing_events = 0
    volatile_call_clobbers = 0

    for owner in sorted(rows_by_owner):
        record = fdes.get(owner)
        if record is None:
            raise ValueError(
                f"typed-member write owner 0x{owner:X} has no FDE")
        function_raw = read_elf_vma(
            data, owner, record.end - owner,
            f"typed-member write owner 0x{owner:X}",
        )

        def instruction_word(address: int) -> int:
            offset = address - owner
            if offset < 0 or offset + 4 > len(function_raw):
                raise ValueError(
                    f"typed-member write instruction 0x{address:X} is "
                    f"outside owner 0x{owner:X}")
            return struct.unpack_from("<I", function_raw, offset)[0]

        graph = walk_normal_cfg(
            owner, owner, record.end, instruction_word,
            switch_destinations, noreturn_targets,
        )
        predecessors: dict[int, list[int]] = {
            address: [] for address in graph
        }
        for source_address, (_, successors) in graph.items():
            for successor in successors:
                predecessors.setdefault(successor, []).append(source_address)

        for event in rows_by_owner[owner]:
            if event.site not in graph:
                landing_events += 1
                raise ValueError(
                    f"typed-member write site 0x{event.site:X} is not "
                    "normal-entry reachable")
            normal_events += 1
            if (
                graph[event.site][0] != event.store_word
                or instruction_word(event.site) != event.store_word
            ):
                raise ValueError(
                    f"typed-member write store changed at 0x{event.site:X}")

            observed_sites.add((owner, event.site))
            observed_owners.add(owner)
            store_counts[event.store_kind] = (
                store_counts.get(event.store_kind, 0) + 1)
            site_key = (owner, event.site)
            prior_kind = store_site_kinds.setdefault(
                site_key, event.store_kind)
            if prior_kind != event.store_kind:
                raise ValueError(
                    f"typed-member write store kind disagrees at "
                    f"0x{event.site:X}")
            mode_counts[event.mode] = mode_counts.get(event.mode, 0) + 1
            operand_counts[event.value_operand_index] = (
                operand_counts.get(event.value_operand_index, 0) + 1)
            bank_counts[event.bank] = bank_counts.get(event.bank, 0) + 1
            type_key = (event.type_class, event.store_size)
            type_size_counts[type_key] = type_size_counts.get(type_key, 0) + 1
            base_type_counts[event.base_type] = (
                base_type_counts.get(event.base_type, 0) + 1)
            field_type_counts[event.field_type] = (
                field_type_counts.get(event.field_type, 0) + 1)
            cardinalities[len(event.sources)] = (
                cardinalities.get(len(event.sources), 0) + 1)

            expected_instruction_sites: dict[
                int, set[tuple[int, ...]]
            ] = {}
            expected_call_sites: dict[int, set[tuple[int, ...]]] = {}
            expected_entry = set()
            expected_zero = set()
            register = None if event.bank == "ZR" else int(event.bank[1:])
            for source in event.sources:
                (
                    source_role_id,
                    source_kind_id,
                    operand_index,
                    source_address,
                    source_word,
                ) = source
                source_role = TYPED_MEMBER_WRITE_SOURCE_ROLE_IDS[
                    source_role_id]
                source_kind = TYPED_MEMBER_WRITE_SOURCE_KIND_IDS[
                    source_kind_id]
                source_role_counts[source_role] += 1
                source_kind_counts[source_kind] = (
                    source_kind_counts.get(source_kind, 0) + 1)

                if source_role in {"entry-parameter", "entry-residue"}:
                    expected_entry.add(source)
                    entry_sources.add((owner, event.site, event.bank))
                    continue
                if source_role == "zero-register":
                    expected_zero.add(source)
                    continue
                if source_address not in graph:
                    raise ValueError(
                        "typed-member write source is outside normal CFG at "
                        f"0x{source_address:X}")
                actual_source_word = instruction_word(source_address)
                if actual_source_word != source_word:
                    raise ValueError(
                        "typed-member write source word changed at "
                        f"0x{source_address:X}: expected "
                        f"0x{source_word:08X}, got 0x{actual_source_word:08X}")

                if source_role in {"call-return", "call-clobber"}:
                    is_bl = source_word & 0xFC000000 == 0x94000000
                    is_blr = source_word & 0xFFFFFC1F == 0xD63F0000
                    if not is_bl and not is_blr:
                        raise ValueError(
                            "typed-member write call boundary changed at "
                            f"0x{source_address:X}")
                    if source_role == "call-return" and event.bank != "X0":
                        raise ValueError(
                            "typed-member write call return feeds "
                            f"{event.bank} at 0x{event.site:X}")
                    expected_call_sites.setdefault(
                        source_address, set()).add(source)
                    continue

                destination = typed_member_write_instruction_destination(
                    source_kind, operand_index, source_word)
                if destination != register:
                    raise ValueError(
                        f"typed-member write source writes X{destination}, "
                        f"expected {event.bank}, at 0x{source_address:X}")
                expected_instruction_sites.setdefault(
                    source_address, set()).add(source)
                if source_kind in {"LDR", "LDRH"}:
                    source_class_counts["memory_sources"] += 1
                elif source_kind == "MOV":
                    source_class_counts["transfer_sources"] += 1
                elif source_kind == "ADD":
                    source_class_counts["address_sources"] += 1
                elif source_kind in {"SUB", "SUBS"}:
                    source_class_counts["arithmetic_sources"] += 1

            if expected_zero:
                if expected_zero != set(event.sources):
                    raise ValueError(
                        "typed-member write zero source is mixed with a "
                        f"backwards-sliced source at 0x{event.site:X}")
                continue

            hits = set()
            pending = list(predecessors.get(event.site, ()))
            visited = set()
            if not pending:
                if not expected_entry:
                    raise ValueError(
                        "typed-member write reaches an undeclared graph root "
                        f"at 0x{event.site:X}:{event.bank}")
                hits.update(expected_entry)
            while pending:
                address = pending.pop()
                if address in visited:
                    continue
                visited.add(address)

                instruction_items = expected_instruction_sites.get(address)
                if instruction_items:
                    hits.update(instruction_items)
                    continue

                word = instruction_word(address)
                is_prior_bl = word & 0xFC000000 == 0x94000000
                is_prior_blr = word & 0xFFFFFC1F == 0xD63F0000
                if is_prior_bl or is_prior_blr:
                    call_items = expected_call_sites.get(address)
                    if call_items:
                        hits.update(call_items)
                        continue
                    if register is not None and register <= 18:
                        volatile_call_clobbers += 1
                        raise ValueError(
                            "typed-member write backwards slice crosses an "
                            f"undeclared volatile {event.bank} call boundary "
                            f"at 0x{owner:X}:0x{event.site:X}:0x{address:X}")

                if (owner, event.bank, address) in explicit_writer_sources:
                    raise ValueError(
                        "typed-member write path crosses an undeclared "
                        f"explicit {event.bank} writer at "
                        f"0x{owner:X}:0x{event.site:X}:0x{address:X}")

                incoming = predecessors.get(address, ())
                if incoming:
                    pending.extend(incoming)
                else:
                    if not expected_entry:
                        raise ValueError(
                            "typed-member write path reaches an undeclared "
                            f"normal root at 0x{owner:X}:0x{event.site:X}:"
                            f"{event.bank}")
                    hits.update(expected_entry)

            if hits != set(event.sources):
                missing = set(event.sources) - hits
                extra = hits - set(event.sources)
                raise ValueError(
                    "typed-member write reaching sources changed at "
                    f"0x{owner:X}:0x{event.site:X}:{event.bank}: "
                    f"missing={missing}, extra={extra}")

    store_site_counts: dict[str, int] = {}
    for store_kind in store_site_kinds.values():
        store_site_counts[store_kind] = (
            store_site_counts.get(store_kind, 0) + 1)
    expectations = (
        (
            "source cardinalities", cardinalities,
            EXPECTED_TYPED_MEMBER_WRITE_CARDINALITIES,
        ),
        (
            "store event kinds", store_counts,
            EXPECTED_TYPED_MEMBER_WRITE_STORE_COUNTS,
        ),
        (
            "store site kinds", store_site_counts,
            EXPECTED_TYPED_MEMBER_WRITE_STORE_SITE_COUNTS,
        ),
        ("modes", mode_counts, EXPECTED_TYPED_MEMBER_WRITE_MODE_COUNTS),
        (
            "selected operands", operand_counts,
            EXPECTED_TYPED_MEMBER_WRITE_OPERAND_COUNTS,
        ),
        ("banks", bank_counts, EXPECTED_TYPED_MEMBER_WRITE_BANK_COUNTS),
        (
            "type/size pairs", type_size_counts,
            EXPECTED_TYPED_MEMBER_WRITE_TYPE_SIZE_COUNTS,
        ),
        (
            "base types", base_type_counts,
            EXPECTED_TYPED_MEMBER_WRITE_BASE_TYPE_COUNTS,
        ),
        (
            "field types", field_type_counts,
            EXPECTED_TYPED_MEMBER_WRITE_FIELD_TYPE_COUNTS,
        ),
        (
            "source roles", source_role_counts,
            EXPECTED_TYPED_MEMBER_WRITE_SOURCE_ROLE_COUNTS,
        ),
        (
            "source kinds", source_kind_counts,
            EXPECTED_TYPED_MEMBER_WRITE_SOURCE_KIND_COUNTS,
        ),
    )
    for label, actual, expected in expectations:
        if actual != expected:
            raise ValueError(
                f"typed-member write {label} changed: expected "
                f"{expected}, got {actual}")
    if entry_sources != EXPECTED_TYPED_MEMBER_WRITE_ENTRY_SOURCES:
        raise ValueError(
            "typed-member write entry sources changed: expected "
            f"{EXPECTED_TYPED_MEMBER_WRITE_ENTRY_SOURCES}, got "
            f"{entry_sources}")

    relation_count = sum(
        source_count * event_count
        for source_count, event_count in cardinalities.items()
    )
    event_count = len(events)
    counts = {
        "owners": len(observed_owners),
        "sites": len(observed_sites),
        "events": event_count,
        "relations": relation_count,
        "single_source": cardinalities.get(1, 0),
        "multi_source": event_count - cardinalities.get(1, 0),
        "max_sources": max(cardinalities, default=0),
        "normal": normal_events,
        "landing": landing_events,
        "instruction": source_role_counts["instruction"],
        "entry": source_role_counts["entry-parameter"],
        "zero": source_role_counts["zero-register"],
        "call_return": source_role_counts["call-return"],
        "call_clobber": source_role_counts["call-clobber"],
        "entry_residue": source_role_counts["entry-residue"],
        "volatile_call_clobbers": volatile_call_clobbers,
        **source_class_counts,
    }
    if counts != EXPECTED_TYPED_MEMBER_WRITE_COUNTS:
        raise ValueError(
            "typed-member write counts changed: expected "
            f"{EXPECTED_TYPED_MEMBER_WRITE_COUNTS}, got {counts}")

    type_counts = {
        type_class: sum(
            count for (candidate, _), count in type_size_counts.items()
            if candidate == type_class
        )
        for type_class in TYPED_MEMBER_WRITE_TYPE_IDS.values()
    }
    return {
        **counts,
        **type_counts,
        "base_types": len(base_type_counts),
        "field_types": len(field_type_counts),
        "banks": len(bank_counts),
        "strb": store_counts["STRB"],
        "strh": store_counts["STRH"],
        "str": store_counts["STR"],
        "stp": store_counts["STP"],
        "stp_sites": store_site_counts["STP"],
        "write": mode_counts["W"],
        "read_write": mode_counts["RW"],
        "producer_classes": len(source_kind_counts),
    }


def verify_typed_member_read_surface(
    binary: Path,
    fdes: dict[int, FdeRecord],
    manifest: set[int],
) -> dict[str, int]:
    """Prove every typed-member read/address lane and its first consumer."""
    producers = read_typed_member_read_producer_manifest()
    anchors = read_typed_member_read_anchor_manifest()
    data = binary.read_bytes()

    switch_destinations: dict[int, tuple[int, ...]] = {}
    for owner, site, table, entry_count, _ in EXPECTED_SWITCH_TABLE_SURFACES:
        raw = read_elf_vma(
            data, table, entry_count * 4,
            f"typed-member read switch table 0x{table:X}",
        )
        destinations = tuple(sorted({
            table + displacement
            for displacement in struct.unpack(f"<{entry_count}i", raw)
        }))
        record = fdes.get(owner)
        if record is None or any(
            not owner <= destination < record.end
            for destination in destinations
        ):
            raise ValueError(
                f"typed-member read switch 0x{site:X} escapes owner "
                f"0x{owner:X}")
        switch_destinations[site] = destinations

    # A call is a first use only when the already-proved input manifest names
    # the same physical bank. Otherwise X0...X18 are volatile boundaries and
    # X19...X28 survive for continued tracing.
    call_argument_banks = set()
    for (owner, call), (_, _, _, arguments) in (
        read_normal_direct_argument_manifest().items()
    ):
        for _, bank_id, _, _, _ in arguments:
            bank_name = NORMAL_DIRECT_ARGUMENT_BANK_IDS[bank_id]
            if bank_name.startswith("X"):
                call_argument_banks.add(
                    (owner, call, int(bank_name[1:])))
    for (owner, call), (_, _, _, _, _, arguments) in (
        read_indirect_argument_manifest().items()
    ):
        for _, bank_id, _, _, _ in arguments:
            bank_name = INDIRECT_ARGUMENT_BANK_IDS[bank_id]
            call_argument_banks.add(
                (owner, call, int(bank_name[1:])))

    noreturn_targets = frozenset(
        target for target, _, _ in EXPECTED_NORMAL_NORETURN_TARGETS)
    owners = sorted({
        row.owner for row in producers
    } | {
        row.owner for row in anchors
    })
    function_raws = {}
    graphs = {}
    predecessors = {}
    for owner in owners:
        if owner not in manifest:
            raise ValueError(
                f"typed-member read owner 0x{owner:X} is outside MANIFEST")
        record = fdes.get(owner)
        if record is None:
            raise ValueError(
                f"typed-member read owner 0x{owner:X} has no FDE")
        function_raw = read_elf_vma(
            data, owner, record.end - owner,
            f"typed-member read owner 0x{owner:X}",
        )
        function_raws[owner] = function_raw

        def instruction_word(address: int) -> int:
            offset = address - owner
            if offset < 0 or offset + 4 > len(function_raw):
                raise ValueError(
                    f"typed-member read instruction 0x{address:X} is "
                    f"outside owner 0x{owner:X}")
            return struct.unpack_from("<I", function_raw, offset)[0]

        graph = walk_normal_cfg(
            owner,
            owner,
            record.end,
            instruction_word,
            switch_destinations,
            noreturn_targets,
        )
        graphs[owner] = graph
        incoming = {address: [] for address in graph}
        for source, (_, successors) in graph.items():
            for successor in successors:
                incoming.setdefault(successor, []).append(source)
        predecessors[owner] = incoming

    def instruction_word(owner: int, address: int) -> int:
        function_raw = function_raws[owner]
        offset = address - owner
        if offset < 0 or offset + 4 > len(function_raw):
            raise ValueError(
                f"typed-member read instruction 0x{address:X} is outside "
                f"owner 0x{owner:X}")
        return struct.unpack_from("<I", function_raw, offset)[0]

    # A path for one row may not silently cross a first event already proved
    # for another semantic row in the same physical register bank.
    explicit_forward_events = {}
    for row in producers:
        for event in row.events:
            key = (row.owner, row.bank, event[4])
            previous = explicit_forward_events.setdefault(key, event)
            if previous != event:
                raise ValueError(
                    "typed-member read event semantics conflict at "
                    f"0x{row.owner:X}:X{row.bank}:0x{event[4]:X}")

    producer_kind_counts = {}
    producer_width_counts = {}
    producer_mode_counts = {}
    producer_op_counts = {}
    producer_bank_counts = {}
    event_cardinalities = {}
    event_role_counts = {
        role: 0 for role in TYPED_MEMBER_READ_EVENT_ROLE_IDS.values()
    }
    producer_semantics = set()
    producer_sites = set()
    producer_owners = set()
    pre_event_loop_rows = 0
    volatile_call_clobbers = 0
    typed_member_sites = frozenset(EXPECTED_TYPED_MEMBER_INSTRUCTION_SITES)

    for row in producers:
        graph = graphs[row.owner]
        if row.site not in graph:
            raise ValueError(
                f"typed-member read producer 0x{row.site:X} is not "
                "normal-entry reachable")
        actual_word = instruction_word(row.owner, row.site)
        if actual_word != row.producer_word or graph[row.site][0] != actual_word:
            raise ValueError(
                f"typed-member read producer word changed at 0x{row.site:X}")
        if row.site not in typed_member_sites:
            raise ValueError(
                f"typed-member read producer 0x{row.site:X} is outside the "
                "instruction-backed member surface")

        semantic_key = (
            row.owner,
            row.site,
            row.mode,
            row.base_type,
            row.member_type,
            row.field_offset,
            row.op,
        )
        producer_semantics.add(semantic_key)
        producer_sites.add((row.owner, row.site))
        producer_owners.add(row.owner)
        producer_kind_counts[row.producer_kind] = (
            producer_kind_counts.get(row.producer_kind, 0) + 1)
        producer_width_counts[row.width] = (
            producer_width_counts.get(row.width, 0) + 1)
        producer_mode_counts[row.mode] = (
            producer_mode_counts.get(row.mode, 0) + 1)
        producer_op_counts[row.op] = (
            producer_op_counts.get(row.op, 0) + 1)
        bank_name = f"X{row.bank}"
        producer_bank_counts[bank_name] = (
            producer_bank_counts.get(bank_name, 0) + 1)
        event_cardinalities[len(row.events)] = (
            event_cardinalities.get(len(row.events), 0) + 1)

        expected_event_map = {}
        for event in row.events:
            (
                role_id,
                mnemonic_id,
                _,
                _,
                event_address,
                event_word,
            ) = event
            if event_address not in graph:
                raise ValueError(
                    f"typed-member read event 0x{event_address:X} is outside "
                    f"the normal graph of 0x{row.owner:X}")
            if instruction_word(row.owner, event_address) != event_word:
                raise ValueError(
                    f"typed-member read event word changed at "
                    f"0x{event_address:X}")
            role = TYPED_MEMBER_READ_EVENT_ROLE_IDS[role_id]
            mnemonic = TYPED_MEMBER_READ_EVENT_MNEMONIC_IDS[mnemonic_id]
            event_role_counts[role] += 1
            expected_event_map[event_address] = event
            is_bl = event_word & 0xFC000000 == 0x94000000
            is_blr = event_word & 0xFFFFFC1F == 0xD63F0000
            is_b = event_word & 0xFC000000 == 0x14000000
            is_ret = event_word & 0xFFFFFC1F == 0xD65F0000
            if role == "call-use":
                if (
                    (row.owner, event_address, row.bank)
                    not in call_argument_banks
                    or not (is_bl or is_blr or is_b)
                    or mnemonic != (
                        "BL" if is_bl else "BLR" if is_blr else "B"
                    )
                ):
                    raise ValueError(
                        f"typed-member read call-use ABI changed at "
                        f"0x{event_address:X}:X{row.bank}")
            elif role == "call-boundary":
                if not (is_bl or is_blr) or mnemonic != (
                    "BL" if is_bl else "BLR"
                ):
                    raise ValueError(
                        f"typed-member read call boundary changed at "
                        f"0x{event_address:X}")
            elif role == "terminal" and (
                not is_ret or mnemonic != "RET"
            ):
                raise ValueError(
                    f"typed-member read terminal changed at "
                    f"0x{event_address:X}")

        pending = list(graph[row.site][1])
        visited = set()
        hits = set()
        ordinary_edges = {}
        while pending:
            address = pending.pop()
            if address in visited:
                continue
            visited.add(address)
            event = expected_event_map.get(address)
            if event is not None:
                hits.add(event)
                continue
            if (row.owner, row.bank, address) in explicit_forward_events:
                raise ValueError(
                    "typed-member read path crosses an undeclared first "
                    f"event at 0x{row.owner:X}:0x{row.site:X}:"
                    f"X{row.bank}:0x{address:X}")

            word, successors = graph[address]
            is_bl = word & 0xFC000000 == 0x94000000
            is_blr = word & 0xFFFFFC1F == 0xD63F0000
            is_ret = word & 0xFFFFFC1F == 0xD65F0000
            if is_bl or is_blr:
                if (row.owner, address, row.bank) in call_argument_banks:
                    raise ValueError(
                        "typed-member read path crosses an undeclared call "
                        f"use at 0x{row.owner:X}:0x{row.site:X}:"
                        f"X{row.bank}:0x{address:X}")
                if row.bank <= 18:
                    volatile_call_clobbers += 1
                    raise ValueError(
                        "typed-member read path crosses an undeclared "
                        f"volatile X{row.bank} call boundary at "
                        f"0x{row.owner:X}:0x{row.site:X}:0x{address:X}")
            if is_ret:
                raise ValueError(
                    "typed-member read path reaches an undeclared RET at "
                    f"0x{row.owner:X}:0x{row.site:X}:0x{address:X}")
            if not successors:
                raise ValueError(
                    "typed-member read path reaches an unclassified terminal "
                    f"at 0x{row.owner:X}:0x{row.site:X}:0x{address:X}")
            ordinary_edges[address] = successors
            pending.extend(
                successor for successor in successors
                if successor not in visited
            )

        if hits != set(row.events):
            raise ValueError(
                "typed-member read first events changed at "
                f"0x{row.owner:X}:0x{row.site:X}:X{row.bank}: "
                f"missing={set(row.events) - hits}, "
                f"extra={hits - set(row.events)}")
        can_reach_event = {
            address
            for address, successors in ordinary_edges.items()
            if any(successor in expected_event_map for successor in successors)
        }
        changed = True
        while changed:
            changed = False
            for address, successors in ordinary_edges.items():
                if address in can_reach_event:
                    continue
                if any(successor in can_reach_event for successor in successors):
                    can_reach_event.add(address)
                    changed = True
        unreachable = set(ordinary_edges) - can_reach_event
        if unreachable:
            raise ValueError(
                "typed-member read path cannot reach a declared event at "
                f"0x{row.owner:X}:0x{row.site:X}: "
                + ",".join(f"0x{address:X}" for address in sorted(unreachable))
            )
        if normal_call_result_has_pre_event_loop(ordinary_edges):
            pre_event_loop_rows += 1

    explicit_anchor_sources = {}
    for row in anchors:
        for source in row.sources:
            role = TYPED_MEMBER_READ_SOURCE_ROLE_IDS[source[0]]
            if role == "instruction":
                key = (row.owner, row.bank, source[3])
                previous = explicit_anchor_sources.setdefault(key, source)
                if previous != source:
                    raise ValueError(
                        "typed-member read anchor source conflict at "
                        f"0x{row.owner:X}:X{row.bank}:0x{source[3]:X}")

    anchor_class_counts = {}
    anchor_mode_counts = {}
    anchor_op_counts = {}
    anchor_bank_counts = {}
    source_role_counts = {
        role: 0 for role in TYPED_MEMBER_READ_SOURCE_ROLE_IDS.values()
    }
    source_kind_counts = {}
    source_cardinalities = {}
    anchor_semantics = set()
    anchor_sites = set()
    anchor_owners = set()

    for row in anchors:
        graph = graphs[row.owner]
        if row.site not in graph or row.consumer not in graph:
            raise ValueError(
                f"typed-member read anchor 0x{row.site:X} is not "
                "normal-entry reachable")
        if (
            instruction_word(row.owner, row.site) != row.site_word
            or instruction_word(row.owner, row.consumer) != row.consumer_word
        ):
            raise ValueError(
                f"typed-member read anchor word changed at 0x{row.site:X}")
        if row.site not in typed_member_sites:
            raise ValueError(
                f"typed-member read anchor 0x{row.site:X} is outside the "
                "instruction-backed member surface")
        if row.anchor_class == "predicate-register":
            valid_anchor = (
                row.site == row.consumer
                and row.consumer_word & 0x7E000000 == 0x34000000
            )
        elif row.anchor_class == "predicate-nzcv":
            valid_anchor = (
                row.site != row.consumer
                and row.consumer_word & 31 == 31
                and row.consumer_word & 0x7F000000
                in {0x71000000, 0x6B000000}
            )
        elif row.anchor_class in {
            "store-anchored",
            "transfer-anchored",
        }:
            valid_anchor = row.site == row.consumer
        else:
            valid_anchor = (
                row.site == row.consumer
                and row.bank == 31
                and row.width == "X"
            )
        if not valid_anchor:
            raise ValueError(
                f"typed-member read anchor class changed at 0x{row.site:X}")

        semantic_key = (
            row.owner,
            row.site,
            row.mode,
            row.base_type,
            row.member_type,
            row.field_offset,
            row.op,
        )
        anchor_semantics.add(semantic_key)
        anchor_sites.add((row.owner, row.site))
        anchor_owners.add(row.owner)
        anchor_class_counts[row.anchor_class] = (
            anchor_class_counts.get(row.anchor_class, 0) + 1)
        anchor_mode_counts[row.mode] = (
            anchor_mode_counts.get(row.mode, 0) + 1)
        anchor_op_counts[row.op] = (
            anchor_op_counts.get(row.op, 0) + 1)
        bank_name = "ZR" if row.bank == 31 else f"X{row.bank}"
        anchor_bank_counts[bank_name] = (
            anchor_bank_counts.get(bank_name, 0) + 1)
        source_cardinalities[len(row.sources)] = (
            source_cardinalities.get(len(row.sources), 0) + 1)

        expected_sources = {}
        zero_sources = set()
        for source in row.sources:
            role = TYPED_MEMBER_READ_SOURCE_ROLE_IDS[source[0]]
            source_kind = TYPED_MEMBER_READ_SOURCE_KIND_IDS[source[1]]
            source_role_counts[role] += 1
            source_kind_counts[source_kind] = (
                source_kind_counts.get(source_kind, 0) + 1)
            if role == "zero-register":
                zero_sources.add(source)
                continue
            if role != "instruction":
                raise ValueError(
                    f"typed-member read unsupported anchor source role "
                    f"{role} at 0x{row.site:X}")
            if source[3] not in graph:
                raise ValueError(
                    f"typed-member read anchor source 0x{source[3]:X} is "
                    "outside the normal graph")
            if instruction_word(row.owner, source[3]) != source[4]:
                raise ValueError(
                    f"typed-member read anchor source word changed at "
                    f"0x{source[3]:X}")
            expected_sources[source[3]] = source

        if zero_sources:
            if zero_sources != set(row.sources):
                raise ValueError(
                    f"typed-member read zero source is mixed at "
                    f"0x{row.site:X}")
            continue

        pending = list(predecessors[row.owner].get(row.consumer, ()))
        visited = set()
        hits = set()
        while pending:
            address = pending.pop()
            if address in visited:
                continue
            visited.add(address)
            source = expected_sources.get(address)
            if source is not None:
                hits.add(source)
                continue
            if (row.owner, row.bank, address) in explicit_anchor_sources:
                raise ValueError(
                    "typed-member read reverse path crosses an undeclared "
                    f"source at 0x{row.owner:X}:0x{row.site:X}:"
                    f"X{row.bank}:0x{address:X}")

            word = instruction_word(row.owner, address)
            is_bl = word & 0xFC000000 == 0x94000000
            is_blr = word & 0xFFFFFC1F == 0xD63F0000
            if (is_bl or is_blr) and row.bank <= 18:
                volatile_call_clobbers += 1
                raise ValueError(
                    "typed-member read reverse path crosses an undeclared "
                    f"volatile X{row.bank} call boundary at "
                    f"0x{row.owner:X}:0x{row.site:X}:0x{address:X}")
            incoming = predecessors[row.owner].get(address, ())
            if not incoming:
                raise ValueError(
                    "typed-member read reverse path reaches an undeclared "
                    f"normal root at 0x{row.owner:X}:0x{row.site:X}:"
                    f"X{row.bank}")
            pending.extend(incoming)
        if hits != set(row.sources):
            raise ValueError(
                "typed-member read anchor sources changed at "
                f"0x{row.owner:X}:0x{row.site:X}:X{row.bank}: "
                f"missing={set(row.sources) - hits}, "
                f"extra={hits - set(row.sources)}")

    expectations = (
        (
            "producer kinds",
            producer_kind_counts,
            EXPECTED_TYPED_MEMBER_READ_PRODUCER_KIND_COUNTS,
        ),
        (
            "producer widths",
            producer_width_counts,
            EXPECTED_TYPED_MEMBER_READ_PRODUCER_WIDTH_COUNTS,
        ),
        (
            "producer modes",
            producer_mode_counts,
            EXPECTED_TYPED_MEMBER_READ_PRODUCER_MODE_COUNTS,
        ),
        (
            "producer operations",
            producer_op_counts,
            EXPECTED_TYPED_MEMBER_READ_PRODUCER_OP_COUNTS,
        ),
        (
            "producer banks",
            producer_bank_counts,
            EXPECTED_TYPED_MEMBER_READ_PRODUCER_BANK_COUNTS,
        ),
        (
            "consumer cardinalities",
            event_cardinalities,
            EXPECTED_TYPED_MEMBER_READ_PRODUCER_CARDINALITIES,
        ),
        (
            "event roles",
            event_role_counts,
            EXPECTED_TYPED_MEMBER_READ_EVENT_ROLE_COUNTS,
        ),
        (
            "anchor classes",
            anchor_class_counts,
            EXPECTED_TYPED_MEMBER_READ_ANCHOR_CLASS_COUNTS,
        ),
        (
            "anchor modes",
            anchor_mode_counts,
            EXPECTED_TYPED_MEMBER_READ_ANCHOR_MODE_COUNTS,
        ),
        (
            "anchor operations",
            anchor_op_counts,
            EXPECTED_TYPED_MEMBER_READ_ANCHOR_OP_COUNTS,
        ),
        (
            "anchor banks",
            anchor_bank_counts,
            EXPECTED_TYPED_MEMBER_READ_ANCHOR_BANK_COUNTS,
        ),
        (
            "source roles",
            source_role_counts,
            EXPECTED_TYPED_MEMBER_READ_SOURCE_ROLE_COUNTS,
        ),
        (
            "source kinds",
            source_kind_counts,
            EXPECTED_TYPED_MEMBER_READ_SOURCE_KIND_COUNTS,
        ),
    )
    for label, actual, expected in expectations:
        if actual != expected:
            raise ValueError(
                f"typed-member read {label} changed: expected "
                f"{expected}, got {actual}")

    if producer_semantics & anchor_semantics:
        raise ValueError(
            "typed-member read producer and anchor semantic rows overlap")
    semantic_events = producer_semantics | anchor_semantics
    all_sites = producer_sites | anchor_sites
    counts = {
        "owners": len(producer_owners | anchor_owners),
        "sites": len(all_sites),
        "semantic_events": len(semantic_events),
        "normal": len(semantic_events),
        "landing": 0,
        "producer_owners": len(producer_owners),
        "producer_sites": len(producer_sites),
        "producer_semantic_rows": len(producer_semantics),
        "producer_lanes": len(producers),
        "consumer_relations": sum(len(row.events) for row in producers),
        "single_consumer": event_cardinalities.get(1, 0),
        "multi_consumer": (
            len(producers) - event_cardinalities.get(1, 0)
        ),
        "max_consumers": max(event_cardinalities, default=0),
        "anchor_owners": len(anchor_owners),
        "anchor_sites": len(anchor_sites),
        "anchor_semantic_rows": len(anchor_semantics),
        "anchor_lanes": len(anchors),
        "anchor_sources": sum(len(row.sources) for row in anchors),
        "single_source": source_cardinalities.get(1, 0),
        "multi_source": len(anchors) - source_cardinalities.get(1, 0),
        "max_sources": max(source_cardinalities, default=0),
        "pre_event_loop_rows": pre_event_loop_rows,
        "volatile_call_clobbers": volatile_call_clobbers,
    }
    if counts != EXPECTED_TYPED_MEMBER_READ_COUNTS:
        raise ValueError(
            "typed-member read counts changed: expected "
            f"{EXPECTED_TYPED_MEMBER_READ_COUNTS}, got {counts}")
    return {
        **counts,
        "read": sum(
            1 for semantic in semantic_events if semantic[2] == "R"),
        "read_write": sum(
            1 for semantic in semantic_events if semantic[2] == "RW"),
        "address": sum(
            1 for semantic in semantic_events if semantic[2] == "address"),
        "use": event_role_counts["use"],
        "transform": event_role_counts["transform"],
        "call_use": event_role_counts["call-use"],
        "call_boundary": event_role_counts["call-boundary"],
        "terminal": event_role_counts["terminal"],
        "instruction_sources": source_role_counts["instruction"],
        "zero_sources": source_role_counts["zero-register"],
        "producer_classes": len(producer_kind_counts),
        "anchor_classes": len(anchor_class_counts),
        "base_types": len(TYPED_MEMBER_READ_BASE_TYPES),
        "member_types": len(TYPED_MEMBER_READ_MEMBER_TYPES),
    }


def verify_typed_member_synthetic_surface(
    binary: Path,
    fdes: dict[int, FdeRecord],
    manifest: set[int],
    write_counts: dict[str, int],
    read_counts: dict[str, int],
) -> dict[str, int]:
    """Tie every BADADDR ctree member row to its emitted machine anchors."""
    rows = read_typed_member_synthetic_manifest()
    data = binary.read_bytes()

    switch_destinations: dict[int, tuple[int, ...]] = {}
    for owner, site, table, entry_count, _ in EXPECTED_SWITCH_TABLE_SURFACES:
        raw = read_elf_vma(
            data,
            table,
            entry_count * 4,
            f"typed-member synthetic switch table 0x{table:X}",
        )
        destinations = tuple(sorted({
            table + displacement
            for displacement in struct.unpack(f"<{entry_count}i", raw)
        }))
        record = fdes.get(owner)
        if record is None or any(
            not owner <= destination < record.end
            for destination in destinations
        ):
            raise ValueError(
                f"typed-member synthetic switch 0x{site:X} escapes owner "
                f"0x{owner:X}")
        switch_destinations[site] = destinations

    owners = sorted({row.owner for row in rows})
    noreturn_targets = frozenset(
        target for target, _, _ in EXPECTED_NORMAL_NORETURN_TARGETS)
    function_raws = {}
    graphs = {}
    for owner in owners:
        if owner not in manifest:
            raise ValueError(
                f"typed-member synthetic owner 0x{owner:X} is outside "
                "MANIFEST")
        record = fdes.get(owner)
        if record is None:
            raise ValueError(
                f"typed-member synthetic owner 0x{owner:X} has no FDE")
        function_raw = read_elf_vma(
            data,
            owner,
            record.end - owner,
            f"typed-member synthetic owner 0x{owner:X}",
        )
        function_raws[owner] = function_raw

        def owner_instruction_word(address: int) -> int:
            relative = address - owner
            if relative < 0 or relative + 4 > len(function_raw):
                raise ValueError(
                    f"typed-member synthetic instruction 0x{address:X} "
                    f"is outside owner 0x{owner:X}")
            return struct.unpack_from("<I", function_raw, relative)[0]

        graphs[owner] = walk_normal_cfg(
            owner,
            owner,
            record.end,
            owner_instruction_word,
            switch_destinations,
            noreturn_targets,
        )

    def instruction_word(owner: int, address: int) -> int:
        function_raw = function_raws[owner]
        relative = address - owner
        if relative < 0 or relative + 4 > len(function_raw):
            raise ValueError(
                f"typed-member synthetic instruction 0x{address:X} is "
                f"outside owner 0x{owner:X}")
        return struct.unpack_from("<I", function_raw, relative)[0]

    function_manager_sites = frozenset(
        (owner, site)
        for owner, site, _, _, role in EXPECTED_INDIRECT_ABI_SITES
        if role == "function-manager"
    )
    switch_sites = frozenset(
        (owner, site)
        for owner, site, _, _, _ in EXPECTED_SWITCH_TABLE_SURFACES
    )
    instruction_member_sites = frozenset(
        EXPECTED_TYPED_MEMBER_INSTRUCTION_SITES)

    mode_counts = {}
    occurrence_mode_counts = {}
    op_counts = {}
    parent_op_counts = {}
    realization_class_counts = {}
    mnemonic_counts = {}
    cardinalities = {}
    offset_counts = {}
    base_type_counts = {}
    member_type_counts = {}
    expressions = set()
    semantic_keys = set()
    occurrence_sites = set()
    instruction_site_intersection = 0

    for row in rows:
        mode_counts[row.mode] = mode_counts.get(row.mode, 0) + 1
        op_counts[row.op] = op_counts.get(row.op, 0) + 1
        offset_counts[row.field_offset] = (
            offset_counts.get(row.field_offset, 0) + 1)
        base_type_counts[row.base_type] = (
            base_type_counts.get(row.base_type, 0) + 1)
        member_type_counts[row.member_type] = (
            member_type_counts.get(row.member_type, 0) + 1)
        expressions.add(row.expression)
        semantic_key = (
            row.owner,
            row.mode,
            row.expression,
            row.base_type,
            row.member_type,
            row.field_offset,
            row.op,
        )
        if semantic_key in semantic_keys:
            raise ValueError(
                "typed-member synthetic semantic row is duplicated at "
                f"0x{row.owner:X}:{row.expression}")
        semantic_keys.add(semantic_key)
        cardinalities[len(row.occurrences)] = (
            cardinalities.get(len(row.occurrences), 0) + 1)

        for (
            parent_op,
            realization_class,
            mnemonic,
            address,
            expected_word,
        ) in row.occurrences:
            graph = graphs[row.owner]
            if address not in graph:
                raise ValueError(
                    f"typed-member synthetic anchor 0x{address:X} is not "
                    "normal-entry reachable")
            actual_word = instruction_word(row.owner, address)
            if actual_word != expected_word or graph[address][0] != actual_word:
                raise ValueError(
                    f"typed-member synthetic anchor word changed at "
                    f"0x{address:X}")
            if not typed_member_synthetic_word_matches_mnemonic(
                mnemonic, actual_word
            ):
                raise ValueError(
                    f"typed-member synthetic mnemonic changed at "
                    f"0x{address:X}")

            if realization_class == "assignment-store":
                valid_realization = (
                    row.mode == "W"
                    and parent_op == "asg"
                    and mnemonic in {"STR", "STP", "STRB"}
                )
            elif realization_class == "read-modify-write-store":
                valid_realization = (
                    row.mode == "RW"
                    and parent_op == "preinc"
                    and mnemonic == "STR"
                )
            elif realization_class == "address-coalesced-store":
                valid_realization = (
                    row.mode == "address"
                    and parent_op == "ref"
                    and mnemonic == "STR"
                )
            elif realization_class == "direct-load":
                valid_realization = (
                    row.mode == "R"
                    and parent_op == "cast"
                    and mnemonic == "LDR"
                )
            elif realization_class == "indirect-call-target":
                valid_realization = (
                    row.mode == "R"
                    and parent_op == "cast"
                    and mnemonic == "BLR"
                    and (row.owner, address) in function_manager_sites
                )
            elif realization_class == "switch-dispatch":
                valid_realization = (
                    row.mode == "R"
                    and parent_op == "ptr"
                    and mnemonic == "BR"
                    and (row.owner, address) in switch_sites
                )
            else:
                valid_realization = (
                    row.mode == "R"
                    and parent_op == "cast"
                    and mnemonic in {"STR", "STP"}
                )
            if not valid_realization:
                raise ValueError(
                    "typed-member synthetic realization changed at "
                    f"0x{row.owner:X}:{row.expression}:0x{address:X}")

            occurrence_key = (row.owner, address)
            if occurrence_key in occurrence_sites:
                raise ValueError(
                    f"typed-member synthetic anchor 0x{address:X} is shared")
            occurrence_sites.add(occurrence_key)
            if address in instruction_member_sites:
                instruction_site_intersection += 1
            occurrence_mode_counts[row.mode] = (
                occurrence_mode_counts.get(row.mode, 0) + 1)
            parent_op_counts[parent_op] = (
                parent_op_counts.get(parent_op, 0) + 1)
            realization_class_counts[realization_class] = (
                realization_class_counts.get(realization_class, 0) + 1)
            mnemonic_counts[mnemonic] = (
                mnemonic_counts.get(mnemonic, 0) + 1)

    expectations = (
        (
            "semantic modes",
            mode_counts,
            EXPECTED_TYPED_MEMBER_SYNTHETIC_MODE_COUNTS,
        ),
        (
            "occurrence modes",
            occurrence_mode_counts,
            EXPECTED_TYPED_MEMBER_SYNTHETIC_OCCURRENCE_MODE_COUNTS,
        ),
        (
            "operations",
            op_counts,
            EXPECTED_TYPED_MEMBER_SYNTHETIC_OP_COUNTS,
        ),
        (
            "parent operations",
            parent_op_counts,
            EXPECTED_TYPED_MEMBER_SYNTHETIC_PARENT_OP_COUNTS,
        ),
        (
            "realization classes",
            realization_class_counts,
            EXPECTED_TYPED_MEMBER_SYNTHETIC_REALIZATION_CLASS_COUNTS,
        ),
        (
            "mnemonics",
            mnemonic_counts,
            EXPECTED_TYPED_MEMBER_SYNTHETIC_MNEMONIC_COUNTS,
        ),
        (
            "cardinalities",
            cardinalities,
            EXPECTED_TYPED_MEMBER_SYNTHETIC_CARDINALITIES,
        ),
        (
            "offsets",
            offset_counts,
            EXPECTED_TYPED_MEMBER_SYNTHETIC_OFFSET_COUNTS,
        ),
        (
            "base types",
            base_type_counts,
            EXPECTED_TYPED_MEMBER_SYNTHETIC_BASE_TYPE_COUNTS,
        ),
        (
            "member types",
            member_type_counts,
            EXPECTED_TYPED_MEMBER_SYNTHETIC_MEMBER_TYPE_COUNTS,
        ),
    )
    for label, actual, expected in expectations:
        if actual != expected:
            raise ValueError(
                f"typed-member synthetic {label} changed: expected "
                f"{expected}, got {actual}")

    if read_counts["read_write"] != write_counts["read_write"]:
        raise ValueError(
            "typed-member synthetic EA-backed RW overlap changed")
    ea_backed_semantic_rows = (
        read_counts["semantic_events"]
        + write_counts["events"]
        - read_counts["read_write"]
    )
    counts = {
        "owners": len(owners),
        "semantic_rows": len(rows),
        "occurrences": sum(len(row.occurrences) for row in rows),
        "sites": len(occurrence_sites),
        "normal": len(occurrence_sites),
        "landing": 0,
        "single_occurrence": cardinalities.get(1, 0),
        "multi_occurrence": len(rows) - cardinalities.get(1, 0),
        "max_occurrences": max(cardinalities, default=0),
        "expression_forms": len(expressions),
        "ea_backed_semantic_rows": ea_backed_semantic_rows,
        "total_semantic_rows": ea_backed_semantic_rows + len(rows),
        "instruction_site_intersection": instruction_site_intersection,
    }
    if counts != EXPECTED_TYPED_MEMBER_SYNTHETIC_COUNTS:
        raise ValueError(
            "typed-member synthetic counts changed: expected "
            f"{EXPECTED_TYPED_MEMBER_SYNTHETIC_COUNTS}, got {counts}")
    return {
        **counts,
        "write": mode_counts["W"],
        "read": mode_counts["R"],
        "read_write": mode_counts["RW"],
        "address": mode_counts["address"],
        "assignment_store": realization_class_counts["assignment-store"],
        "read_modify_write_store": realization_class_counts[
            "read-modify-write-store"
        ],
        "address_coalesced_store": realization_class_counts[
            "address-coalesced-store"
        ],
        "direct_load": realization_class_counts["direct-load"],
        "indirect_call_target": realization_class_counts[
            "indirect-call-target"
        ],
        "switch_dispatch": realization_class_counts["switch-dispatch"],
        "cast_coalesced_store": realization_class_counts[
            "cast-coalesced-store"
        ],
        "machine_stores": (
            mnemonic_counts["STR"]
            + mnemonic_counts["STP"]
            + mnemonic_counts["STRB"]
        ),
        "str": mnemonic_counts["STR"],
        "stp": mnemonic_counts["STP"],
        "strb": mnemonic_counts["STRB"],
        "ldr": mnemonic_counts["LDR"],
        "blr": mnemonic_counts["BLR"],
        "br": mnemonic_counts["BR"],
        "base_types": len(base_type_counts),
        "member_types": len(member_type_counts),
    }


def read_raw_memory_manifest() -> tuple[RawMemoryRow, ...]:
    """Decode the compact IDB-derived raw cot_ptr/cot_idx manifest."""
    try:
        compressed = base64.b64decode(
            EXPECTED_RAW_MEMORY_ZLIB_BASE64, validate=True)
        raw = zlib.decompress(compressed)
    except (binascii.Error, zlib.error) as exc:
        raise ValueError(
            f"raw-memory canonical payload is invalid: {exc}") from exc

    if len(raw) != EXPECTED_RAW_MEMORY_RAW_BYTES:
        raise ValueError(
            "raw-memory canonical byte count changed: expected "
            f"{EXPECTED_RAW_MEMORY_RAW_BYTES}, got {len(raw)}")
    digest = hashlib.sha256(raw).hexdigest()
    if digest != EXPECTED_RAW_MEMORY_RAW_SHA256:
        raise ValueError(
            "raw-memory canonical digest changed: expected "
            f"{EXPECTED_RAW_MEMORY_RAW_SHA256}, got {digest}")
    if raw[:4] != b"RMC2":
        raise ValueError("raw-memory canonical magic changed")

    row_count = struct.unpack_from("<H", raw, 4)[0]
    row_size = struct.calcsize("<QHBBBBBQQI")
    expected_size = 6 + row_count * row_size + 32
    if expected_size != len(raw):
        raise ValueError(
            "raw-memory canonical structure changed: expected "
            f"{expected_size} bytes from count, got {len(raw)}")

    cursor = 6
    rows: list[RawMemoryRow] = []
    for _ in range(row_count):
        (
            owner,
            ordinal,
            kind_id,
            mode_id,
            parent_id,
            mode_parent_id,
            mnemonic_id,
            ea,
            anchor,
            word,
        ) = struct.unpack_from("<QHBBBBBQQI", raw, cursor)
        cursor += row_size
        if kind_id not in RAW_MEMORY_KIND_IDS:
            raise ValueError(f"raw-memory kind id {kind_id} is unknown")
        if mode_id not in RAW_MEMORY_MODE_IDS:
            raise ValueError(f"raw-memory mode id {mode_id} is unknown")
        if parent_id not in RAW_MEMORY_PARENT_IDS:
            raise ValueError(
                f"raw-memory parent id {parent_id} is unknown")
        if mode_parent_id not in RAW_MEMORY_MODE_PARENT_IDS:
            raise ValueError(
                f"raw-memory mode-parent id {mode_parent_id} is unknown")
        if mnemonic_id not in RAW_MEMORY_MNEMONIC_IDS:
            raise ValueError(
                f"raw-memory mnemonic id {mnemonic_id} is unknown")
        rows.append(RawMemoryRow(
            owner=owner,
            ordinal=ordinal,
            kind=RAW_MEMORY_KIND_IDS[kind_id],
            mode=RAW_MEMORY_MODE_IDS[mode_id],
            parent=RAW_MEMORY_PARENT_IDS[parent_id],
            mode_parent=RAW_MEMORY_MODE_PARENT_IDS[mode_parent_id],
            mnemonic=RAW_MEMORY_MNEMONIC_IDS[mnemonic_id],
            ea=None if ea == 0 else ea,
            anchor=anchor,
            word=word,
        ))

    semantic_digest = raw[cursor:cursor + 32].hex()
    if semantic_digest != EXPECTED_RAW_MEMORY_SEMANTIC_SHA256:
        raise ValueError(
            "raw-memory ctree semantic digest changed: expected "
            f"{EXPECTED_RAW_MEMORY_SEMANTIC_SHA256}, got "
            f"{semantic_digest}")
    if len(rows) != EXPECTED_RAW_MEMORY_COUNTS["rows"]:
        raise ValueError(
            "raw-memory canonical row count changed: expected "
            f"{EXPECTED_RAW_MEMORY_COUNTS['rows']}, got {len(rows)}")
    return tuple(rows)


def read_numeric_ctree_manifest() -> tuple[NumericCtreeRow, ...]:
    """Decode the compact IDB-derived complete cot_num manifest."""
    try:
        compressed = base64.b64decode(
            EXPECTED_NUMERIC_CTREE_ZLIB_BASE64, validate=True)
        raw = zlib.decompress(compressed)
    except (binascii.Error, zlib.error) as exc:
        raise ValueError(
            f"numeric-ctree canonical payload is invalid: {exc}") from exc

    if len(raw) != EXPECTED_NUMERIC_CTREE_RAW_BYTES:
        raise ValueError(
            "numeric-ctree canonical byte count changed: expected "
            f"{EXPECTED_NUMERIC_CTREE_RAW_BYTES}, got {len(raw)}")
    digest = hashlib.sha256(raw).hexdigest()
    if digest != EXPECTED_NUMERIC_CTREE_RAW_SHA256:
        raise ValueError(
            "numeric-ctree canonical digest changed: expected "
            f"{EXPECTED_NUMERIC_CTREE_RAW_SHA256}, got {digest}")
    if raw[:4] != b"NMC1":
        raise ValueError("numeric-ctree canonical magic changed")

    row_count = struct.unpack_from("<H", raw, 4)[0]
    row_size = struct.calcsize("<QHBBBBQQIQ")
    expected_size = 6 + row_count * row_size + 32
    if expected_size != len(raw):
        raise ValueError(
            "numeric-ctree canonical structure changed: expected "
            f"{expected_size} bytes from count, got {len(raw)}")

    cursor = 6
    rows: list[NumericCtreeRow] = []
    for _ in range(row_count):
        (
            owner,
            ordinal,
            parent_id,
            type_id,
            mnemonic_id,
            flags,
            ea,
            anchor,
            word,
            value,
        ) = struct.unpack_from("<QHBBBBQQIQ", raw, cursor)
        cursor += row_size
        if parent_id not in NUMERIC_CTREE_PARENT_IDS:
            raise ValueError(
                f"numeric-ctree parent id {parent_id} is unknown")
        if type_id not in NUMERIC_CTREE_TYPE_IDS:
            raise ValueError(
                f"numeric-ctree type id {type_id} is unknown")
        if mnemonic_id not in NUMERIC_CTREE_MNEMONIC_IDS:
            raise ValueError(
                f"numeric-ctree mnemonic id {mnemonic_id} is unknown")
        if flags not in {0, 1}:
            raise ValueError(
                f"numeric-ctree flags 0x{flags:X} are invalid")
        synthetic = bool(flags & 1)
        if synthetic != (ea == 0):
            raise ValueError(
                f"numeric-ctree synthetic/EA mismatch in 0x{owner:X}:"
                f"{ordinal}")
        rows.append(NumericCtreeRow(
            owner=owner,
            ordinal=ordinal,
            parent=NUMERIC_CTREE_PARENT_IDS[parent_id],
            type_name=NUMERIC_CTREE_TYPE_IDS[type_id],
            mnemonic=NUMERIC_CTREE_MNEMONIC_IDS[mnemonic_id],
            synthetic=synthetic,
            ea=None if ea == 0 else ea,
            anchor=anchor,
            word=word,
            value=value,
        ))

    semantic_digest = raw[cursor:cursor + 32].hex()
    if semantic_digest != EXPECTED_NUMERIC_CTREE_SEMANTIC_SHA256:
        raise ValueError(
            "numeric-ctree semantic digest changed: expected "
            f"{EXPECTED_NUMERIC_CTREE_SEMANTIC_SHA256}, got "
            f"{semantic_digest}")
    if len(rows) != EXPECTED_NUMERIC_CTREE_COUNTS["rows"]:
        raise ValueError(
            "numeric-ctree canonical row count changed: expected "
            f"{EXPECTED_NUMERIC_CTREE_COUNTS['rows']}, got {len(rows)}")
    return tuple(rows)


def read_lvar_ctree_manifest() -> tuple[
    tuple[LvarDeclarationRow, ...],
    tuple[LvarUseRow, ...],
]:
    """Decode the compact IDB-derived lvar declaration/use manifest."""
    try:
        compressed = base64.b64decode(
            EXPECTED_LVAR_CTREE_ZLIB_BASE64, validate=True)
        raw = zlib.decompress(compressed)
    except (binascii.Error, zlib.error) as exc:
        raise ValueError(
            f"lvar-ctree canonical payload is invalid: {exc}") from exc

    if len(raw) != EXPECTED_LVAR_CTREE_RAW_BYTES:
        raise ValueError(
            "lvar-ctree canonical byte count changed: expected "
            f"{EXPECTED_LVAR_CTREE_RAW_BYTES}, got {len(raw)}")
    digest = hashlib.sha256(raw).hexdigest()
    if digest != EXPECTED_LVAR_CTREE_RAW_SHA256:
        raise ValueError(
            "lvar-ctree canonical digest changed: expected "
            f"{EXPECTED_LVAR_CTREE_RAW_SHA256}, got {digest}")

    header = struct.Struct("<4sHHHHII")
    if len(raw) < header.size + 32:
        raise ValueError("lvar-ctree canonical payload is truncated")
    (
        magic,
        type_count,
        parent_count,
        relation_count,
        mnemonic_count,
        declaration_count,
        use_count,
    ) = header.unpack_from(raw)
    if magic != b"LVS1":
        raise ValueError("lvar-ctree canonical magic changed")

    cursor = header.size

    def read_catalog(count: int, label: str) -> tuple[str, ...]:
        nonlocal cursor
        items: list[str] = []
        for _ in range(count):
            if cursor + 2 > len(raw) - 32:
                raise ValueError(
                    f"lvar-ctree {label} catalog is truncated")
            size = struct.unpack_from("<H", raw, cursor)[0]
            cursor += 2
            if cursor + size > len(raw) - 32:
                raise ValueError(
                    f"lvar-ctree {label} string is truncated")
            try:
                item = raw[cursor:cursor + size].decode("utf-8")
            except UnicodeDecodeError as exc:
                raise ValueError(
                    f"lvar-ctree {label} is not UTF-8") from exc
            cursor += size
            items.append(item)
        if items != sorted(set(items)):
            raise ValueError(
                f"lvar-ctree {label} catalog is not canonical")
        return tuple(items)

    types = read_catalog(type_count, "type")
    parents = read_catalog(parent_count, "parent")
    relations = read_catalog(relation_count, "relation")
    mnemonics = read_catalog(mnemonic_count, "mnemonic")
    if (
        len(types) != EXPECTED_LVAR_CTREE_COUNTS["types"]
        or len(parents) != EXPECTED_LVAR_CTREE_COUNTS["parents"]
        or len(relations) != EXPECTED_LVAR_CTREE_COUNTS["relations"]
        or len(mnemonics) != EXPECTED_LVAR_CTREE_COUNTS["mnemonics"]
    ):
        raise ValueError("lvar-ctree catalog cardinality changed")

    declaration_struct = struct.Struct("<QHBBHIQQI")
    use_struct = struct.Struct("<QHHBBBBQQI")
    expected_size = (
        cursor
        + declaration_count * declaration_struct.size
        + use_count * use_struct.size
        + 32
    )
    if expected_size != len(raw):
        raise ValueError(
            "lvar-ctree canonical structure changed: expected "
            f"{expected_size} bytes from header, got {len(raw)}")

    declarations: list[LvarDeclarationRow] = []
    semantic = bytearray()
    for _ in range(declaration_count):
        (
            owner,
            ordinal,
            type_id,
            width,
            flags,
            location,
            defea,
            anchor,
            word,
        ) = declaration_struct.unpack_from(raw, cursor)
        cursor += declaration_struct.size
        if type_id >= len(types):
            raise ValueError(
                f"lvar-ctree type id {type_id} is out of range")
        if flags & ~0x1FF or ((flags >> 7) & 3) == 3:
            raise ValueError(
                f"lvar-ctree declaration flags 0x{flags:X} are invalid")
        stack = bool(flags & (1 << 1))
        register = bool(flags & (1 << 2))
        if stack == register:
            raise ValueError(
                f"lvar-ctree declaration 0x{owner:X}:{ordinal} has an "
                "invalid location class")
        if anchor == 0:
            if word != 0 or defea < 0xFFFFFFFF00000000:
                raise ValueError(
                    f"lvar-ctree special definition 0x{owner:X}:"
                    f"{ordinal} is malformed")
        elif anchor & 3 or not anchor <= defea < anchor + 4:
            raise ValueError(
                f"lvar-ctree definition anchor mismatch in 0x{owner:X}:"
                f"{ordinal}")
        row = LvarDeclarationRow(
            owner=owner,
            ordinal=ordinal,
            type_name=types[type_id],
            width=width,
            flags=flags,
            location=location,
            defea=defea,
            anchor=None if anchor == 0 else anchor,
            word=word,
        )
        declarations.append(row)
        semantic_line = (
            f"D\t{owner:016X}\t{ordinal}\t{row.type_name}\t{width}\t"
            f"{flags}\t{location:08X}\t{defea:016X}\t{anchor:016X}\t"
            f"{word:08X}\n"
        )
        semantic.extend(semantic_line.encode("utf-8"))

    mode_names = ("read", "write", "read-write", "address")
    uses: list[LvarUseRow] = []
    for _ in range(use_count):
        (
            owner,
            ordinal,
            lvar_index,
            parent_id,
            relation_id,
            mnemonic_id,
            flags,
            ea,
            anchor,
            word,
        ) = use_struct.unpack_from(raw, cursor)
        cursor += use_struct.size
        if (
            parent_id >= len(parents)
            or relation_id >= len(relations)
            or mnemonic_id >= len(mnemonics)
            or flags & ~7
        ):
            raise ValueError(
                f"lvar-ctree use metadata is invalid in 0x{owner:X}:"
                f"{ordinal}")
        synthetic = bool(flags & 1)
        if synthetic != (ea == 0) or anchor & 3:
            raise ValueError(
                f"lvar-ctree use anchor mismatch in 0x{owner:X}:"
                f"{ordinal}")
        if not synthetic and ea != anchor:
            raise ValueError(
                f"lvar-ctree concrete use 0x{owner:X}:{ordinal} does not "
                "anchor at its own EA")
        row = LvarUseRow(
            owner=owner,
            ordinal=ordinal,
            lvar_index=lvar_index,
            parent=parents[parent_id],
            relation=relations[relation_id],
            mnemonic=mnemonics[mnemonic_id],
            mode=mode_names[(flags >> 1) & 3],
            synthetic=synthetic,
            ea=None if ea == 0 else ea,
            anchor=anchor,
            word=word,
        )
        uses.append(row)
        semantic_line = (
            f"U\t{owner:016X}\t{ordinal}\t{lvar_index}\t{row.parent}\t"
            f"{row.relation}\t{row.mnemonic}\t{row.mode}\t"
            f"{1 if synthetic else 0}\t{ea:016X}\t{anchor:016X}\t"
            f"{word:08X}\n"
        )
        semantic.extend(semantic_line.encode("utf-8"))

    stored_semantic_digest = raw[cursor:cursor + 32].hex()
    observed_semantic_digest = hashlib.sha256(semantic).hexdigest()
    if len(semantic) != EXPECTED_LVAR_CTREE_SEMANTIC_BYTES:
        raise ValueError(
            "lvar-ctree semantic byte count changed: expected "
            f"{EXPECTED_LVAR_CTREE_SEMANTIC_BYTES}, got "
            f"{len(semantic)}")
    if (
        stored_semantic_digest != EXPECTED_LVAR_CTREE_SEMANTIC_SHA256
        or observed_semantic_digest
        != EXPECTED_LVAR_CTREE_SEMANTIC_SHA256
    ):
        raise ValueError(
            "lvar-ctree semantic digest changed: expected "
            f"{EXPECTED_LVAR_CTREE_SEMANTIC_SHA256}, got stored "
            f"{stored_semantic_digest}, recomputed "
            f"{observed_semantic_digest}")
    if (
        len(declarations) != EXPECTED_LVAR_CTREE_COUNTS["declarations"]
        or len(uses) != EXPECTED_LVAR_CTREE_COUNTS["uses"]
    ):
        raise ValueError("lvar-ctree declaration/use count changed")
    return tuple(declarations), tuple(uses)


def read_statement_ctree_manifest() -> tuple[StatementCtreeRow, ...]:
    """Decode the compact IDB-derived complete cit_* statement tree."""
    try:
        compressed = base64.b64decode(
            EXPECTED_STATEMENT_CTREE_ZLIB_BASE64, validate=True)
        raw = zlib.decompress(compressed)
    except (binascii.Error, zlib.error) as exc:
        raise ValueError(
            f"statement-ctree canonical payload is invalid: {exc}") from exc

    if len(raw) != EXPECTED_STATEMENT_CTREE_RAW_BYTES:
        raise ValueError(
            "statement-ctree canonical byte count changed: expected "
            f"{EXPECTED_STATEMENT_CTREE_RAW_BYTES}, got {len(raw)}")
    digest = hashlib.sha256(raw).hexdigest()
    if digest != EXPECTED_STATEMENT_CTREE_RAW_SHA256:
        raise ValueError(
            "statement-ctree canonical digest changed: expected "
            f"{EXPECTED_STATEMENT_CTREE_RAW_SHA256}, got {digest}")

    header = struct.Struct("<4sHHHI")
    if len(raw) < header.size + 32:
        raise ValueError("statement-ctree canonical payload is truncated")
    magic, op_count, relation_count, detail_count, row_count = \
        header.unpack_from(raw)
    if magic != b"STS1":
        raise ValueError("statement-ctree canonical magic changed")
    cursor = header.size

    def read_catalog(count: int, label: str) -> tuple[str, ...]:
        nonlocal cursor
        items: list[str] = []
        for _ in range(count):
            if cursor + 2 > len(raw) - 32:
                raise ValueError(
                    f"statement-ctree {label} catalog is truncated")
            size = struct.unpack_from("<H", raw, cursor)[0]
            cursor += 2
            if cursor + size > len(raw) - 32:
                raise ValueError(
                    f"statement-ctree {label} string is truncated")
            try:
                item = raw[cursor:cursor + size].decode("utf-8")
            except UnicodeDecodeError as exc:
                raise ValueError(
                    f"statement-ctree {label} is not UTF-8") from exc
            cursor += size
            items.append(item)
        if items != sorted(set(items)):
            raise ValueError(
                f"statement-ctree {label} catalog is not canonical")
        return tuple(items)

    ops = read_catalog(op_count, "op")
    relations = read_catalog(relation_count, "relation")
    details = read_catalog(detail_count, "detail")
    if (
        len(ops) != EXPECTED_STATEMENT_CTREE_COUNTS["ops"]
        or len(relations)
        != EXPECTED_STATEMENT_CTREE_COUNTS["relation_catalog"]
        or len(details) != EXPECTED_STATEMENT_CTREE_COUNTS["detail_catalog"]
    ):
        raise ValueError("statement-ctree catalog cardinality changed")

    row_struct = struct.Struct("<QHhHHHBBQQiI")
    expected_size = cursor + row_count * row_struct.size + 32
    if expected_size != len(raw):
        raise ValueError(
            "statement-ctree canonical structure changed: expected "
            f"{expected_size} bytes from header, got {len(raw)}")

    rows: list[StatementCtreeRow] = []
    semantic = bytearray()
    for _ in range(row_count):
        (
            owner,
            ordinal,
            parent_ordinal,
            op_id,
            relation_id,
            detail_id,
            depth,
            flags,
            raw_ea,
            anchor,
            label,
            word,
        ) = row_struct.unpack_from(raw, cursor)
        cursor += row_struct.size
        if (
            op_id >= len(ops)
            or relation_id >= len(relations)
            or detail_id >= len(details)
            or flags & ~1
            or parent_ordinal < -1
            or parent_ordinal >= ordinal
            or anchor & 3
        ):
            raise ValueError(
                f"statement-ctree row metadata is invalid in "
                f"0x{owner:X}:{ordinal}")
        concrete = bool(flags & 1)
        if concrete != (raw_ea == anchor):
            raise ValueError(
                f"statement-ctree concrete/anchor mismatch in "
                f"0x{owner:X}:{ordinal}")
        row = StatementCtreeRow(
            owner=owner,
            ordinal=ordinal,
            parent_ordinal=parent_ordinal,
            op=ops[op_id],
            relation=relations[relation_id],
            detail=details[detail_id],
            depth=depth,
            synthetic=not concrete,
            raw_ea=raw_ea,
            anchor=anchor,
            label=label,
            word=word,
        )
        rows.append(row)
        semantic_line = (
            f"{owner:016X}\t{ordinal}\t{parent_ordinal}\t{row.op}\t"
            f"{row.relation}\t{depth}\t{raw_ea:016X}\t"
            f"{anchor:016X}\t{label}\t{row.detail}\t{word:08X}\n"
        )
        semantic.extend(semantic_line.encode("utf-8"))

    semantic_digest = raw[cursor:cursor + 32].hex()
    observed_semantic_digest = hashlib.sha256(semantic).hexdigest()
    if len(semantic) != EXPECTED_STATEMENT_CTREE_SEMANTIC_BYTES:
        raise ValueError(
            "statement-ctree semantic byte count changed: expected "
            f"{EXPECTED_STATEMENT_CTREE_SEMANTIC_BYTES}, got "
            f"{len(semantic)}")
    if (
        semantic_digest != EXPECTED_STATEMENT_CTREE_SEMANTIC_SHA256
        or observed_semantic_digest
        != EXPECTED_STATEMENT_CTREE_SEMANTIC_SHA256
    ):
        raise ValueError(
            "statement-ctree semantic digest changed: expected "
            f"{EXPECTED_STATEMENT_CTREE_SEMANTIC_SHA256}, got stored "
            f"{semantic_digest}, recomputed {observed_semantic_digest}")
    if len(rows) != EXPECTED_STATEMENT_CTREE_COUNTS["rows"]:
        raise ValueError(
            "statement-ctree canonical row count changed: expected "
            f"{EXPECTED_STATEMENT_CTREE_COUNTS['rows']}, got {len(rows)}")
    return tuple(rows)


